window.__D("text/sefer-hamaamarim-rayatz/c000",{"p":[[2700520054,"<b>יום</b><sup data-n=\"1\">1</sup> טוב של ר\"ה שחל להיות בשבת במקדש היו תוקעין אבל לא במדינה<sup data-n=\"2\">2</sup>, ומפרש בגמ'<sup data-n=\"3\">3</sup> מנה\"מ לחלק לענין תקיעת שופר בין שחל ר\"ה בחול לכשחל להיות",[["1","1","מאמר זה ושמונת המאמרים שלאחריו הם המשך אחד. ההמשך (עד סוף ד\"ה ביום השמע\"צ) נדפס בשינוייםא בקונטרס סט-עב (ספר המאמרים ה'שי\"ת ע' 3 ואילך)ב - עם מראי מקומות והערות בשולי הגליון מכ\"ק אדמו\"ר. בהוצאה זו ניתוספו ע\"י המו\"ל מ\"מ לפסוקים מחז\"ל וכו' (בהערות הממוספרות).\nבגוכתי\"ק כ\"ק אדמו\"ר מוהריי\"צ ב\"עניני מאמרי רצ\"ב\", נרשם: \"יו\"ט של ר\"ה שחל להיות בשבת, ובו ז' פרקים. יב ענינים\". - נעתקו לקמן במקומם.\nפרק א-ז - מיוסד על ד\"ה יו\"ט של ר\"ה תרס\"ו (המשך תרס\"ו ע' א-ד)ג. פרק ט-י - מיוסד על קונטרס עץ החיים פרק א. פרק יא-יד - מיוסד על ד\"ה לך אמר לבי עת\"ר (ספר המאמרים עת\"ר ע' יב ואילך). פרק טו-כב - מיוסד על ד\"ה אחת שאלתי עת\"ר (ספר המאמרים עת\"ר ע' טז ואילך). פרק כג-כז - מיוסד על ד\"ה בסוכות תשבו עת\"ר (ספר המאמרים עת\"ר ע' כג ואילך)ד. פרק כח-ל - מיוסד על ד\"ה חסידים ואנשי מעשה עת\"ר (ספר המאמרים עת\"ר ע' ל ואילך)ה. חלק מפרק לב - מיוסד על ד\"ה ביום השמע\"צ עת\"ר (ספר המאמרים עת\"ר ע' לה ואילך). סוף פרק לב עד סוף פרק לו - מיוסד על ד\"ה פנים בפנים עטר\"ת פרק ב-ד (ספר המאמרים עטר\"ת ע' תקפב ואילך)ו. פרק לז-מ מיוסד על ד\"ה ועשית בגדי קודש תרס\"ה (ספר המאמרים תרס\"ה ע' קסה ואילך)ז. חלק מפרק מא - מיוסד על ד\"ה כבוד מלכותך תרס\"א (ספר המאמרים תרס\"א ע' קעא)ח. סוף פרק מא עד סוף פרק מד - מיוסד על ד\"ה ולקחתם לכם תרס\"א (ספר המאמרים תרס\"א ע' קצא ואילך).\n------------------------------------------------\nא) כמה מהם נסמנו בהערות.\nב) משם נעתקו הקיצורים שכתב בשנת ה'שי\"ת.\nג) עוד מאמרים המיוסדים על ד\"ה הנ\"ל תרס\"ו: ספר המאמרים תרפ\"ד ע' פד ואילך. תרח\"ץ ע' טו ואילך. תרצ\"ט ע' 3 ואילך. תש\"ב ע' 3 ואילך.\nד) עוד מאמר המיוסד על ד\"ה הנ\"ל עת\"ר: ספר המאמרים תרפ\"ה ע' עט ואילך.\nה) עוד מאמרים המיוסדים על ד\"ה הנ\"ל עת\"ר: ספר המאמרים תרפ\"ה ע' פג ואילך. תרפ\"ט ע' 254 ואילך.\nו) עוד מאמרים המיוסדים על ד\"ה הנ\"ל עטר\"ת: ספר המאמרים תרפ\"ד ע' שמב ואילך. תרפ\"ו ע' קיז ואילך. ד\"ה פנים בפנים תרצ\"ג (לקמן ע' תקכא ואילך). ספר המאמרים תרצ\"ז ס\"ע 276 ואילך. תש\"ג ע' 29 ואילך.\nז) עוד מאמר המיוסד על ד\"ה הנ\"ל תרס\"ה: ספר המאמרים תרפ\"ו ס\"ע ער ואילך.\nח) עוד מאמר המיוסד על ד\"ה כבוד מלכותך תרס\"א: ד\"ה לדוד מזמור תרפ\"ב. ד\"ה הנ\"ל תרס\"א מיוסד על ד\"ה אלה מסעי תרל\"ה (ספר המאמרים תרל\"ה ח\"ב ע' שפז ואילך). עוד מאמרים המיוסדים על ד\"ה הנ\"ל תרל\"ה: ספר המאמרים עטר\"ת ע' שמה ואילך. תרפ\"ז ע' קצז ואילך. ה'ש\"ת ע' 39 ואילך."],["2","2","משנה ראש השנה רפ\"ד (כט, ב)."],["3","3","ראש השנה שם."]]],[2700520104,"בשבת, דיו\"ט של ר\"ה שחל להיות בשבת הנה במדינה אין תוקעין, א\"ר חמא בר חנינא כתוב אחד אומר (ויקרא<sup data-n=\"4\">4</sup> ) שבתון זכרון תרועה (ולא תרועה ממש אלא מקראות של תרועה יאמרו, רש\"י) וכתוב אחד אומר<sup data-n=\"5\">5</sup> יום תרועה יהי' לכם, לא קשיא כאן ביו\"ט שחל להיות בשבת, כאן ביו\"ט שחל להיות בחול, ורבנן הוא דגזור בי', (ביו\"ט שחל להיות בשבת שלא יתקעו בשופר, וטעמי') כדרבה, דאמר רבה הכל חייבין בתקיעת שופר ואין הכל בקיאין בתקיעת שופר גזירה שמא יטלנו בידו וילך אצל הבקי ללמוד ויעבירנו ד' אמות בר\"ה. ולכאו' א\"מ<sup data-n=\"6\">6</sup> מה ראו חז\"ל לעקור מ\"ע דאורייתא משום חשש גזירה בעלמא, והלא החשש הוא להדיוטים<sup data-n=\"7\">7</sup> וקלי הדעת<sup data-n=\"8\">8</sup> ואיך מנעו המצוה לגמרי מכמה צדיקים גדולים וטובים, וידוע דמצות שופר היא מצוה רמה ונשאה מאד<sup data-n=\"9\">9</sup>, דהנה כל המצות שבחודש זה הם מצות כללות<sup data-n=\"10\">10</sup>, וכדאי' במד\"ר (ויקרא פכ\"ט<sup data-n=\"11\">11</sup> ) בחודש השביעי|4 ומפרשים שביעי ל' שובע זאַט, בחודש השביעי אַ זאַטער חודש, שהוא משובע בכל, גתות בתוכו, דגתות הם אוצרי תבואות ופירות, דאז הוא זמן אוסף התבואה והפירות, וישראל שרוים בנחת ברוב טוב, ואז מקבלין עליהם עול מל' שמים<sup data-n=\"12\">12</sup> מקרב ולב עמוק, דזהו\"ע העבודה בר\"ה לקבל עלינו עול מלכותו ית' בלימוד התורה ובעבודה שבלב זו תפלה<sup data-n=\"13\">13</sup>, ובקיום המצות במסירה ונתינה ובחיות רב, וקבלה זו היא בשמחה פנימיות, דענין הבכי' בר\"ה הוא התשובה על העדר העבודה כדבעי למהוי בשנה העברה, והקבלה על להבא היא בשמחה, אמנם להיותו יום דין הנה השמחה היא מכוסה ובהעלם<sup data-n=\"e1\">*</sup>, ומה שבגילוי הוא הקבלת עול, וקבלת עול זה הוא ברצון פנימי, וזהו דזמן ר\"ה הוא בזמן אוסף התבואה והפירות להורות על קבלת עומ\"ש מתוך הרחבה, דאינו דומה הקבלת עול דעבד אם הוא מתוך הדוחק וההכרח, או שהוא מתוך ההרחבה והקירוב, והוא בחי' יש בן",[["4","4","אמור כג, כד."],["5","5","פינחס כט, א."],["6","6","ראה לקו\"ת דרושים לר\"ה ד\"ה להבין המשנה (נו, א ואילך). ד\"ה הנ\"ל בסידור שער התקיעות (רמ, ג ואילך). ועוד."],["7","7","כ\"ה (\"והלא החשש הוא כו'\") בלקו\"ת שם ובהמשך תרס\"ו שבהערה 1. וברד\"ה יו\"ט של ר\"ה תש\"ג: \"ועוד זאת שהחשש הוא להדיוטים כו'\". - ראה לקוטי שיחות ח\"ז ע' 52 ובהערה 25 שם."],["8","8","ויש לומר: הדיוטים - שאין יודעים דיני תק\"ש, וקלי הדעת - שלכן יש לחשוש שיעבירו ד\"א ברה\"ר (ד\"ה יו\"ט של ר\"ה דער\"ה תשל\"ג (ספר המאמרים מלוקט ח\"ג ע' רצג הערה 7. בהוצאה החדשה - ח\"א ע' יז))."],["9","9","ראה לקו\"ת שם: \"ובפרט מצות שופר ולולב כו' שנוגעים עד רום המעלות\"."],["10","10","בספר המאמרים ה'שי\"ת שבהערה :1 כללו'."],["11","11","פיסקא ח."],["12","12","ראה ראש השנה טז, א. לד, ב. לקו\"ת שם נו, ב ואילך. אוה\"ת דרושים לר\"ה ס\"ע א'שנא ואילך. ובכ\"מ."],["13","13","תענית ב, א."],["e1","*","<b>מכוסה ובהעלם:</b> ראה לקו\"ת ד\"ה שוש אשיש [מז, א. מח, ד] ובכ\"מ בפירוש וגילו ברעדה."]]],[2700520154,"שהוא עבד<sup data-n=\"e2\">*</sup>, וכמו שהי' בקי\"ס דמלכותו ברצון קבלו<sup data-n=\"14\">14</sup>, ואדרבה יש יתרון בהעבודה דעכשיו, דאז הי' התגלות העצמות ית'<sup data-n=\"15\">15</sup>, ועכשיו בזמה\"ג הנה העבודה היא ביותר, ולכן הנה גם אם עדיין חסרים ההרחבה הנה מצד האמונה הפשוטה והבטחון הגמור באבינו מלכנו אשר הוא ית' יתן שפע רב בברכה מרובה, הנה הקבועמ\"ש דר\"ה הוא כאלו מתוך ההרחבה, וזהו גתות בתוכו. ברכות בתוכו, דמזונותיו קצובות לו מר\"ה<sup data-n=\"16\">16</sup> בשפע ברכה על כל השנה, ועיקר הברכה הוא לבד זאת שהשפע תהי' בריבוי הנה יהי' במנוחה באופן שיוכל לעסוק בתורה ועבודה. כפור בתוכו, וכתיב<sup data-n=\"17\">17</sup> לפני הוי' תטהרו, ועצומו של יום מכפר<sup data-n=\"18\">18</sup> שזהו הוראה על קירוב פנימי. סוכה בתוכו שהוא זמן עת רצון בתנועה של שמחה ובו השפעת השמחה על כל השנה בשפע רב. דהנה ר\"ה ויוהכ\"פ נקראים ימים נוראים<sup data-n=\"19\">19</sup>, שהימים מצד עצמם הם נוראים, ורק בחסד הוי' עלינו הופך לנו מדה\"ד למדה\"ר<sup data-n=\"20\">20</sup>, אבל מ\"מ הנה זה גופא בא בדין ומשפט כפי אופן התשובה על העבר וכפי אופן הקבלה על להבא, אבל בחגה\"ס הוא וימינו תחבקני<sup data-n=\"21\">21</sup> בגילוי השמחה העליונה. לולב וערבה בתוכו, דלולב הוא הוראה דדן נצח<sup data-n=\"22\">22</sup>, וכדאי' במד\"ר (ויק\"ר פ\"ל פיסקא ב') שישראל יוצאין ולולביהן ואתרוגיהן בידן אנו יודעין דישראל אינון ניצוחייא, שזכו בדין, וערבה אין בהם לא טעם וריח<sup data-n=\"23\">23</sup> אלא שהם גדילים באחדות<sup data-n=\"24\">24</sup>, להורות דלכל<sup data-n=\"25\">25</sup> השובע לכל השנה אשר נמשך בחודש השביעי הוא מפני הביטול והאחדות שבישראל, דכל ישראל הם שוים בענין קיום התומ\"צ<sup data-n=\"26\">26</sup>. וזהו לולב וערבה שבמהותם וענינם העצמי הם רחוקים זמ\"ז, דלולב הוא לו לב<sup data-n=\"e3\">*</sup>, ובכוונת המצוה ביחוד העליון הנה לולב הוא סוד המשכת בחי' דעת ועוד למעלה יותר, וההמשכה היא בבחי' יסוד, שהוא בקו האמצעי<sup data-n=\"27\">27</sup>, וערבה הם אנשים פשוטים|26,",[["14","14","ברכות ק\"ש של ערבית. וראה אבודרהם שם."],["15","15","ראה לקו\"ת צו יד, ג."],["16","16","ראה ביצה טז, א."],["17","17","אחרי טז, ל."],["18","18","ראה רמב\"ם הל' תשובה פ\"א ה\"ג-ד. וראה לקוטי שיחות ח\"ד ע' 1150 ואילך."],["19","19","ראה לקו\"ת ר\"פ עקב (יג, ג). ובכ\"מ."],["20","20","ראה ויק\"ר פכ\"ט, ג. ד. ו. י."],["21","21","שיר השירים ב, ו. ראה לקו\"ת דרושים לשמע\"צ פז, סע\"א ואילך. ובכ\"מ."],["22","22","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שבהערה :1 אשר דידן נצח."],["23","23","ויק\"ר פ\"ל, יב."],["24","24","ראה מאמרי אדמו\"ר הזקן תקס\"ח ח\"א ע' תמז. סידור עם דא\"ח רסד, ד ואילך. המשך וככה תרל\"ז פפ\"ז. פצ\"ג ואילך. וראה לקוטי שיחות חכ\"ט ע' 224 ואילך."],["25","25","כ\"ה בכתי\"ק ובהעתקה. ובספר המאמרים ה'שי\"ת שבהערה :1 דכל."],["26","26","נתבאר בלקוטי שיחות שם ע' 223 ואילך."],["27","27","ראה משנת חסידים מסכת ימי מצוה וסוכה פ\"ה. וראה המשך וככה תרל\"ז פפ\"ד. פפ\"ז. ועוד."],["e2","*","<b> בן שהוא עבד:</b> ראה תניא פמ\"א [נז, א]. לקו\"ת פ' בלק סוף הביאור ע\"פ לא הביט [עג, א]. שם פ' ראה ד\"ה וכל בניך פ\"ב [כט, ד]. ד\"ה א\"ר עקיבא דש\"פ נח תרס\"ז (מהמשך ר\"ה תרס\"ו [ס\"ע שפ ואילך]), ועוד."],["e3","*","<b>לו לב:</b> ת\"ז סוף ת\"ו [כג, א]. וראה ג\"כ יאיר נתיב למאורי אור ל, ה."]]],[2700520204,"דקיום המצות הוא רק באמונה פשוטה. וזהו ערבה ל' עריבות ומתיקות וכמ\"ש (מלאכי ג' ד') וערבה לד' וגו', דבאמת זהו תכלית ועיקר הכל, אבל מ\"מ הלא חסרים הידיעה וההשגה באלקות, הנה בחדש השביעי לולב וערבה בתוכו דמאיר<sup data-n=\"28\">28</sup> עיני שניהם הוי'<sup data-n=\"e4\">*</sup>, והיינו דהמצות הללו חלוקים המה מהמצות דכל השנה שהן מצות כללות|10, ובפרט מצות שופר שמעורר וממשיך פנימית ועצמות אוא\"ס ב\"ה, דמצות שופר בכוונתה הרוחנית הו\"ע התשובה<sup data-n=\"29\">29</sup> דזהו\"ע התקיעה הראשונה שהוא צעקה בקול פשוט שזהו מצד ההתעוררות והתפעלות פנימי שבנפש שבא בהתגלות הלב בקול פשוט דוקא.\n<span data-k=\"ks\"><b>קיצור.</b> יקשה למה דחו מ\"ע מפני חשש גזירה דטלטול בר\"ה, ויבאר דחדש השביעי שבע במצות כוללים, ובו זמן אוסף התבואה דישראל שרוים בטוחים באמונת שנה טובה, בר\"ה ויו\"כ השמחה פנימי' על הקירוב לד' בהעלם, והקבעמ\"ש בגילוי, ימים נוראים, ובחה\"ס השמחה בגילוי, לולב וערבה בעלי השכלה ועבודה ופשוטים כאחד, תקיעות תשובה ותקיעה ראשונה הצעקה בקול פשוט<sup data-n=\"30\">30</sup>.</span>\n<b>ענינים.</b> א ר\"ה ויו\"כ, א) בזמן אוסף התבואה, ב) השמחה בהעלם והקבע\"ו בגילוי, ג) ימים נוראים. ב לולב וערבה עובדים ופשוטים.\nב) <b>וביאור</b> הענין הוא, דהנה יש התפעלות פנימי דנפש הבא' בעבודה, והיא העבודה דרעו\"ד<sup data-n=\"31\">31</sup> דענינו שהוא בהמשכה ובהתעוררות התפעלות פנימי דנפש, וההתפעלו' הלזו עם היות שהיא התפעלות פנימי דנפש אבל כל ענין אופנה, היינו האופן של הרצוא הלזה הוא בחשאי דוקא שלא ברעש כלל, וכמו עבודת הכהנים וכדאי' בזהר דכהנא בעובדא וברעו\"ד<sup data-n=\"e5\">*</sup> שהוא בחשאי, משא\"כ התעוררות ההתפעלות פנימי שבנפש דתשובה הוא בצעקת הקול דוקא. והיינו דשניהם, הן תשובה והן רעו\"ד הם בבחי' התפעלות פנימי דנפש, אמנם הם חלוקים באופן ההתפעלות פנימי שבהם, דברעו\"ד הנה ההתפעלות פנימי הוא ברצוא אבל ההמשכה הוא בחשאי, ובתשו' הנה ההתפעלות פנימי הוא ברצוא ובאה ברעש ובצעקת הקול. וטעם התחלקו' אופניהם הוא לפי שהם חלוקים בסיבותיהם ועניניהם. ומה שאומרים סיבותיהם לפי שלכל אחד מהם ישנו שני סיבות הגורמים את ההתפעלות פנימי שבנפש, דכל התפעלות היא באה בסיבת איזה התעוררות,",[["28","28","משלי כט, יג."],["29","29","ראה לקמן פ\"ה. ספר המאמרים תרח\"ץ שבשוה\"ג להערה 1."],["30","30","הקיצור דשנת ה'שי\"ת: יקשה איך בטלו תק\"ש מחשש גזירה, ובפרט דמצוות חודש השביעי הם כלליות. יפרש גתות ברכות כפור סוכה ולולב וערבה בתוכו. קבלת עול דר\"ה מתוך הרחבה."],["31","31","בהבא לקמן - ראה ספר המאמרים תרח\"ץ, תרצ\"ט ותש\"ב שבשוה\"ג להערה 1."],["e4","*","<b>עיני שניהם הוי':</b> הכוונה לדרז\"ל ע\"פ זה (תמורה טז, א)."],["e5","*","<b>דכהנא .. דלבא:</b> ראה זח\"ג לט, א. פח, ב. קעז, ב."]]],[2700520254,"דההתעוררות ההיא היא סיבת ההתפעלות, וההתעוררות עצמה היא ג\"כ מסובבה מאיזה סיבה כללית המביאה את ההתעוררות, ובתשובה ורעו\"ד בשתיהם יש שני סיבות האלו שהם סיבה פרטית וקרובה וסיבה כללית, והשני סיבות האלו הם חלוקי' במהותם ובמילא הם חלוקים בענינם היינו בהמבוקש שלהם, ולהיות דרעו\"ד ותשובה חלוקים זמ\"ז בסיבתם הכללית והפרטית, היינו סיבה הקרובה, וחלוקים במבוקשם, ה\"ה חלוקים גם באופנם. דהנה רעו\"ד הרי הסיבה הכללית היא הקירוב לאוא\"ס ב\"ה, והסיבה הפרטית שהיא באה מהכללית הוא הרגש האוא\"ס שמרגיש בנפשו, דרעו\"ד באה עפ\"י העבודה דוקא, היינו בסדר והדרגה, דבעניני התבוננות הרי יש בזה כמה עניני חילוקי מדריגות, דכשם שיש<sup data-n=\"e6\">*</sup> התבוננות המיוחדה לאהבה והתבוננות המיוחדה ליראה כן יש התבוננות שההתבוננות שלו הוא בהאור דממכ\"ע ויש שההתבוננו' שלו הוא בהעניני' דסוכ\"ע, הנה כאשר ההתבוננות שלו הוא בהענין איך כי עצמות אוא\"ס ב\"ה מופלא ומרומם מעולמות, ומתבונן בזה באריכות הענין בכל פרטיו ומבינו ומשיגו בטוב ובמילא הרי בא לידי זה שנרגש בנפשו, עס דער הערט זעך באַ אים דער רוממות והפלאת אוא\"ס, אבל אינו בא בגילוי בנפשו מפני שאין נשמתו כלי לזה שיאיר האור הזה בפנימיות בגילוי בנפש, כ\"א שהוא נרגש בכללותו, ומ\"מ הנה עי\"ז נעשה הרצוא להכלל באוא\"ס, והיינו דזהו המבוקש שלו להכלל באוא\"ס ב\"ה, א\"כ הנה הסיבה הכללית הוא הקירוב לאוא\"ס ב\"ה מה שהמסובב מזה הוא ההרגש הכללי דהפלאת ורוממות אוא\"ס ב\"ה, וסיבה זו מביאה ענין הרצוא, ולזאת הנה הרצוא הבא בסיבת הקירוב הרי עצם ענין הרצוא ג\"כ ענינה הוא בחי' קירוב מה שרוצה להכלל, משא\"כ בתשובה עם היות דגם היא באה בסיבה כללית ופרטית כמו ברעו\"ד, ולזאת היא ג\"כ בהתפעלות פנימי דנפש, אבל היא חלוקה בעצם מהות סיבתה ולכן חלוקה בענינה שהוא המבוקש. דהנה תשו' הרי סיבתה הכללית הוא הריחוק, מה שהוא מרוחק מאלקות, דזהו היפך ממש מכמו הסיבה הכללית דרעו\"ד, דרעו\"ד הנה הסיבה הכללית הוא הקירוב לאלקו', ובתשו' הנה הסיבה הכללית הוא מה שהוא מרוחק מאלקות, וכתיב (ש\"ב י\"ד י\"ד) וחשב מחשבות לבלתי ידח ממנו נדח<sup data-n=\"32\">32</sup>, דגם מי שהוא נדח מצ\"ע, והיינו דכאשר בבחירתו ח\"ו עוזב דרכי התורה והמצוה, הנה גם הוא לא יהי' נדח, והוא שיעשה תשובה, וכידוע דכאשר האדם ח\"ו נוטה מדרכי התורה והמצוה מעוררים אותו מלמעלה שיעשה תשובה, והתעוררות זו היא בכמה אופנים שונים כפי אופן מעמדו ומצבו בריחוקו מאלקות, והתעוררות זו היא לאו דוקא באלו אשר ר\"ל נתרחקו לגמרי, אלא גם אלו אשר הם חלושים בעבודה ואינם עוסקים בה, וכידוע דתשובה אין הכוונה על חטא ועון<sup data-n=\"e7\">*</sup>, אלא גם מי שאינו מקורב או שהוא מרוחק בסיבת העדר העבודה, ומעוררים אותו",[["32","32","ראה תניא ספל\"ט. הל' ת\"ת לאדמו\"ר הזקן פ\"ד ס\"ג."],["e6","*","<b>דכשם שיש:</b> ע\"ד התבוננות לאהוי\"ר ראה בקונטרס העבודה [ע' 17 ואילך] ובדרושים המובאים שם."],["e7","*","<b>דתשובה אין .. ועון:</b> תו\"א ר\"פ ויחי [מה, סע\"א] ובכ\"מ."]]],[2700520304,"מלמעלה שיתקרב, הנה התעוררות הלזו סיבתה הוא הריחוק, והגם דההתעוררות עצמה באה בתנועה של קירוב, אבל סיבתה הוא ריחוק, ולכן הנה ההתעורות עצמה אין זה מצד ההרגש דאוא\"ס כמו שהוא בההתעוררות דרעו\"ד שהוא מה שמרגיש אוא\"ס ב\"ה, כ\"א הסיבה הכללית דתשובה הוא הריחוק, ובסיבת הריחוק הנה בא ההתעוררות מלמעלה, והוא מה שנעשה לו צר מאד מה שנתרחק מאלקות, עס ווערט אים ניט גוט און איינג פון דעם ואָס ער איז אַ מרוחק פון געטליכקאַייט.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר ההפרש שבין תשובה לרעו\"ד, והגם דשניהם התפעלות פנימי דנפש ברצוא, מ\"מ תשובה ברעש ורעו\"ד בהמשכה ובחשאי, ויבאר כי כל התפעלות באה בסיבת התעוררות המסובבה מסיבה כללית, דברעו\"ד הסיבה כללית הוא הקירוב לאוא\"ס והמסובבה הוא הרגש אוא\"ס ולזאת המבוקש להכלל באוא\"ס, ובתשובה הסיבה כללית הוא הריחוק, והמסובבה היא התעוררות הלא טוב דריחוק<sup data-n=\"33\">33</sup>.</span>\n<b>ענינים.</b> ג רעו\"ד ותשובה התפעלות פנימי וחלוקים בסיבותיהם ואופניהם.\nג) <b>והנה</b> הגם דגם בזה שהוא מצטער ומיצר לו על ריחוקו מד' הרי בזה גופא יש לו הרגש אלקו', הנה ההרגש הזה מה שמצטער על ריחוקו מד' זהו רק מה שרע ומר עזבו את ד'<sup data-n=\"34\">34</sup>, שההרגש הוא רק בהלא טוב מריחוקו, ואינו דומה לרעו\"ד כלל, דברעו\"ד הלא סיבתה הוא הקירוב, והוא מה שמרגיש ההפלאה והעילוי דאוא\"ס, ומזה הוא התפעלות נפשו, איז דאָך דאָס אַלץ אַ תנועה פון יע, ער איז בכלל אַ מקורב צוא אלקות, און דער קירוב זאַיינער איז מצד עבודה, ועבודה תמידית בסדר והדרגה, און פון דעם קומט ער צוא דעם הרגש הפלאת ורוממות אוא\"ס ב\"ה בנפשו, איז דאָך דיא כללות התנועה פון רעו\"ד אַ תנועה פון יע, אבל תנועת התשובה באה בסיבת הריחוק, והיינו מה שע\"י ההתעוררות רוח ממרום נעשה לו נוגע מאד בעומק לבבו ריחוקו מד', ומזה נעשה ההתפעלות הגדולה בצעקה פנימית מקרב ולב עמוק, איז דאָס דאָך אַ תנועה פון ניט, והיינו עם איז זייער ביטער און זייער טוטויי דער ניט, היינו דער ריחוק, והגם שיש בזה ג\"כ ההמשכה והרצוא לאלקות, דער ציען זעך צוא געטליכקייט, דעתה כאשר שב הנה הוא נמשך לאלקות ולעניני אלקות, שהרי נשתנה בפועל, דהשינוי לטוב בעבודה בפועל הוא קירובו לאלקות ואָס ער ציט זעך צוא געטליכקאַייט, אמנם בעומק הענין הרי המשכה זו אין ענינה ענין הקירוב, דאם ענינה הי' ענין הקירוב הנה אז הרי הי' המבוקש שלו להכלל באוא\"ס ב\"ה, בדוגמת דבר כמו שהוא בהתנועה דרעו\"ד, דברעו\"ד דהסיבה הכללית הוא הקירוב לאוא\"ס והסיבה הפרטית הוא הרגש הפלאת ורוממות אוא\"ס הרי מזה נעשה המבוקש להכלל באוא\"ס, אבל בהתנועה דתשובה ענין ההמשכה הוא מה שרוצה להיות מקורב לאלקות,",[["33","33","הקיצור דשנת ה'שי\"ת: ברעו\"ד ההתפעלות פנימי הוא ברצוא ובחשאי, בתשובה ברצוא ובצעקת הקול. יפרש הטעם, כי סיבות הרעו\"ד הם הקירוב והרגש האוא\"ס, סיבות התשובה הריחוק והרגשו."],["34","34","ע\"פ ירמי' ב, יט."]]],[2700520354,"וגם זה מה שהוא רוצה להיות מקורב לאלקות הנה עיקר ופנימי' ענינו הוא לא הקירוב כ\"א אך ורק שלא יהי' במקום הריחוק, ואָס דאָס, אייף זאַיין במקום הריחוק, דאָס ויל ער ניט בכל תוקף עוז, ובמילא ישנו ההמשכה והרצוא לאלקות, והמבוקש שנעשה מזה הוא רק ענין הנתינה ומסירה שמוסר א\"ע לאלקות ולקיים רצונו ית', והיינו דתשו' הרי סיבתה הוא הריחוק ולזאת הנה גם ענינה הוא לא הקירוב עיקר כ\"א כל המבוקש שלו הוא אך ורק להתרחק מהלא טוב, ונמצא דתנועה דתשובה איז אַלץ אין אַ תנועה פון ניט, שהוא היפך התנועה דרעו\"ד כנ\"ל. ומאחר דתשו' ורעו\"ד חלוקים בסיבתם וענינם ה\"ה חלוקים גם באופנם, היינו באופן המבוקש שלהם, דהגם דשניהם ברצוא ובהתפעלות פנימי דנפש, מ\"מ מתחלקים בזה דרעו\"ד הוא בחשאי שלא ברעש כלל, ותשובה הוא מרוצה ברעש ובהתגלות הלב בצעקה בקול. דהרעו\"ד דסיבתה הוא מצד הקירוב שהוא הרגש אוא\"ס הנה ענינו הוא ג\"כ ענין הקירוב שרוצה להכלל, ולכן בא באופן כזה שהוא בחשאי המורה על המשכה פנימיות, זייער טיף און זייער איויניג<sup data-n=\"35\">35</sup>, וכמו שאנו רואין בטבעי בנ\"א דכאשר האדם יש לו איזה קירוב והמשכה פנימיות בהתקשרות גדולה לאיזה ענין, ואָס ער איז אין דעם אָנגיבונדין מיט דיא גאַנצע עצמיות זאַיינע, הרי ההמשכה הזאת היא בעומק תוכיות פנימיות לבב, ודבוק בה תמיד, והוא רק בחשאי, ואינו מדבר בזה כלל, באַ אים איז דער ענין אַזיי טייער און פאַרבונדין מיט זאַיין עצמות, אַז ער שטייט נאָר אין אַ תנועה פון המשכה ובחשאי דוקא, וכן הוא ברעו\"ד שזהו מה שפנימיות לבבו מקושר בהתקשרות פנימי בקירוב, לכן הוא בחשאי, אבל תשו' דסיבתה הוא הריחוק וענינה אינה ענין הקירוב כ\"א שלא להיות בריחוק לזאת היא באה בהתגלות בצעקה בקול פשוט דוקא, והמשל בזה במי שר\"ל יושב בבית אסורים ונדון למיתה, דאז הנה התעוררות הכוסף והתשוקה אל החיים הוא עוד יותר, והיינו דאז נרגש, יעמולט דער הערט זעך היוקר דחיים, ונעשה לו רע ומר מאד מצבו כמו שהוא, שמההרגש דלא טוב, פון דעם דער פילין דעם ניט גוט, איז הגם שמזה נעשה עוד יותר הרגש יוקר החיים, אבל אצלו גם ההרגש הזה הוא בהתנועה דהלא טוב, וכאשר בא לידי איזה אפשרות להמלט ולהציל את חייו, הרי בריחה זו היא במרוצה גדולה ובצעקה בהתגלות הלב, והגם דמרוצתו היא אל החיים, ומ\"מ הנה העיקר בזה הוא הבריחה מהמות והסכנה, וכן הוא בענין התשובה דע\"י ההתעוררות שלמעלה הרי בא לידי ידיעה שהוא במקום הריחוק, וח\"ו במקום המות ר\"ל, והיינו דאז נרגש אצלו דמקום הריחוק הוא מקום המיתה ר\"ל, דתחלה קודם ההתעוררות אינם מרגישים זאת, אבל ע\"י ההתעוררות הנה נרגש אצלו דמקום הריחוק הוא מקום מיתה רוחניות ר\"ל, ולזאת הנה תנועת התשובה באה בצעקה ובקול גדול כבורח מן הסכנה.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דברעו\"ד הוא הרגש הקירוב און ער שטייט אין אַ תנועה פון יע, ובתשובה רק הרגש הלא טוב, און ער שטייט אין אַ תנועה פון ניט, ולזאת חלוקים במבוקשם, דברעו\"ד המבוקש להכלל ובא בהמשכה בחשאי כאדם הנמשך </span>",[["35","35","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שבהערה :1 אינוויניג."]]],[2700520401,"<b></b><span data-k=\"ks\"> אחרי התקשרות פנימיות נפשו, והמבוקש דתשובה לצאת מהריחוק כאדם הבורח מסכנת מות שהוא ברעש<sup data-n=\"36\">36</sup>.</span>\n<b>ענינים.</b> ד רעו\"ד ותשובה חלוקים בתנועתם ובמבוקשם.\nד) <b>והנה</b> בתשובה יש עוד אופן, והוא ג\"כ בחשאי, והיינו דכאשר כללות מעמדו ומצבו נוגע לו, רירט אים אָן בפנימיות יותר שאין בכחו לצעוק, והו\"ע צעקת הלב שלמעלה מצעקת הקול<sup data-n=\"37\">37</sup>, דבזה גופא יש מדריגות חלוקות, ובפרטיות המדריגות המרומזים בהתנועות דשופר הם תקיעה שברים תרועה, דתקיעה הוא צעקת הקול כנ\"ל, ושברים ותרועה הוא צעקת הלב דגנוחי גניח וילולי יליל<sup data-n=\"38\">38</sup>, דבצעקת הקול הגם שהוא מקרב ולב עמוק מ\"מ ניכרים הברת אותיות שמוציא בצעקתו, ובצעקת הלב גנוחי גניח וההברות אינם ניכרים במה שהוא מדבר, ורק קול הברה בבכי' רבה, ויש עוד אופן דגם הקול בלתי נשמע כלל, וכמ\"ש (שמ\"א א'<sup data-n=\"39\">39</sup>) גבי חנה והיא מרת נפש ותתפלל על ד' ובכה תבכה וכתיב (שם<sup data-n=\"40\">40</sup>) וחנה היא מדברת על לבה רק שפתי' נעות וקולה לא ישמע, דזהו ילולי יליל בקלא פנימאה דלא אשתמע<sup data-n=\"41\">41</sup>. דהנה כתיב (איכה ב' י\"ח) צעק לבם אל ד' חומת בת ציון הורידי כנחל דמעה וגו', דע\"י התשובה בצעקת הלב מורידים את החומה דלעו\"ז<sup data-n=\"42\">42</sup>. דהנה יש חומה דקדושה וכמ\"ש (שה\"ש<sup data-n=\"43\">43</sup> ) אני חומה ואמרז\"ל (פסחים דפ\"ז ע\"א) א\"ר יוחנן אני חומה זו תורה, ויש חומת ירושלים, שהיא החומה דיראת שמים, דירושלים הוא יראה שלם<sup data-n=\"e8\">*</sup>, ויש להבדיל החומה דלעו\"ז, והיא החומה המפסקת בין ישראל לאביהם שבשמים, ואָס בא יעדערין איז פראַן זאַיין חומה ואָס איז מפסיק בינו לבין אבינו שבשמים. דחומה נעשית מאבנים ולבנים, דאבנים הם בידי שמים שהם האותיות דתורה ותפלה, ולבנים בידי אדם<sup data-n=\"44\">44</sup>, והם האותיות דדברים בטלים או ח\"ו דיבור האסור<sup data-n=\"45\">45</sup>,",[["36","36","הקיצור דשנת ה'שי\"ת: ימשיך דברעו\"ד הוא מקורב ובתנועה פון יע, בתשובה הוא מרוחק ובתנועה פון ניט, עיקר ענינה להתרחק מהלא טוב. ימשיל בהנמצא בסכנה דהעיקר אצלו הבריחה מהסכנה ונעשה במרוצה ובהתגלות."],["37","37","ראה לקו\"ת נצבים מד, ב ואילך. מאמרי אדמו\"ר האמצעי דברים ח\"ג ע' תשסו ואילך. ספר המאמרים תרנ\"ג ע' קנח ואילך."],["38","38","ראש השנה לג, ב. לד, א."],["39","39","פסוק י."],["40","40","פסוק יג."],["41","41","ראה זח\"א נ, ב. רי, א."],["42","42","ראה שערי אורה ד\"ה בכ\"ה בכסלו פי\"א-יב."],["43","43","ח, י."],["44","44","ראה רש\"י ע\"ז מו, א - ד\"ה לבינה."],["45","45","ראה תו\"א משפטים עז, ג ואילך. אוה\"ת שם ע' א'רעג ואילך. ספר המאמרים תרכ\"ו ע' י ואילך. תרנ\"ה ע' צה ואילך."],["e8","*","<b>יראה שלם:</b> נתבאר בלקו\"ת ד\"ה אלה פקודי פ\"ד [ד, א]. פ' ראה ד\"ה וכל בניך פ\"ב [כט, ד]. ובכ\"מ. - להעיר מתוד\"ה הר (תענית טז, א) והוא ע\"פ ב\"ר פנ\"ו, י."]]],[2700520448,"דהאותיות של הדיבורים האלו נעשו מחיצה לגבי למעלה, כי אין דבר המפסיק לגבי למעלה כ\"א הרע<sup data-n=\"e9\">*</sup>, והוא המחיצה שישנו לכל אחד ואחד המחיצה אשר בונה מהאותיות של דברים בטלים שלו, דהאותיות האלו עושים כתמים בנפש, ותיקונה הוא ע\"י כף הקלע ר\"ל, דענין דכף הקלע הוא<sup data-n=\"46\">46</sup> מה שקולעים את הנפש מסוף העולם ועד סופו כדי להוציא האבק שנתקבץ בו<sup data-n=\"47\">47</sup> מהאותיות דדברים בטלים<sup data-n=\"48\">48</sup>, וכמו הבגד דכשרוצים לכבסו הנה תחלה מנערים אותו מן האבק שנקבץ בו, ואח\"כ מכבסים אותו, וכן הוא בעונש הנפש ר\"ל דמנערים אותו להוציא אלו האותיות דדב\"ט. והעצה לביטול האותיות האלו הוא ע\"י ריבוי אותיות דתורה ואמירת תהילים, ואשר לזאת טוב לכל אדם להיות דברי תורה חקוקים בכח זכרונו<sup data-n=\"49\">49</sup>, וביותר אותיות שבתורה, כמו תושב\"כ וספר תהלים וכו', ולהיות בקי בהם בע\"פ בדיוק רב בהאותיות כנקודתם ובכל רגע פנוי' מעניניו יחשוב ויהרהר בהם, דבריבוי האותיות דקדושה מבטלים האותיות דדב\"ט. אמנם זהו לאחר הביטול ושבירת החומה דלעו\"ז אשר הקים בהאותיות דדב\"ט שלו, והיינו דתחילה צריכים לשבור את החומה שנעשו מהאותיות דדב\"ט, דשבירת החומה והפשרת<sup data-n=\"e10\">*</sup> הלבנים הוא ע\"י המים, ומים רותחין דוקא, דענינם בעבודה הוא זיעה של מצוה ודמעות של תשובה. והנה כאשר ישים האדם אל לבו במעמדו<sup data-n=\"50\">50</sup> ומצבו ואופן הנהגתו בריבוי דב\"ט אשר הוא חושב ומדבר, ויתבונן בגודל ההיזק המגיע לו מזה, הנה יתעורר בהתעוררות עצומה ויבכה בבכי רב, אשר בזה הוא שובר החומה דלעו\"ז, וכאשר עושה הסכם חזק בנפשו להרגיל א\"ע להיות ד\"ת חקוקים במוחו ומקיים כן, הנה בזה הוא בונה החומה דתורה ויר\"ש. וזהו צעק לבם אל ד', שהוא צעקת הלב בקלא פנימאה דלא אשתמע, שזה מעורר רחמים רבים למעלה שירחמו עליו. דהנה אנו רואים במוחש דכאשר אדם צועק בקול מר צורח ובבכי' גדולה, הנה כל השומע צעקתו מרחם עליו, ומ\"מ הנה כאשר שומעי' דברי צעקתו הרי יש מקום לבעל דין לחלוק ולאמר אשר לא כצעקתו, אבל כאשר הוא צועק מפנימיות עומק לבבו וגנוחי גניח וילולי יליל אז הכל מרחמים עליו. דזהו הענינים הכללים שבתנועת התשובה שהיא מצות תקיעת שופר ברוחניות.\n<b></b><span data-k=\"ks\">קיצור. יבאר דבתשובה יש ג\"כ אופן חשאי והוא צעקת הלב הבא מההתבוננות מההיזק הגדול שגורם לנפשו בהדברים בטלים שלו שמהם נעשה חומה </span>",[["46","46","ראה גם לקו\"ת פינחס עה, ג. סהמ\"צ להצ\"צ קמב, א ואילך. ספר המאמרים תרל\"ה ח\"ב ע' שעג."],["47","47","ראה גם לקמן ע' תיט. סד\"ה שובה ישראל תר\"ץ. ספר המאמרים תרח\"ץ ע' ריב. ד\"ה אין עומדין להתפלל דש\"פ וישב ה'ש\"ת פ\"ד (ספר המאמרים קונטרסים ח\"ב תמב, א)."],["48","48","ראה תניא פ\"ח (יג, א)."],["49","49","ראה לקו\"ת ס\"פ קדושים (ל, ד). וראה לקוטי שיחות חלק יד ע' 237."],["50","50","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שבהערה :1 מעמדו."],["e9","*","<b>כ\"א הרע:</b> אגרת התשובה פ\"ה."],["e10","*","<b>והפשרת:</b> מלשון התרגום (שמות טז, כא) ונמס ופשר. וראה ערוך ערך פשר השני."]]],[2700520490,"<b></b><span data-k=\"ks\">מפסקת בינו לבין אב\"ש ית', ושבירתה ע\"י דמעות דתשובה ויבאר במעלת צעקת הלב על צעקת הקול, דשניהם בתנועת התשובה שהיא הנשמה דמצות שופר<sup data-n=\"51\">51</sup>.</span>\n<b>ענינים.</b> ה חומה דדברים ושבירתה בדמעות דתשובה. ו צעקת הלב נשמת מצות שופר.\nה) <b>ונמצא</b> דשופר הו\"ע התשובה שבאה באופנים שונים, וכמ\"ש הרמב\"ם הל' תשובה פ\"ג ה\"ד אעפ\"י שתקיעת שופר בר\"ה גזירת הכתוב הוא, רמז יש בו<sup data-n=\"52\">52</sup>, כלומר עורו ישינים משנתכם<sup data-n=\"53\">53</sup> ונרדמים הקיצו מתרדמתכם וחפשו במעשיכם וחזרו בתשובה וזכרו בוראכם אלו השוכחים את האמת בהבלי הזמן ושונים<sup data-n=\"54\">54</sup> כל שנתם בהבל וריק אשר לא יועיל ולא יציל, הביטו לנפשותיכם והטיבו דרכיכם ומעלליכם ויעזוב כל אחד מכם דרכו הרעה ומחשבתו אשר לא טובה. ואומר עורו ישינים משינתכם<sup data-n=\"55\">55</sup> ונרדמים הקיצו מתרדמתכם, דהגם דשינה ותרדמה הרי כללות ענינם אחד שהוא השינה, ומ\"מ הם חלוקים זמ\"ז, דתרדמה היא שינה חזקה ביותר, דהנה אדם הישן הוא בריא בכל כחותיו וחושיו כאדם הער, אלא שכחותיו וחושיו הם חלושים ורפוים שאינם פועלים פעולותיהם כענין פעולתם בשעה שהאדם ער. ועיקר השינה ניכר יותר בחוש הראות שעיניו סתומות. דהנה בכחות הנפש המתלבשים באברי הגוף, הרי פעולת הכחות הוא בשתי אופנים, ישנם כחות שפעולתם ניכרת, וכמו כח התנועה וכח הראי', וישנם כחות שפעולתם בלתי ניכרת, וכמו כח השמיעה, דבעת השינה הנה בכח התנועה<sup data-n=\"56\">56</sup> אינו ניכר ענין השינוי שנעשה ע\"י השינה, משא\"כ בהעינים ניכר השינוי והוא שעיניו סגורות. וכן ענינו ברוחניות דהשינה בכלל הוא אינו העדר וחסרון הכחות והחושים, אלא חלישות הכחות והחושים, ועיקרו בכח הראי' שעיניו סגורות מבלי ראות את האמת, ועוד יותר מה שבעת השינה הרי השקר נראה לאמת, דזהו\"ע החלום<sup data-n=\"57\">57</sup>, דהחלומות הרי רובן בענינים בלתי אמיתים בציורם הנדמה לו, וכמו בהרכבת שני ענינים רחוקים זמ\"ז או גם הפכים, ובעת החלום נדמה לו שהאמת הוא כן, ולפעמים גורם לו עונג ולפעמים צער, דשניהם כאחד בדמיון ושקר יסודם, והוא מחשיב ומדמה את השקר לאמת, דבקומו משינתו הנה לבד זאת שרואה שהעונג והצער שהי' לו הוא חלום",[["51","51","הקיצור דשנת ה'שי\"ת: יפרט דיש בתשובה צעקת הקול תקיעה, וצעקת הלב ב' מדרי' גנוחי גניח או ילולי יליל. ע\"י צעקת הלב שוברים החומה דלעו\"ז הנעשית מדברים בטלים או אסורים. תיקון הנפש ע\"י כף הקלע. ע\"י ריבוי אותיות דקדושה מבטל האותיות דלעו\"ז, ובונה החומה דקדושה."],["52","52","רמז יש בו: בו - כ\"ה בדפוסים שראיתי, אבל בכו\"כ כת\"י (והתימנים בתוכם): בה (לקוטי שיחות חי\"ד ע' 124 הערה 12)."],["53","53","ראה לקמן הערה 53."],["54","54","כ\"ה בכתי\"ק ובהעתקה. ברמב\"ם שלפנינו: ושוגים."],["55","55","כ\"ה - \"משינתכם\" (ביו\"ד) - בכת\"י תימן (רמב\"ם הוצאת קאפח. וראה שינויי הנוסחאות בזה - רמב\"ם ספר המדע ירושלים תשכ\"ד) - לקו\"ש חלק כט ע' 273 הערה 32."],["56","56","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שם: השמיעה."],["57","57","ראה תו\"א וישב כח, ג."]]],[2700520527,"בלבד, ולבד זאת שהשקר נדמה לו לאמת, הנה רואה כי חסר לו האמת בכלל, והיינו דבעת השינה חסר ענין האמת. וכן הוא ברוחני', דהנה אי' במד\"ר (בראשית פי\"ז ה') ר' יהושע דסכנין בשם ר' לוי אמר תחלת מפלה שינה (תחלת מפלתו של אדם לא בא עליו כ\"א ע\"י שינה ועצלות, רש\"י) דמיך לי' ולא לעי באורייתא (שמרוב הצלחתו אין לו פנאי לעסוק בתורה, רש\"י) ולא עביד עבידתי', וכשם שבאדם הישן הרי כל הכחות והחושי' הם רפוים בפעולתם והעיקר הוא בכח הראי' שעיניו סגורות, הנה כן הוא ברוחניות דכחות הנפש בהעבודה דשכל ומדות הם חלושים ורפוים מהעדר ההתעסקות בתורה ועבודה, ועיני האדם סגורות מלראות את האמת, ועוד יותר כי השקר נדמה לו לאמת, והיינו דלא זו בלבד שאינו רואה את האמת הגמור בהשגחה פרטית בכל עניניו, הנה עוד זאת שהשקר נדמה לו לאמת, ובזה הנה לפעמים מתענג ולפעמים הפכו, ומן האמת ממש הוא רחוק, וכתיב (משלי י\"ט ט\"ו) עצלה תפיל תרדמה"],[2700520555,"ונפש רמי' תרעב, וחשיב במד\"ר הנ\"ל כמה מיני תרדמה, תרדמת שינה, תרדמת מרמיטה, רש\"י פי' ל' בהלות ובערוך פי' ל' דומם, ותרדמה של שטות, דמהעצלות והעדר העבודה שהו\"ע השינה באים לידי תרדמה של שינה, דשינה הוא מה שהשקר נדמה לאמת, הרי יודע שישנו מציאות האמת רק שהוא מדמה על השקר שהוא אמת, ותרדמה הוא ששוכחי' לגמרי על האמת, וזהו שמהשינה באים לתרדמה של מרמיטה שהוא בבהלה ר\"ל כל ימיו ואינו עוסק בתורה ועבודה עד שנעשה כדומם והיינו שאין לו מושג בעניני תורה, עד כי בא ר\"ל לתרדמה של שטות המכסה על האמת, וזהו עצלה תפיל תרדמה ההתחלה היא מהעצלות, והעצלות מביאו לידי שינה, והשינה לידי תרדמה וסוף דבר הנה נפש רמי' תרעב, דהנה ענין הרמאות הוא מה שמטעה בדברים אשר לעצמם אינם שקר, כי רמי' הוא הנק' בלשון העולם פאַלש און נאַרין, ואינו ענין השקר אלא הוא מרמה כמו לשון רמי' מה שדוחה בטענות ומענות של דברי אונאה, ונפש רמי' בכללות ענינו הוא מה שמרמים את עצמם, דאָס ואָס מיא נאַרט זיך אַליין, ודוחים עניני עסק התורה ועניני עבודה מזמן לזמן, האַיינט איז ער טרוד אין דעם ענין של עסק או דברים בעלמא, ומחר נמצא ענין אחר מה שמטרידו באמת, או חפץ בו, ומניח עניני תורה ועבודה לזמן אחר, וכמאמר<sup data-n=\"58\">58</sup> לכשאפנה אשנה וכו', מיא נאַרט זיך אַליין אָפּ און מי שמוסט<sup data-n=\"59\">59</sup> זיך אַיין אַז מי האָט קיין צייט ניט וכו', וסוף כל סוף הנה נפש רמי' תרעב, דכאשר בא מועד הוא רואה אשר איבד ימיו ושנותיו בהבל וריק, והחכם עיניו בראשו<sup data-n=\"60\">60</sup> לקבוע עתים לתורה ולשמרם ולהתפלל בציבור ולקיים מצות ד' בקבעומ\"ש בכל תוקף עוז.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר לשון הרמב\"ם בהרמזים דת\"ק<sup data-n=\"61\">61</sup>, דשינה ניכר בסגירת העינים, וענין החלום שהשקר נדמה לאמת ותחלת מפלה שינה, ועצלות תפיל תרדמה שינה חזקה ששוכחים על האמת, ונפש רמי' מה שהאדם מרמה ומטעה א\"ע בטענות של מה בכך, ירעב דמאבד ימיו בהבל<sup data-n=\"62\">62</sup>.</span>\nענינים. ז שינה מביא לידי תרדמה.\nו) <b>וזהו</b> עורו ישינים משנתכם ונרדמים הקיצו מתרדמתכם, דהגם דשינה ותרדמה הרי כללות ענינם הוא אחד שהוא ענין השינה, הנה בכ\"ז אינם דומים זל\"ז, כי התרדמה היא שינה חזקה ביותר, דהשינה היא שעיניו סגורות ואינו שם אל לבו עניני השגחה פרטית וגם חושב את השקר לאמת, כי חושב שבשביל חכמתו וטוב הנהגתו ד' מצליח לו בעניניו, א\"כ הלא חושב בהאמת אלא דזה שחושב שהטוב מגיע לו הוא שקר, וחושב את השקר לאמת, ותרדמה היא מה ששוכחים על האמת לגמרי, והוא כאשר מרוב השינה היינו פון אַפולע שקרים ואָס ער מאַכט זיי פאַר אמת, וכמו החולם חלום שמאמת את השקר, שוכחים על האמת ובאים לתרדמה של שינה, אַז ער פאַרגעסט ח\"ו אייף דעם אמת ה' לעולם<sup data-n=\"63\">63</sup> און ברכת ד' תעשיר<sup data-n=\"64\">64</sup> און ער וערט ר\"ל אַ יורד מדחי אל דחי, מתרדמה של שינה לתרדמה של מרמיטה בבהלות שונות אַז אַלץ דאַרף ער, אַלץ איז אים נייטיג, אייף אַלץ איז דאָ צאַייט, נאָר אייף תפלה בציבור ולקבוע עתים לתורה אייף דעם איז קיין צאַייט ניטאָ, עד שר\"ל נתטמטם לבו ומוחו כדומם ובא לתרדמה של שטות. וזהו וזכרו את בוראכם אלו השוכחים את האמת בהבלי הזמן שהם ר\"ל בעלי התרדמה למיניהם כנ\"ל, והסיבה לזה הוא זה, ושונים|54 כל שנתם בהבל וריק, אָט דאָס ואָס מיא שלאָפט ואינם עוסקים בלימוד התורה ובעבודה שבלב זו תפלה. ואומר ע\"ז עורו ישינים משינתכם|55, דלהשינה מספיק התעוררות, אבל הנרדמים צריכים הקיצה ואינו מספיק ההתעוררות בלבד, וצריכים התעסקות גדולה ברפואתו, וכידוע דר\"ל מחלת השינה ח\"ו דזהו תרדמה ר\"ל הרי כל גופו נעשה חולה ר\"ל וצריכים התעסקות גדולה ברפואתו, דכן הוא גם ברוחניות דלתרדמה צריכים הקיצה, והוא ע\"י סדר מסודר בדרכי התשובה, ואינו מספיק ההתעוררות לבד. ואומר הביטו לנפשותיכם והטיבו דרכיכם ומעלליכם וכו', דסיבת הדרכים והמעללים הלא טובים היא בסיבת המדות רעות שהם מקור המעשים הלא טובים, והיינו דלבד זאת דמדות רעות הם לעצמן רע, והם חטאים ועוונות שצריכי' לעשות תשובה עליהם כמו על עבירה ר\"ל בפועל ועוד יותר, וכמ\"ש הרמב\"ם (שם פ\"ז ה\"ג) אל תאמר שאין תשובה אלא מעבירות שיש בהן מעשה וכו', אלא כשם שצריך אדם לשוב מאלו כך הוא צריך לחפש בדעות רעות שיש לו, ולשוב מן הכעס ומן האיבה ומן הקנאה ומן ההתול וכו', ואלו העוונות קשים מאותן שיש בהם מעשה, שבזמן שאדם נשקע באלו, קשה הוא לפרוש מהם, הרי דהם לעצמן",[["58","58","אבות פ\"ב מ\"ד."],["59","59","כ\"ה בכתי\"ק. ובספר המאמרים ה'שי\"ת שם: שמועסט."],["60","60","קהלת ב, יד."],["61","61","כ\"ה בכתי\"ק. ואוצ\"ל: דתק\"ש [ דתקיעת שופר]."],["62","62","הקיצור דשנת ה'שי\"ת: לשון הרמב\"ם ברמז התק\"ש. שינה ענינה חלישות הכחות ועיקרה בכח הראי'. בשינה יודע ממציאות האמת, בתרדמה שוכח על האמת, תרדמת שטות שמכסה על האמת. נפש רמי' שמרמה את עצמו."],["63","63","תהלים קיז, ב."],["64","64","משלי י, כב (ושם \"היא תעשיר\". וכ\"ה בספר המאמרים ה'שי\"ת שבהערה 1)."]]],[2700520572,"הם חטאים ועוונות שצריכים לשוב עליהם, הנה עוד זאת דהן המה סיבות הגורמים למעשים רעים ח\"ו. וזהו כללות ענין מצות שופר שהיא מצות התשובה, אשר בעת תק\"ש צריך האדם להתעורר בהתעוררות גדולה ולהתוודות על כל עניניו הלא טובים ויתחרט עליהם בחרטה גמורה על העבר ויבכה במר נפשו ויתחנן אל ד' מקרב ולב עמוק בהתעוררות גדולה כעומד בדין נפשות ממש אשר בזה תלויים חייו וחיי ב\"ב, ויעשה הסכם חזק בנפשו כי מעתה יהי' חזק בלימוד התורה ובעבודה שבלב בתפלה ובקיום המצות, שעי\"ז מעורר רחמים רבים על נפשו ומרחמין עליו, וכמארז\"ל (מד\"ר ויקרא פכ\"ט ו') בחודש הזה תחדשו מעשיכם בשופר, בחודש הזה שפרו מעשיכם, אמר להן הקב\"ה לישראל אם שפרתם מעשיכם הריני נעשה לכם כשופר הזה, מה שופר זה מכניס בזו ומוציא בזו כך אני עומד מכסא דין ויושב על כסא רחמים, והופך לכם מדה\"ד למדת הרחמים, והוא ע\"י התשובה מן המיצר<sup data-n=\"65\">65</sup> דוקא בדוגמת השופר<sup data-n=\"66\">66</sup> שצדו א' קצר וצדו א' רחב, כן האדם כאשר שב באמת ומיצר לו במאד כל עניניו הלא טובים ושב אל ד', הנה ע\"י מיצר זה הוא בא לידי מרחב, דבר\"ה הוא ההמשכה כללית בשפע רוחני ושפע גשמי בשפע רב, וכל ההמשכות דר\"ה הוא ע\"י השופר. וכידוע דבר\"ה הו\"ע בנין המל' שממשיכים אז בחי' כתר מל', דלכן נק' ראש השנה ע\"ש המשכת בחי' כתר מל' שנמשך אז וכמ\"ש בפע\"ח<sup data-n=\"67\">67</sup>, וענין כתר מל' ידוע שז\"ע הרצון למלוכה, דשרש ההמשכה היא למעלה מאד, בבחי' פנימיות ועצמות אוא\"ס. וזהו זה היום תחלת מעשיך זכרון ליום ראשון<sup data-n=\"68\">68</sup>, דכמו ביום ראשון בתחלת הבריאה שהי' בחי' התעוררות רצון מצ\"ע שנתעורר ברצון למלוכה וברצון על עולמות, וכמא'<sup data-n=\"69\">69</sup> בריש הורמנותא דמלכא כו', שזהו בבחי' עצמות אוא\"ס ב\"ה שלפני הצמצום, כמו\"כ הנה עכשיו בכל ר\"ה ור\"ה שחוזר כל דבר לקדמותו<sup data-n=\"70\">70</sup> צריכים לעורר בחי' הרצון למלוכה בבחי' פנימיות ועצמות א\"ס ב\"ה, וכ\"ז הוא ע\"י השופר, וכמארז\"ל (ר\"ה ל\"ד ע\"ב) אמר רבה אמר הקב\"ה אמרו לפני בר\"ה מלכיות זכרונות ושופרות, מלכיות כדי שתמליכוני עליכם, זכרונות כדי שיבוא לפני זכרוניכם לטובה, ובמה בשופר, שע\"י הצעקה בקול פשוט דשופר מעומקא דלבא מעוררים וממשיכים בחי' הרצון למלוכה, וא\"כ איך ביטלו חז\"ל מצוה זו בר\"ה שחל להיות בשבת, ומה יש הפרש בהמשכת אור כללי ועליון זה בין מקדש למדינה, ומהו כללות הענין<sup data-n=\"e11\">*</sup> אם ירושלי' בכלל מקדש או דירושלים הוא בכלל גבולין.",[["65","65","תהלים קיח, ה."],["66","66","ראה פרי עץ חיים שער השופר פ\"א. ד\"ה מן המיצר אעת\"ר ותרצ\"ז (ספר המאמרים אעת\"ר ע' א ואילך. תרצ\"ז ע' 152 ואילך). ועוד."],["67","67","שער ר\"ה."],["68","68","תפלת מוסף דר\"ה (ר\"ה כז, א)."],["69","69","זח\"א טו, א."],["70","70","ראה פרי עץ חיים שם פ\"א. לקו\"ת נצבים נא, ב. ובכ\"מ."],["e11","*","<b>כללות הענין:</b> ראה פרש\"י ותוס' לר\"ה (כט, ב). פיה\"מ שם. ועוד."]]],[2700520585,"<span data-k=\"ks\"><b>קיצור.</b> יבאר דשינה הוא מה שאינו שם לבו לההשגחה פרטית, ותרדמה ששוכח על האמת, ובא למרמיטה בהלה, ותרדמה דשטות, מדות רעות סיבת המעשים רעים, ותיקונם צריכים תשובה כמו חטאים ועונות, שופר צדו א' קצר שהוא המיצר וצדו א' רחב שהוא ההמשכה כללי' דר\"ה בנין המל' כתר מל', זכרון ליום ראשון, ויקשה למה נדחה בשבת, ומה ההפרש בין מקדש למדינה ומהו אם ירושלים בכלל מקדש או גבולין<sup data-n=\"71\">71</sup>.</span>\n<b>ענינים.</b> ח תרדמה א) דשינה, ב) דמרמיטה, ג) דשטות. ט מדות רעות צריכים תשוב' כמו עונות.\nז) <b>אך</b> הענין, דהנה ידוע דתכלית בריאת והתהוות העולמות, ותכלית הכוונה בירידת הנשמה בגוף הוא בכדי להמשיך גילוי אוא\"ס בעולמות ע\"י העבודה בקיום התומ\"צ, והו\"ע יחוד אוא\"ס הסוכ\"ע בממכ\"ע, וכמו שאומרים<sup data-n=\"e12\">*</sup> קודם כל מצוה<sup data-n=\"72\">72</sup> לשם יחוד קוב\"ה ושכינתי', בחי' יחוד סוכ\"ע בממכ\"ע<sup data-n=\"e13\">*</sup>, שז\"ע המשכת גילוי עצמות אוא\"ס ב\"ה, שזהו תכלית הכוונה בהתהוות העולמות ובירידת הנשמות למטה להתלבש בגוף גשמי, וכמא'<sup data-n=\"73\">73</sup> נתאוה הקב\"ה להיות לו דירה בתחתונים, וכמו דירת אדם עד\"מ הוא מה שעצמות האדם דר בהדירה<sup data-n=\"74\">74</sup>, הנה כמו\"כ הוא למעלה כבי' שיהי' בחי' עצמות אוא\"ס ב\"ה בגילוי למטה, וכמבואר בעמה\"מ בתחלתו<sup data-n=\"e14\">*</sup> דבריאת העולמות הוא ע\"י הצמצום הראשון שהי' באוא\"ס ונשאר חלל ומק\"פ<sup data-n=\"75\">75</sup>, ומזה הוא שרש התהוות הכלים<sup data-n=\"76\">76</sup> ומציאת העולמו' כולם כו', ואחר הצמצום נמשך גילוי הקו שהוא בחי' גילוי האור להאיר הכלים והעולמות כו', וכללות העולמות בבחי' אורות וכלים ה\"ה בתוך החלל ומק\"פ שנשאר אחר הצמצום כו', אמנם מ\"ש<sup data-n=\"77\">77</sup> ויניחהו בג\"ע",[["71","71","הקיצור דשנת ה'שי\"ת: ימשיך דלשינה די התעוררות, לתרדמה צריך התעסקות. מדות רעות מלבד ענינם גורמים גם מעשים רעים. תקיעת שופר תשובה מן המיצר. כל המשכות דר\"ה, המשכת הרצון למלוכה, על ידי השופר."],["72","72","\"אנחנו אומרים לשם יחוד קודם התפלה ויוצאים בזה על כל היום בקיום המצות כו'\" - ספר המאמרים תרנ\"ז ע' קצח. עטר\"ת ע' תקיח. נתבאר בלקוטי שיחות חלק לט ע' 46 ואילך."],["73","73","ראה תנחומא בחוקותי ג. נשא טז. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא פל\"ו."],["74","74","ראה מאמרי אדמו\"ר הזקן תקס\"ה ח\"א ע' תפט (ועם הגהות - אוה\"ת שה\"ש ח\"ב ע' תרעט ואילך). אוה\"ת בלק ע' תתקצז. ספר המאמרים תרל\"ה ח\"ב ריש ע' שנג. תרס\"ט ע' קס. תרע\"ח ע' קצג."],["75","75","ראה גם עץ חיים שער א (דרוש עגולים ויושר) ענף ב."],["76","76","ראה עץ חיים שם ענף ג. וראה פרק ל (לקמן ע' עה)."],["77","77","בראשית ב, טו."],["e12","*","<b>וכמו שאומרים:</b> ראה לקו\"ת פ' ואתחנן רד\"ה וזאת המצוה [ט, א]. דרושי ר\"ה ד\"ה תקעו (השני) פ\"ב [נה, ג]."],["e13","*","<b>יחוד סוכ\"ע בממכ\"ע:</b> ראה תניא פמ\"א [נז, ב. נח, א]. ובלקו\"ת המובא בהערה הקודמת."],["e14","*","<b>ע\"ה בתחלתו:</b> שער שעשועי המלך פ\"א."]]],[2700520598,"לעבדה ולשמרה, דלעבדה זו<sup data-n=\"e15\">*</sup> רמ\"ח מ\"ע, ולשמרה שס\"ה ל\"ת, היינו להמשיך תוספות אורות ע\"י הקו מאוא\"ס שלפני הצמצום, עד שלעתיד יהי' גילוי אוא\"ס במקום החלל כמו שהי' קודם הצמצום. ולכאו' א\"מ מהו ההתחדשות בזה דע\"י העבודה בתומ\"צ ימשיכו במקום החלל אותו האור כמו שהי' קודם הצמצום, והלא גם קודם הצמצום הי' אוא\"ס ממלא כל מקום החלל<sup data-n=\"78\">78</sup>, אך הענין הוא דתחלה קודם הצמצום כשהי' אוא\"ס ב\"ה ממלא מקום החלל הרי לא הי' אפשר להיות מציאות העולמות כמו שהם עכשיו, וא\"כ הרי לא הי' הגילוי בעולמו', אמנם לאחר שנתהוו העולמות הנה כשממשיכים גילוי אוא\"ס שלפני הצמצום הרי הגילוי הוא בעולמות, ועם היות דתחלת התהוותם לא הי' אפשר להיות כשהי' מאיר האור שלפני הצמצום, מ\"מ הנה לאחר שנתהוו העולמות ע\"י הצמצום הרי יכולים לקבל גם האור הזה, והוא ע\"ד דאי' בע\"ח<sup data-n=\"79\">79</sup> בענין גילוי הקו<sup data-n=\"80\">80</sup>, דהקו הוא מהאוא\"ס שלפני הצמצום, דזהו הלשון בע\"ח|79 חזר והאיר לאחר הצמצום, א\"כ הנה זה מה שחזר והאיר הוא אותו האור ממש שלפני הצמצום, וא\"כ יוקשה לאיזה צורך הי' כללו' ענין הצמצום ואח\"כ יומשך אור הקו, הרי הי' יכול אור זה של הקו להשאר, ומתרץ דאם הי' נשאר בתחלה הקו הרי לא הי' אפשר להתהוות הכלים, אמנם אחר שנתהוו הכלים הנה אז גם שמאיר אור הקו אינם מתבטלים, וכמו\"כ הוא גם בכללו' האוא\"ס שלפני הצמצום דלאחר שנתהוו העולמות ע\"י הצמצום, הנה יכולים לקבל אור זה ג\"כ. והמשל בזה הוא כמו בהשפעת השכל מהרב לתלמיד, הרי אם הרב הי' משפיע לתלמידו בתחלה עומק פנימיות חכמתו, הרי התלמיד לא הי' אפשר לקבל, והי' מתבטל ממציאותו לגמרי, והיינו שלא הי' מציאות מקבל, וצריך הרב להשפיע לתלמידו אור מצומצם שלפי ערכו של התלמיד, ואחרי שהתלמיד מקבל את האור המצומצם ונתפס ונקלט בשכלו, הנה אח\"כ הרי התלמיד בא על עומק פנימיות שכל הרב, שזהו מה דקאים אדעתי' דרבי'<sup data-n=\"81\">81</sup> וביכולתו לקבל בפנימיות, והקבלה בפנימיות הוא שמתחדש אצלו ענינים חדשים בהשכלות עמוקות, דזהו ג\"כ מצד תיקון הכלי, דע\"י שהתלמיד תופס השפעת הרב, והשפעת הרב נתפס בשכלו הנה בזה גופא הרי מתתקן ומזדכך הכלי מוחין של התלמיד, וכמו שאנו רואין במוחש דבהשפעת הרב לתלמיד הרי בריבוי השפעה נעשים חושי התלמיד באופן חושי הרב, אם בסוג ההשכלה, או הבנה או",[["78","78","בעץ חיים שער א שם: \"ממלא כל המציאות\". ובסהמ\"צ להצ\"צ לד, א: \"דאא\"ס ב\"ה הי' ממלא כל החלל שעתה בו העולמות\". אבל כ\"ה כבפנים בכ\"מ - ראה לקו\"ת הוספות לויקרא נב, ג. מאמרי אדמו\"ר הזקן תקס\"ב ח\"א ע' רפב. ועוד. וראה ד\"ה בחודש השלישי תשל\"ג (ספר המאמרים תשל\"ג ע' 343)."],["79","79","שבהערה 76."],["80","80","ראה גם המשך תער\"ב ח\"א ע' כח. ח\"ב ע' תתקכו. ספר המאמרים תרע\"ח ע' רפג. תרפ\"ד שבשוה\"ג להערה 1. ועוד."],["81","81","ראה עבודה זרה ה, ב. ספר המאמרים תרנ\"ז ס\"ע מט ואילך."],["e15","*","<b>דלעבדה זה:</b> ילקוט ראובני בשם מדרש. וכ\"ה בזח\"א כז, א. זח\"ב קסה, ב. ת\"ז תי' כא קרוב לסופו [סב, א]."]]],[2700520607,"בסוג ההסבר, ולזאת הנה אור שכל עצמו שבתחלה לא הי' אפשר להתלמיד לקבלו והי' מתבטל לגמרי<sup data-n=\"82\">82</sup>, הנה אחרי שתחלה השפיע לו הרב שכל מצומצם מה שלפ\"ע, הנה בזה התתקן כלי שכלו שיוכל לקבל השכל העמוק, ובקבלה פנימיות. ובדוגמא כזאת יובן דלאחר שנתהוו העולמות ומאיר בהם אור הקו, הנה הגם שהקו הוא קו המדה שמודד מדידת האורות והכלים, הנה בזה גופא נעשים כלים מקבלים, דידוע<sup data-n=\"e16\">*</sup> דהאו\"פ מצחצח חצי הכלי מבפנים, והאו\"מ מצחצח חצי הכלי מבחוץ, הנה לזאת יכולים העולמות לקבל אח\"כ גם בחי' כללות האור שלמעלה מגילוי הקו. ונמצא הגם שהאור שממשיכים ע\"י תומ\"צ הוא אותו האור שהי' ממלא מקום החלל קודם הצמצום, אבל יש בזה התחדשות גדולה בב' ענינים, הענין הא' דתחלה לא הי' אפשר להיות מציאות העולמות, ועכשיו העולמות יכולים לקבלו, והענין הב' והוא העיקר מה שבא ע\"י עבודת התחתונים, וההמשכה הוא ע\"י התורה וכתי'<sup data-n=\"83\">83</sup> הוי' עוז לעמו יתן, ואין עוז אלא תורה<sup data-n=\"84\">84</sup>, שהתורה היא הכלי להברכה העליונה, דבה ועל ידה נעשים ישראל כלים לקבל שפע רב, בשפע רוחני ושפע גשמי, ובה ועל ידה הוא המשכת אור העליון בעולם שלמעלה מהאור הקודם, וזהו התוס' אורות שנמשך ע\"י התומ\"צ שמאיר בחי' פנימיות ועצמות אוא\"ס שלמעלה גם מהאור שהי' ממלא מקום החלל.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דתכלי' הבריאה דעולמות וירידת הנשמה להיות יחוד סוכ\"ע וממכ\"ע שזהו\"ע אמירת לשם יחוד קודם כל מצוה, ויבאר לשון עמה\"מ דע\"י תומ\"צ ממשיכים העצמות שלפני הצמצום, והמשל בזה מרב ותלמיד שע\"י השפעת הרב במדידה נעשה כלי לקבל, כמו\"כ ע\"י הקו נעשו הכלים מקבלים גם האור שלא הי' אפשר להתקבל בתחלה, וההתחדשות א) ההמשכה בעולמות ב) ע\"י עבודה<sup data-n=\"85\">85</sup>.</span>\n<b>ענינים.</b> י התהוות העולמות ע\"י הצמצום. יא התהוות הכלים ע\"י הקו. יב תו\"מ ממשיכים העצמות שלפני הצמצום.\n\n-------------------- * --------------------",[["82","82","בכתי\"ק: שבתחלה לא הי' אפשר להתלמיד לקבלו, דלא זו בלבד מה שלא הי' יכול לקבל הענין על בוריו, אלא אדרבא הי' מתבטל לגמרי. ובהעתקה - נשמט."],["83","83","תהלים כט, יא."],["84","84","שהש\"ר פ\"א, ג (א). פ\"ב, ג (ג). מדרש תהלים עה\"פ ח, ג. וראה זבחים קטז, סע\"א. ויק\"ר פל\"א, ה. יל\"ש בשלח רמז רמד. וראה ספר המאמרים תרפ\"ז ע' קיב. ספר המאמרים מלוקט ח\"א ע' קצו (בהוצאה החדשה - ח\"ד ע' נט)."],["85","85","הקיצור דשנת ה'שי\"ת: תכלית הבריאה הוא שע\"י התומ\"צ יהי' דירה בתחתונים, המשכת האור שלפני הצמצום. החידוש הוא דהעולמות יכולים לקבלו (יביא דוגמא מהמשכת הקו ומשל בהשפעה מרב לתלמיד), ושבא ע\"י עבודה."],["e16","*","<b>דידוע דהאור:</b> ע\"ח ש\"ב ענף ג."]]],[2700520055,"<b>כי</b><sup data-n=\"86\">86</sup> חק לישראל הוא משפט לאלקי יעקב<sup data-n=\"87\">87</sup>, ואי' בזח\"ג דר\"י ע\"ב א\"ר יוסי תרין דרגין אינון יעקב וישראל, בקדמיתא יעקב ולבתר ישראל, שהם ב' בחינות ומדריגות בנשמה ושני דרכים בדרכי העבודה<sup data-n=\"e17\">*</sup>, וזהו תרין דרגין אינון יעקב וישראל, שהם ב' בחינות במדריגת נשמה, והם ב' דרכים בדרכי העבודה, וסדר העבודה בעבודה זו היא בקדמיתא יעקב ולבתר ישראל, דמדרי' יעקב הוא בחי' עבד וכמ\"ש<sup data-n=\"88\">88</sup> יעקב עבדי, ומדרי' ישראל הוא בחי' בן וכמ\"ש<sup data-n=\"89\">89</sup> בני בכורי ישראל וכתיב<sup data-n=\"90\">90</sup> בנים אתם לה\"א, וע\"ז הוא אומר כי חק לישראל הוא וגו' שהם בהב' בחינות ומדריגות דיעקב וישראל. דהנה כללות אומרו כי חק לישראל וגו' קאי אדלעיל מיני'<sup data-n=\"91\">91</sup> תקעו בחודש שופר בכסה ליום חגינו, היינו תקיעת שופר, דר\"ה נק' בכסה שהוא מכוסה, והיינו דהגם דכל ההשפעות בשפע רוחני ושפע גשמי על כל השנה נמשך בר\"ה, וכמארז\"ל (ביצה דט\"ז ע\"א) כל מזונותיו של אדם קצובין לו מר\"ה כו', ופי' כל מזונותיו היינו<sup data-n=\"92\">92</sup> הן המזון רוחני<sup data-n=\"93\">93</sup> והן המזון גשמי<sup data-n=\"94\">94</sup> הכל כאשר לכל קצובין לו בר\"ה, אמנם כל ההמשכות האלו הם בהעלם עדיין ומכוסים שבלתי ידועים, ותלוים במעשי האדם, וכמאמר<sup data-n=\"95\">95</sup> אדם נידון בכל יום, וכידוע<sup data-n=\"e18\">*</sup> שזהו הדין ומשפט בההשפעה פרטית בפועל, דלפעמי' מתחלפי' ההשפעות הגשמי והרוחני, אלו תמורת אלו, דתמורת שפע רוחני נשפע לו שפע גשמי ולפעמי' לטובתו ולפעמי' להפכו, ולפעמי' הנה תמורת שפע הגשמי נשפע לו שפע רוחני דלפעמים הוא לטובתו ולפעמי' כו', וזהו בכסה דכללות השפע וגם אופני ההשפעה הם מכוסים עדיין, דזהו אמרז\"ל<sup data-n=\"96\">96</sup>",[["86","86","בגוכתי\"ק כ\"ק אדמו\"ר מוהריי\"צ ב\"עניני מאמרי רצ\"ב\", נרשם: \"כי חק לישראל הוא משפט לאלקי יעקב, ובו ז' פרקים. יב ענינים\". - נעתקו לקמן במקומם."],["87","87","תהלים פא, ה."],["88","88","ישעי' מד, א."],["89","89","שמות ד, כב."],["90","90","פ' ראה יד, א."],["91","91","פסוק ד."],["92","92","ראה גם לקמן ע' תנ."],["93","93","ראה לקו\"ת דרושים לר\"ה נו, א. ספר המאמרים תרפ\"ט ע' 26. לקמן ע' תפה."],["94","94","ראה לקו\"ת שם נד, ד. נה, סע\"ד. נט, ב."],["95","95","ראש השנה טז, א."],["96","96","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שם: מארז\"ל."],["e17","*","<b>בנשמה .. בדרכי העבודה:</b> בארוכה בלקו\"ת פ' בלק סוף הביאור דמי מנה [ע, ב]. שם ד\"ה לא הביט [ע, ג]. בד\"ה ושבתה, ובד\"ה תתן אמת ליעקב המשך רס\"ו [ס\"ע רכד ואילך. ע' שג ואילך]."],["e18","*","<b>וכידוע שזהו:</b> ראה לקו\"ת ס\"פ קרח [נה, ד]. ספר המצות להצ\"צ מצות תגלחת מצורע לכשיטהר [קו, א ואילך]. קונטרס ומעין מאמר יז ואילך [ע' 108 ואילך]."]]],[2700520105,"(ר\"ה ד\"ח ע\"א) שהחודש מתכסה בו הוי אומר זה ר\"ה, דחודש פירושו חידוש, דבר\"ה נמשכים השפעות חדשות בשפע רוחני וגשמי אבל הוא חדש מתכסה, שהוא מכוסה ונעלם, דזהו מה שאנו אומרים בר\"ה<sup data-n=\"97\">97</sup> היום הרת עולם, דפי' הרת הוא מל' הריון<sup data-n=\"98\">98</sup>, דיודעים שיש עובר אבל הוא מכוסה ונעלם, כן הנה בר\"ה הנה היום דר\"ה הוא הרת עולם שנמשכים המשכת שפע רב בשפע רוחני וגשמי אבל הוא מכוסה עדיין בכללותו, וגם תלוי במעשי האדם, דע\"ז הוא הדין ומשפט פרטי דאדם נידון בכל יום ובכל שעה, וזהו בכסה, ומ\"מ הנה בכסה הוא ליום חגינו, דגם שהוא מכוסה ונעלם, הנה מצד האמונה פשוטה והבטחון באבינו מלכינו ית' ויתעלה הנה גם הכסה הוא יום חגינו, והוא ע\"י תקעו בחודש שופר לפי שכל ההמשכה דר\"ה הוא ע\"י תקיעת שופר, דבכוונתה הרוחנית הו\"ע התשובה, ונת\"ל דבתשובה יש ג' ענינים, צעקת הקול שהו\"ע התקיעה בקול פשוט כמו הבורח מן סכנת מות ר\"ל שהוא בצעקה גדולה, ובא לצעקת הלב דגנוחי גניח ילולי<sup data-n=\"99\">99</sup> יליל, דבזה הוא שובר את החומה דלעו\"ז אשר נעשה מהאותיות של המחשבות ודיבורים שלו בדיבורי בטלים והדומה ומפסיק בינו ובין אבינו מלכנו, וע\"י החרטה על העבר בבכי רב מעומקא דלבא הוא מפשר את הלבנים, וע\"י הקבלה על להבא לעסוק בדברי תורה הנה הוא בונה חומה דתורה, וכמ\"ש אני חומה זו תורה וחומת ירושלים. דכללות ענין התשובה מרומז בתנועת השופר דתש\"ר וכמאמר הרמב\"ם עורו ישינים משנתכם, דהישן הוא חולם חלום והשקר נדמה לו לאמת, דע\"י השינה נעשה ר\"ל נרדם ששוכח על האמת לגמרי, ויורד ר\"ל מדחי אל דחי מתרדמה של שינה לתרדמה של בהלה עד אשר מגיע ר\"ל לתרדמה של שטות, וכתיב עצלה תפיל תרדמה, דההתחלה היא העצלות שאינם קובעים עתים לתורה בטענות של מה בכך, עד כי עי\"ז הנה נעשה נפש רמי', ואָס ער נאַרט זיך אַליין אָפּ, ור\"ל מאבד ימיו ושנותיו בהבל וריק. אמנם גם מי שאינו בדרגות נמוכות כאלו ועוסק בתורה ועבודה שבלב זו תפלה הנה מ\"מ צריך לעשות תשובה, שע\"ז הוא אומר הביטו לנפשותיכם, מיא דאַרף ויסין ואָס טוט זעך מיט דיא כחות הנפש, ויא איז מען אין דעות, און ויא איז מען אין מדות, והטיבו דרכיכם ומעלליכם ויעזוב כאו\"א דרכו הרעה של המדות ומחשבתו אשר לא טובה שזהו מקור המדות רעות, דכשם שהעוונות בפועל באים בסיבת המדות רעות כן הנה המדות רעות באי' בסיבת מחשבתו אשר לא טובה. דהנה כתיב<sup data-n=\"100\">100</sup> יתיצב על דרך לא טוב רע לא ימאס וגו', הנה יש דעה כוזבת אשר היא מקור המדות רעות, והוא מה שאומרים אין חיוב בהטוב הגמור כמו בהידור מצוה ודרכי לפנים משוה\"ד, ומעמידים עניניהם על דיני התורה<sup data-n=\"101\">101</sup>, אבל טוב הגמור אין הכרח, דעה זו כוזבת",[["97","97","תפלת מוסף דר\"ה."],["98","98","מחזור ויטרי במקומו. ועוד. וראה רש\"י ורד\"ק ירמי' כ, יז. ועוד."],["99","99","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שם: וילולי."],["100","100","תהלים לו, ה."],["101","101","ראה בבא מציעא ל, ב."]]],[2700520155,"ומקור למדות רעות, וזהו יתיצב על דרך כזה הנה רע לא ימאס. וזהו הביטו לנפשותיכם, זעהט ואָס טוט זעך מיט דיא כחות הנפש, ויעזוב כו' מחשבתו הלא טובה כי זהו מקור המדות רעות. וזהו תקעו כו' חגינו, דע\"י התשובה מעומקא דלבא מתחזק הבטחון כי גם הכסא<sup data-n=\"102\">102</sup> הוא יום חגינו בשפע רב גשמי ורוחני. וזהו כי חק כו' יעקב בהשני מיני המשכות דשפע גשמי ורוחני, כי ענין חק קאי גם על מזונות|94 וכמ\"ש<sup data-n=\"103\">103</sup> הטריפני לחם חוקי, וכתיב<sup data-n=\"104\">104</sup> כי חקך וחק בניך, ומשפט לאלקי יעקב הוא שפע הרוחני. אמנם לפ\"ז הרי הי' צ\"ל כי חק הוא ליעקב משפט לאלקי ישראל, דחיים רוחנים למעלה מחיי בשר, ולמה אומר כי חק הוא לישראל<sup data-n=\"105\">105</sup> משפט לאלקי יעקב.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר ב' מדרי' בנשמה יעקב עבד ישראל בן וקאי על תקעו וגו' דבר\"ה נמשך שפע רוחני וגשמי, והוא בכסה מכוסה, אמנם מצד האמונה והבטחון בהוי' הוא יום חגינו, ויבאר דכשם שהחטאי' ראשיתן המד\"ר, כן המד\"ר ראשיתן המחשבות רעות, וזהו הביטו לנפשותיכם, וההתחלה הוא יתיצב על דרך שאינו טוב גמור, ובמילא רע לא ימאס.</span>\n<b>ענינים.</b> א ר\"ה א) כסה שההשפעה נעלם, ב) יום חגינו מפני האמונה. ב מחשבות רעות מקור המד\"ר.\nט) <b>והנה</b> בבריאת והתהוות העולמות מצינו שני לשונות<sup data-n=\"e19\">*</sup>, פעם כתיב (תהלי' קל\"ה ו') כל אשר חפץ הוי' עשה בשמים ובארץ בימים וכל תהומות, דמזה מובן שההתהוות הוא מבחי' חפץ ורצון הוי' לבד, ופעם כתיב (שם ל\"ג ו') בדבר הוי' שמים נעשו וגו', וכמאמר<sup data-n=\"106\">106</sup> בע\"מ נבה\"ע כמ\"ש<sup data-n=\"107\">107</sup> ויאמר אלקים, שהי' מאמר ודיבור מפורש פרטי בכל מאמר ומאמר<sup data-n=\"108\">108</sup>, דמזה מובן שהתהוות העולמות והנבראי' הנה לבד זה שהוא בבחי' חפץ ורצון הוי' הרי הי'<sup data-n=\"109\">109</sup> מאמרות מפורטים בדיבורים מפורשים ולא שנברא הכל רק ברצון וחפץ לבד. אך הענין הוא<sup data-n=\"110\">110</sup> כי הנה נודע דלכל דבר יש חומר וצורה, שהחומר הוא עצם גוף הדבר בכלל, כמו השמים בכלל או הארץ בכלל, וצורה",[["102","102","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שם: הכסה."],["103","103","משלי ל, ח."],["104","104","שמיני י, יג-יד."],["105","105","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שם: כי חק לישראל הוא."],["106","106","אבות רפ\"ה."],["107","107","בראשית א, ג ואילך."],["108","108","ראה גם רד\"ה בראשית שנה זו (לקמן ע' צג)."],["109","109","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שם: היו."],["110","110","בהבא לקמן - ראה (בנוסף להמצויין בהערה ד\"ה שני לשונות): אוה\"ת נ\"ך ח\"א ע' תקסט. ספר המאמרים תרכ\"ט ע' יז ואילך. ע' שצג ואילך. תרמ\"ד ע' רט ואילך. תרנ\"ו ע' שיח ואילך. תרס\"ג ע' קטו ואילך. תרפ\"ה ע' נו ואילך. ע' סו ואילך. תש\"ח ע' 57 ואילך. ע' 67 ואילך."],["e19","*","<b>שני לשונות:</b> ראה בכ\"ז תו\"א פ' מקץ רד\"ה נר חנוכה [מא, ד]. קונטרס עץ החיים בתחלתו. ובכ\"מ."]]],[2700520205,"הוא ציור ותמונת הדבר בדמותו וצלמו המיוחדה לו, וע\"ד מה שהשמים הוא כדורי, וכן ציור מראה הדבר ההוא, או צורת שטחו בעיגול וריבוע ומספר קצותיו בעל ששה או שמונה קצות. והנה חומר הנבראים, נברא בדבר ה' ובע\"מ, דכל מאמר ומאמר עביד עבידתי', שבמאמר יהי אור נתהוה האור מאין ליש, ובמאמר יהי רקיע נתהוה הרקיע מאין ליש, אבל אופן צורת הרקיע בדמותו וצלמו הוא נעשה בחפץ ד', היינו מה שלא בא לכלל גילוי בדיבור או מאמר. וזהו בדבר ה' שמים נעשו, ובע\"מ נבה\"ע קאי על חומר הנבראים, ומ\"ש כל אשר חפץ ד' עשה הוא ציור כל נברא ונברא שזהו מבחי' חפץ ד'. והנה כתיב (תלי' ק\"ד כ\"ד) מה רבו מעשיך הוי' כולם בחכמה עשית<sup data-n=\"111\">111</sup>, דהמשכת בחי' חפץ ורצון ד' הוא ע\"י בחי' חכ', וחכ' מדריגתה אמת שהו\"ע ההתאמתות, ומאחר דהמשכת בחי' חפץ ד' בציור הנבראים הוא ע\"י חכ' הנה מצד הביטול וההתאמתות שבספי' החכ' הנה זה כמו שבא מבחי' חכמה עצמה, כי במדרי' הפרטים הנה כולם בחכ' עשית ואי' בזהר<sup data-n=\"e20\">*</sup> כולם בחכ' עשית בבינה, והיינו דכל הציורי' הם מבחי' בינה, וכמאמר דבינה ציירא ציורים<sup data-n=\"112\">112</sup>, כמו בהשכלה והשגה הרי השגת הבינה היא בנקודת ההשכלה דחכ' שענינו הוא מה שבינה מציירת ציורים שונים בהנקודה דהשכלה, שהנקודה היא החומר, ובכל נקודה יש בה ענינים, מהם עיקרים ומהם מסתעפים, וההשגה דבינה היא לבד מה שמבארת בהסבר רב הענין שבהנקודה דחכ' הנה היא מציירת בו ציורים שונים, ולכן הנה אמיתת ענין ההשגה הוא הבנת כל מושכל באופנים שונים, דכל האופנים האלו הם הציורים בהחומר שהוא הנקודה דחכ', וזהו כולם בחכ' עשית בבינה דכל הציורים הם מבחי' בינה, משא\"כ בחכ' שהוא בבחי' נקודה שזהו\"ע החומר, א\"כ הרי התהוות החומר הוא מחכ' והצורה היא מבינה. אמנם זהו בפרטיות המדריגות, אבל בכללות הענין הוא להיות דהמשכת בחי' חפץ ורצון ד' הוא ע\"י בחי' חכ', והחכ' היא התאמתות דענינו הוא ההתאחדות עם הדבר הבא על ידו, ולזאת הנה הוא כאילו הוא בא מבחי' חכ' עצמה, וכמאמר אשר יצר את האדם בחכ'. והענין בזה הוא דהנה בכדי שמבחי' חפץ ורצון ד' יהי' נעשה פעולה ממש בנבראים בהאופן דסדר ההשתל' היינו בבחי' התחלקות דוקא שחלוקים בדמותם ובצלמם, כל יצור פרטי בכל מין בצורה המיוחדת לו ברצון העליון ב\"ה ביחוד ממש, והגם דכללות הנבראים ה\"ה רק בהד' מדרי' דצח\"מ, הנה לבד זאת שבכל אחד מהד' מדרי' דצח\"מ יש ריבוי סוגים במינו, וכמו בסוג הדומם הרי בהפרט דאבנים יש בו בעצמו ריבוי מינים<sup data-n=\"113\">113</sup>, דכולם הם אבנים אבל חלוקים",[["111","111","ראה גם ספר המאמרים תרנ\"ב ע' מו ואילך. ד\"ה מה רבו מעשיך תרמ\"ד (ספר המאמרים תרמ\"ד (קה\"ת, תשס\"ב) ע' שיד ואילך)."],["112","112","ראה אור תורה להרב המגיד ג, ד. הובא באוה\"ת חנוכה ח\"ה תתקנב, ב (שהוא - הערות לתו\"א הנ\"ל בהערה ד\"ה \"שני לשונות\"). ספר המאמרים תרנ\"ב שם. וראה זח\"א ב, א ובמקדש מלך שם."],["113","113","ראה בחיי תצוה כח, י. ועוד. וראה גם לקמן ס\"ע קעו ואילך. ד\"ה אין ערוך לך דש\"פ חיי שרה תרצ\"ד סכ\"ח."],["e20","*","<b>ואיתא בזהר:</b> ח\"ג מג, א."]]],[2700520255,"בעצם מהותם, דישנם אבנים פשוטות עד המין אבנים טובות ומאירות ואבני סגולה בסגולות רוחנים<sup data-n=\"114\">114</sup>, וכמו אבני ההצלחה ואבני החן, ומ\"מ הרי כולם כאחד הוא במין פרטי דאבן, וכן בצומח שיש בו ריבוי מינים אילנות תבואות דשאים ועשבים, דכל אחד ואחד מהם הוא כמו סוג מיוחד במינו שישנם שהם סמי מרפא וסגולה וישנם הפכם, הנה לבד זאת הרי במין עשב אחד הנה מין העשבים האלו בכל מרחב העולם כולו הוא ריבוי מופלג אשר מספרי המספר לא יכילנו, ומ\"מ הרי כאו\"א מן המספר המרובה הלזה יש לו דמותו וצלמו המיוחד לו מאת הבורא ב\"ה מה שאינו דומה לזולתו.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דחומר הנבראי' נברא בע\"מ, וצורה בחפץ ד' שלא בדיבור מפורט, והמשכת חפץ ד' הוא ע\"י בחי' חכ', בינה ציירא ציורים בנקודת החכ', ומפני ענין ההתאמתות שבבחי' חכ' הוא כמו שבא מחכ' עצמה. וזהו אשר יצר את האדם בחכ', ויבאר ריבוי המופלג שבדצח\"מ<sup data-n=\"115\">115</sup>.</span>\n<b>ענינים.</b> ג חומר נברא במאמר וצורה בחפץ לבד.\nי) <b>והנה</b> כשם שבהאדם שהוא בחיר הנבראים אמרז\"ל (סנהדרין פ\"ד מ\"ה) לפיכך נברא האדם יחידי ללמדך שכל המאבד נפש א' מבני אדם, מעלה עליו הכתוב כאילו איבד עולם מלא, וכל המקיים נפש א' מבני אדם, מעלה עליו הכתוב כאילו קיים עולם מלא וכו', ולהגיד גדולתו של הקב\"ה שאדם טובע כמה מטבעות בחותם אחד וכולן דומין זל\"ז, וממ\"ה הקב\"ה טבע כל אדם בחותמו של אדה\"ר (הוא צורת מין האדם אשר בה האדם אדם) ואין אחד מהן דומה לחבירו, הנה כן הוא גם בהנבראי' והיצורים היותר קטנים והיותר קלים ובלתי תופסי מקום אצל האדם כלל, וכמו העלין של אילנות הגם שכולם הם בסוג אחד, ומ\"מ הנה כל אחד מהם הוא יחידי שאינו דומה לחבירו כלל, וכן הוא בכל הנבראים והיצורים דגם במין א' ובמשפחה אחת דבכללותם ה\"ה משתוים בענינם ובסגולתם וגם במראיהם הכללי, ועם זה הרי הם חלוקים בדמותם ובצלמם, והתחלקות זו הוא ע\"י התלבשות בחי' הרצון בבחי' חכ', אמנם דוקא בחכ' שלמעלה מכל הע\"ס, והוא בחי' כ\"ח מ\"ה<sup data-n=\"116\">116</sup>, ושרש החכ' למעלה הוא בחי' בוצינא דקרדוניתא<sup data-n=\"e21\">*</sup> קו המדה, וכמ\"ש<sup data-n=\"117\">117</sup> מי מדד",[["114","114","ראה בבא בתרא טז, ב."],["115","115","הקיצור דשנת ה'שי\"ת: החומר נברא ע\"י העשרה מאמרות, הצורה בחפץ ורצון שנמשכו ע\"י החכמה, ונתאמת ונתאחד בה, כדי שיהי' בסדר ההשתלשלות, בהתחלקות דריבוי הנבראים. (במדרי' הפרטיות בינה מצייר ציורין בנקודה דחכמה)."],["116","116","ראה רע\"מ בזח\"ג כח, א. לד, א. תורת חיים בראשית א, ג. ובכ\"מ."],["117","117","ישעי' מ, יב."],["e21","*","<b>בוצינא דקרדוניתא:</b> זח\"א טו, א. זח\"ג רצב, ב. ובת\"ז ריש תי' ה': בוצינא דקרדוניתא כד מדיד משיחא. - וראה תו\"א פ' מקץ ביאור לד\"ה המגביהי [לט, א]. הוספות לתו\"א פ' שמות ד\"ה להבין כו' ענין חלב ודבש רפ\"ב [קז, ד ואילך]."]]],[2700520305,"בשעלו מים<sup data-n=\"118\">118</sup>, דמים הוא בחי' חכ' ומדד בשעלו מים שע\"י החכ' נעשה המדידה איך ומה יהי' כל נברא ונברא כפי חפץ ורצון ה'. ובזה יובן מ\"ש בע\"ח<sup data-n=\"e22\">*</sup> דיחוד או\"א הוא תדירי כדי להחיות העולמו' תמיד, דלכאורה א\"מ שהרי חיות העולמות הוא ע\"י דבר ה' וכמ\"ש<sup data-n=\"119\">119</sup> לעולם הוי' דברך נצב בשמים, ומה נצרך לזה היחוד תדירי דחו\"ב, אלא להיות כולם בחכ' עשית בבינה, ובכללות ההתהוות הוא ע\"י חכ' דבראשית ברא<sup data-n=\"120\">120</sup>, אמנם ההתהוות בפועל שהוא התהוות החומר הוא ע\"י הדיבור העליון שהוא בחי' מל'. וזהו דכתיב<sup data-n=\"121\">121</sup> ואתה מחי' את כולם, ואי' בזח\"ב דקע\"ט ע\"ב א\"ר יצחק נהורא עילאה ונהורא תתאה כליל כחדא אקרי ואת\"ה (היינו בתוספת וא\"ו) כמה דאת אמר (נחמי' ט') ואתה מחי' את כולם, דהנה אי' בזח\"ב דקל\"ח ע\"ב כתיב (תהלים כב<sup data-n=\"122\">122</sup>) ואתה הוי' אל תרחק אילותי לעזרתי חושה, דוד מלכא אמר דא בשעתא דהוה מתקן ומסדר תושבחתא דמלכא, בגין לחברא שמשא בסיהרא, כיון דהוה מתקן ומסדר שבחין דילי' לאתחברא, אמר ואתה ה' אל תרחק, ואתה ה' רזא דחברותא חדא בלא פרודא. והענין בזה הוא דמקשה בזהר דמאחר דכל היחודים העליונים שהם התיקונים הם מתוקנות<sup data-n=\"123\">123</sup>, הנה לאיזה צורך הוא לעשות תיקונים אלו למטה בתפלה, שמדבר שם בענין התיקון שנעשה בתפלת נשמת כל חי, ומתרץ כי העבודה הוא להתכלל בתיקוני' אלו, ופי' באור החמה<sup data-n=\"124\">124</sup> דכל מגמתינו הוא לכלול נפשותינו בכל היחוד הזה, והטעם שהרוחני' העליון כשנשלם ונגמר מסתלק למעלה והתחתונים נשארים ריקנים בלי טוב כו', וכשיש בתחתונים מי שהוא יודע לתקן למטה סוד המרכבה נקשרי' התחתונים ברוחניותה<sup data-n=\"125\">125</sup>, וזהו דנהו\"ע ונהו\"ת כליל כחדא אקרי ואתה, והיינו שהוי\"ו הוא המשכה מבחי' חפץ ורצון ד' כמו שהוא בח\"ע, ובא ונמשך אל בחי' הדיבור שהוא בחי' אתה להיות מחי' את כולם. וטעם הדבר מה שחומר הנבראים נבראו במאמר ודיבור ולא נבראו הכל בחפצו ורצונו ית' בלבד כמו הצורה, הוא מפני שאם הי' גם התהוות החומר בבחי' החפץ ורצון בלבד הנה אז לא הי' הגילוי מאין ליש, רק שהי' הכל בטל במציאות ממש בלי שום התחלקות באופני הביטול, וחילוקי עולמות אבי\"ע הכללים והפרטים כמו שהוא עתה, והי' העולם בטל במציאות ממש, לפי שהי' מקבל מבחי' חכ' שהוא בחי' ביטול איהו<sup data-n=\"126\">126</sup> וחיוהי חד<sup data-n=\"127\">127</sup>,",[["118","118","ראה תו\"א מקץ מב, ד."],["119","119","תהלים קיט, פט. וראה תניא שעהיוה\"א פ\"א."],["120","120","בראשית א, א. ראה לקו\"ת במדבר יב, סע\"ד ואילך. ובכ\"מ."],["121","121","נחמי' ט, ו."],["122","122","פסוק כ."],["123","123","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שם: מתוקנים."],["124","124","לזהר ח\"ב שם."],["125","125","עכ\"ל האור החמה (בדילוג)."],["126","126","תקו\"ז בהקדמה (ג, סע\"ב)."],["127","127","ראה לקמן ע' קכח ואילך."],["e22","*","<b> מ\"ש בע\"ח:</b> שער הכללים פ\"ב. שער הזווגים פ\"א. ובכ\"מ."]]],[2700520355,"רק עיקר גילוי היש הוא ע\"י דבר ה', כמ\"ש<sup data-n=\"128\">128</sup> כי הוא ציוה ונבראו, דפי' ציוה מל'<sup data-n=\"129\">129</sup> מצות המלך, דכל עניני הנהגת המלוכה הם בפקודה וציווי, ולכן במע\"ב נא' ל'<sup data-n=\"130\">130</sup> יהי, בדרך גזירה, וזהו מלכותך מכ\"ע<sup data-n=\"131\">131</sup>, דכל עולמים ריבוי עולמות וחלוקיהם זמ\"ז בעניניהם והביטול שלהם הוא ע\"י בחי' מל', וזהו פי' יש מאין דהיינו שהמשכת החיות אשר בהעולמות הוא בבחי' אין והארה בעלמא שהוא בחי' שם בלבד ומזה נעשה גילוי היש. ותכלית בריאת יש מאין הוא כדי להיות היש בטל לאין, דזהו תכלית הכוונה בבריאת העולמות והנבראים משום שנתאוה|73 הקב\"ה להיות לו ית'<sup data-n=\"132\">132</sup> דירה בתחתונים, דהיינו שהנבראים התחתונים יהיו בעלי חומר וגוף והם יהיו בבחי' כלי ומכון לשבתו ית' ובבחי' דירה אליו ית', והיינו שיהי' בבחי' ביטול עד שיהי' כלי ודירה אליו ית', ויאיר ויתגלה אור ה' למטה, וכתפארת אדם לשבת בית<sup data-n=\"133\">133</sup> כמו\"כ כבי' יהי' לו ית' דירה בתחתונים שיהי' גילוי אלקות למטה ונגלה כבוד ה'<sup data-n=\"134\">134</sup> למטה כמו למעלה ע\"י עבודת התחתונים בקיום התומ\"צ.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דגם נברא היותר קטן הוא יחידי בדוגמת האדם שאין א' דומה לחבירו והריבוי הזה בא ע\"י ספי' החכ' שלמעלה מהשתל', ויבאר דההתהוות בפועל הוא ע\"י ספי' המל' בכח דח\"ע, נהו\"ע ונהו\"ת כליל כחדא נק' ואתה וטעם שהחומר נברא במאמר ולא ברצון בלבד, דאז הרי לא הי' גילוי היש, ולכן במע\"ב נא' הכל בציווי, והכוונה ביטול היש ע\"י עבודה<sup data-n=\"135\">135</sup>.</span>\n<b>ענינים.</b> ד כל נברא ויצור קטן הוא יחידי בעולם.\nיא) <b>וביאור</b> הענין, דהנה כל הנבראים יש בהם שני בחינות, היינו הגוף של הנברא והאור והשפע אלקי שבו, שהיא בחי' נשמתו השופע בו תמיד להחיותו שהן בחי' אור וכלי, דכשם שבגוף ונפש האדם הרי אברי הגוף הם כלים לאור וחיות הנפש המתלבש בהם, וחיות הנפש הוא בחי' האור דכלי זו, הנה כמו\"כ",[["128","128","תהלים קמח, ה."],["129","129","מלשון."],["130","130","לשון."],["131","131","שם קמה, יג."],["132","132","כן הי' מוסיף כ\"ק אדמו\"ר מהורש\"ב נ\"ע פעמים רבות על לשון המדרש - נתבאר בלקו\"ש חלק יט ס\"ע 27 ואילך. וראה רשימות היומן משנה זו (תרצ\"ב) - ממה שסיפר כ\"ק מו\"ח אדמו\"ר (\"רשימות\" חוברת קפד ע' 5): \"אדנ\"ע התחיל לכתוב - להיות לו \"ית'\" דירה בתחתונים - בהוספת תיבת \"ית'\" ע\"י חלום. אבל גם אח\"כ כתב גם ל' המורגל \"לו דירה\". אבל אני כותב \"לו ית' כו'\". וראה שיחת ליל ב' דחה\"פ תשי\"ב (תורת מנחם התוועדויות תשי\"ב ח\"ב ס\"ע 122 ואילך)."],["133","133","ישעי' מד, יג."],["134","134","שם מ, ה."],["135","135","הקיצור דשנת ה'שי\"ת: יודיע דכל פרטי הדצח\"ם חלוקים זה מזה, וכ\"ז הוא ע\"י ההתלבשות בחכמה, ולכן יחוד חו\"ב תדירי, גילוי היש ע\"י שההתהוות בדבר הוי', יש מאין. התכלית הוא ביטול היש לאין ע\"י התומ\"צ."]]],[2700520402,"הוא בכל נברא ויצור דגופו ואור השפע האלקי השופע בו תמיד להחיותו הן בבחי' אור וכלי. דב' ענינים אלו גוף ונפש אור וכלי הרי ישנם בכל הנבראי' התחתונים והרוחנים, דגם אפילו בהנבראי' היותר נמוכים בד' מדריגות דצח\"מ שהם הצומח והדומם הרי יש בהם נפש וכמ\"ש בע\"ח בסופו<sup data-n=\"136\">136</sup> דיש נפש הצומחת ונפש הדוממת, דהכוונה היא הנפש הפרטי דכל צומח ודומם, וזהו דכתיב (חבקוק ב' י\"א) כי אבן מקיר תזעק וכפיס מעץ יעננה, דהאדם נדמה לו דכאשר אין בנ\"א רואים אותו אין יודע להעיד בו, ובאמת הלא כל הדוממים והצומחים בעלי נפש הם, וכן גם נבראים העליונים יש בהם חומר וצורה שהן בחי' אור וכלי וכמ\"ש (יחזקאל א' כ') כי רוח החי' באופנים שבחי' רוח החי' הוא חיות אלקות ואור אלקי השופע ונמשך בהאופנים להחיותם, שהוא כח הפועל בנפעל, וכמו הנשמה המלובשת בגוף להחיותו הרי אור וחיות הנפש פועלת בהגוף עד שכל אברי הגוף נפעלים מפעולת אור וחיות הנפש הפועל בהם בכאו\"א לפי ערכו ולפי ענינו, בדרך כח הפועל בנפעל, ולכן נקראים בשם כחות להיות ענינם בדרך כח הפועל בנפעל, הנה כמו\"כ הוא באור השפע הנמשך מהחי' לאופנים שהוא בבחי' כח הפועל בנפעל. והנה בכל נברא ונברא הרי גופו הוא חושך בערך נשמתו, וכמו באדם שיש בו גוף ונפש הרי חומר גופו הוא בחי' חושך לגבי הנשמה שבו שהיא בחי' אור וכמ\"ש<sup data-n=\"137\">137</sup> נר ד' נשמת אדם, ולכן הרי גוף האדם כמו שהוא לעצמו נק' גולם, וכמו גולמי כלי עץ<sup data-n=\"138\">138</sup> או חרס, וכמו שאין ערוך חושך לגבי אור שהן ב' הפכים כך אין ערוך גשמיות הנברא וחומריותו לגבי נשמתו ונפשו. דכן הוא אפילו בנבראי' הרוחני' דאין ערוך גוף האופנים לגבי רוח החי' השופע בהם להחיותם שהוא בחי' אלקות, ומ\"מ הרי האור והחיות האלקי בא בבחי' התלבשות בגוף הנברא ונעשה כערכו וכמהותו. ויובן זה תחלה כמו שהוא בהאדם למטה בנפש וגוף, דאור וחיות הנפש הוא המתלבש ומתפשט בכלים ואברי הגוף, דע\"י התלבשו' זו הרי כחות הנפש הרוחניים נעשים כערכו של הלבוש שמתלבשים בתוכו. דהנה הכחות האלו הרי ישנם כמו שהם בהנפש קודם שמתפשט ומתלבש באברי הגוף, אשר שם הם במהותם העצמי, ונקראים אברי הנפש, דכשם שהגוף יש לו אברים, הנה כמו\"כ הנפש יש לו אברים שהם הכחות, וכשם שהאברים הם מעצמות מהותו של הגוף, דגם אבר היותר דק ומזוכך כמו חומר העין או חומר המוח שהם חומריים זכים ודקים ביותר, ומ\"מ ה\"ה מעצמות מהותו של הגוף שהם חומרים ולא רוחניים, הנה כמו\"כ באברי הנפש שהם מעצמות מהותו של הנפש, דעם היות שבכחות הנפש ישנו ג\"כ חילוקי מדריגות עליון ותחתון, דלבד זאת מה שהם חלוקים בעצם ענינם כחות מקיפיים וכחות פנימיים שהם חלוקים בטבעם וענינם הרי הכחות פנימיים עצמם יש בהם גם עליון ותחתון, ומ\"מ הנה הכח היותר אחרון שבנפש הוא ג\"כ רוחני ולא חומרי כלל, עד שהכחות כמו שהם באים בהתלבשות באברי הגוף אינם בערך כלל כמו שהן טרם התלבשותם באברי הגוף, שהכחות כמו",[["136","136","שער נ (שער קיצור אבי\"ע) פ\"י."],["137","137","משלי כ, כז."],["138","138","ראה כלים פי\"ב מ\"ח. חולין כה, א. וראה מצו\"צ תהלים קלט, טז."]]],[2700520449,"שהן קודם התלבשותם בגוף הן רק בבחי' התפשטות מעצמות הנפש בדוגמת אור וזיו המתפשט מן העצם, והיינו דעם היות שהכחות הם אברי הנפש ורוחניים, מ\"מ הנה בערך הנפש הם כדוגמת זיו המתפשט, דהנשמה כמו שהיא למעלה אין לה גוף ואינה מתלבשת בשום דבר, שהרי אינה דומה למלאכים, שהמלאכים הגם שהם נבראי' רוחנים ומ\"מ ה\"ה בעלי גוף אלא שגופם הוא מהיסודות הדקים, וכמ\"ש<sup data-n=\"139\">139</sup> עושה מלאכיו רוחות משרתיו אש לוהט, דאש ורוח הם מהיסודות הדקים, אבל עכ\"פ הם בעלי גשם, משא\"כ הנשמה אין לה גשם כלל ואינה מתלבשת בשום דבר<sup data-n=\"140\">140</sup>, א\"כ הכחות שלה כמו שהם במהותם העצמי ה\"ה בבחי' התפשטות מן העצמות וה\"ה כחות רוחני' ממש שהם בהפשטה מהחוש דגשם לגמרי, והיינו דהשכל שלה הן<sup data-n=\"141\">141</sup> בבחי' תכלית הרוחניות, וכן המדות אהוי\"ר שלה הרי הכל הוא בבחי' הרוחניות ממש.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דהגוף ונשמה אור וכלי, וגם בדומם יש נפש, והם המעידים באדם, וגם הנבראים העליונים יש בהם חומר וצורה, ואין ערוך הגוף להנפש, דכן הוא גם בנבראים העליונים, הכחות הם אברי הנפש וממהותו, ויבאר מהותם קודם התלבשותם ושבזה נעשים כערך לבושם<sup data-n=\"142\">142</sup>.</span>\n<b>ענינים.</b> יא. ה נפש וגוף א) צורה וחומר, ב) אור וכלי. ו הכחות הם אברי הנפש.\nיב) <b>והנה</b> בהתלבשות הנשמה בגוף עם היות שהנפש אינו משתנה בעצם מהותו שהרי גם אז כל ענינה של הנשמה הוא בהשגת אלקות ובבחי' התפעלות אור אלקי, מ\"מ הרי ההשגה גופא היא בבחי' השגה מורגשת ומגושמת שהיא בבחי' יש ממש לגבי",[["139","139","תהלים קד, ד. וראה רמב\"ן בסוף שער הגמול. הובא בתו\"א בראשית ד, ב. לקו\"ת ברכה צח, א."],["140","140","ראה לקו\"ת שם."],["141","141","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שבהערה :1 הוא."],["142","142","הקיצור דשנת ה'שי\"ת: בכל הנבראים יש גוף ונפש, ב' הפכים, אבל נעשים בערך זל\"ז, יבאר זה באדם שכחות הנפש טרם התלבשותן בגוף הם התפשטות מעצמות הנפש, בתכלית הרוחניות."]]],[2700520491,"ההשגה שהי' לה קודם, דהנשמה קודם ירידתה למטה להתלבש בגוף הרי מעמדה ומצבה הוא בג\"ע דשם מאיר זיו השכינה, וזיו השכינה שמאיר בג\"ע זהו בחי' האלקות דאצי'<sup data-n=\"143\">143</sup>, ואצי' לגבי בי\"ע הוא בערך<sup data-n=\"144\">144</sup> סוכ\"ע לגבי ממכ\"ע, ובכל עולם ועולם הנה הג\"ע שבעולם ההוא הוא גילוי הארת האצי' שבעולם ההוא, והשגת הנשמות בג\"ע הוא שמשיגין בחי' מהות האור והזיו, משא\"כ בירידת הנשמה למטה ומתלבשת בגוף הנה הגם דכל ענינה הוא בהשגת אלקות ושכלה הוא שכל אלקי, בכ\"ז אינו בערך כלל לגבי השכלתה והשגתה של הנשמה כמו שהיא<sup data-n=\"145\">145</sup> בה בהיותה למעלה קודם ירידתה להתלבש בגוף, עד כי ההשכלות וההשגות היותר נעלים ונפלאים מה שהנשמה משגת בהתלבשותה בגוף ה\"ה בבחי' יש ממש לגבי ההשגה שהי' לה קודם. דהנה שכל הוא מוכרח התואר, דשכל הוא מציאות, וכל מציאות הרי יש לו תואר ומוכרח בו, להיות כי התואר ההוא מגביל מציאותו במהותו העצמי, ומבדילו בשלילותיו מן הדומה לו שאינו כמוהו, ובכללות הרי השכל שהוא כח המשכיל הכוונה בזה כח המשכיל והמשיג כמו שהוא לעצמו טרם התלבשותו באיזה מושכל ומושג להשכילו ולהבינו ולהשיגו, כ\"א כח המשכיל והמשיג כמו שהוא במציאותו ומהותו העצמי, וכמו החכם הרי קריאת שם חכם הוא ע\"ש העתיד להיות, והיינו ע\"ש היכולת והכח שיש לו להתחכם ולהשכיל בכל דבר חכמה ושכל שהוא מסוגל לה ובאופן שהוא מסוגל, א\"כ הרי קריאת שם חכם הוא אינו ע\"י גילוי המצאת איזה השכלה או ביאור איזה הבנה טובה בהוה, כ\"א ע\"ש ההשכלה וחכמה שעתיד לגלות, והגם שכבר התחכם והשכיל וגילה כמה חכמות והשכלות, זהו רק גילוי דבר שהוא הוא החכם שגילה ההשכלות העמוקות, ואמיתת קריאת שם חכם הוא על כחו בחכמה והשכלה והיינו מה שבכחו להתחכם ולהשכיל, וחכמה ושכל הנה לבד זאת שהיא עצמה כלולה מתחתון ועליון, שכל עליון ושכל תחתון, שהוא שכל עצמי ושכל מסתעף, הנה כללות ענין החכמה והשכל נחלק בג' סוגים כללים, שכל אלקי, שכל אנושי, שכל הטבעי, דכל אחד ואחד מג' אלה ה\"ה מוגבלים כל אחד מהם בגדר מיוחד לו, אבל כללות כולם מוגדרים בההגדרה הכללית דשכל, וכל הגדרה מוכרחת בשתי קצוות מגבילות שהן מעלה ומטה, עליון ותחתון, ובהגדרת כללית ענין המשכיל הנה שני קצוות המגבילות האלו הם, למעלה מן השכל ולמטה מן השכל, והיינו דכשם שלמטה מן השכל אינו שכל, הנה כמו\"כ למעלה מן השכל אינו שכל, רק שהגדרות המטה ומעלה מתרחבים בכל סוג שכל כעוצם מעלת סוג השכל ההוא וכפי מהות ענינו, והיינו דג' סוגי השכל אלקי אנושי וטבעי כל אחד מהם עם היותו מוגבל בענינו ומוגדר במהותו, עם זה ה\"ה מתרחב במרחב רב, ומ\"מ הנה בכל המרחב הזה הנה הוא רק מה שמצטייר בחלקיו שבו, היינו בהעליון ותחתון שבו, אבל עם זה הרי אינו יוצא מהגדרתו העצמי, לא למעלה מסוג שכל זה ולא למטה ממנו, וכמו שכל הטבעי הגם שיש בו מרחב רב שישנם בו חכמות עמוקות ונפלאות בסגולות טבעיות בתכונה רפואה וסגולת הצמחים עד קצהו התחתון בחכמות הבעלי חיים הטפשים והגסים, ומ\"מ הנה כ\"ז הוא רק הצטיירות השכל הטבעי בעניניו, ועם זה אינו יוצא מהגדרתו העצמי לא למעלה ולא למטה. וכן הוא בשכל האנושי שהוא מוגבל בהגדרתו במהותו העצמי, והגם שהאדם הוא משכיל ומשיג נפלא ומ\"מ ה\"ה ג\"כ אינו אלא בחיר הנבראי' לבד, והיינו דבהנבראים בעלי הגוף הוא הבחיר שבהם, ונא'<sup data-n=\"146\">146</sup> הן האדם הי' כאחד ממנו שהוא היחידי בנבראי מטה שיהי' משכיל ומשיג נפלא במושכלות ומושגות הנפלאים ומכוסים, אבל עם זה הרי גם שכלו בשכל אנושי הוא מוגבל בהגדרתו שאינו בערך סוג השכל האלקי, וכמו הדומם שאינו ממהות השכל, ולכן הנה מקור וחום מתפעל הדומם ופועל בו שמתחמם או מתקרר, ומן שכל הרי הדומם אינו מתפעל ממנו, דטעם הדבר",[["143","143","ראה ביאורי הזהר לאדמו\"ר האמצעי אחרי עה, א ואילך. וראה גם לקמן פרק כה (ע' סא). ד\"ה באתי לגני שנה זו (לקמן ע' רצא ואילך). ספר המאמרים תרח\"ץ ע' רכב. וש\"נ."],["144","144","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שבהערה :1 כערך."],["145","145","כ\"ה בכתי\"ק ובהעתקה. שם: שהי'."],["146","146","בראשית ג, כב."]]],[2700520528,"הוא לפי שקור וחום הוא מערכו ומהותו לכן הוא נתפס בזה ותופס אותו ומתפעל ממנו, אבל השכל אינו ממהותו ולכן אינו תופס בו, וכן הוא בשכל אנושי שאינו ממהות סוג שכל אלקי, דכל השגותיו דשכל אנושי הוא בזמן ומקום כפי הגדרת בעלי חומר, והשכל האלקי עם היות דגם בו יש הגדרת זמן ומקום אבל הוא כפי הגדרת הרוחני, והגם דהרוחני הרי יש בו ג\"כ כל ההגדרות אבל הוא באופן רוחני היינו כפי אופן מהותו.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דהנשמה בהתלבשותה בגוף הגם שאינה משתנית מ\"מ השגתה מתגשמת והטעם דשכל הוא מציאות, ומוכרח התואר שמגבילו ומגדירו ממה שלמעלה ושלמטה ממנו, ויבאר ג' סוגי שכל, אלקי אנושי וטבעי, וכולם מוגדרים בהגדרה כללית, וכל אחד מהם הגדרתו כמהותו, והתרחבותו הוא הצטיירותו<sup data-n=\"147\">147</sup>.</span>\n<b>ענינים.</b> ז הנשמה בהתלבשותה מתגשמת. ח שכל, א) מציאות, ב) מוכרח התואר, ג) בו ג' סוגים א) אלקי, ב) אנושי, ג) טבעי.\nיג) <b>והנה</b> ג' סוגי השכל דאלקי אנושי וטבעי עם היותם חלוקים במהותם העצמי, אבל עם זה הרי הנה כולם מוגבלים בהגדרה כללית כנ\"ל, והגם שהם כל אחד מהם מוגדרים במהותו, הנה כל אחד מהם מתרחב ומצטייר במרחב רב כפי מהותו העצמי בעניני עליון ותחתון שבו בערך מהותו, דאינו דומה העליון ותחתון שבשכל הטבעי להעליון ותחתון שבשכל האנושי, ואינו דומה העליון ותחתון שבשכל האנושי להעליון ותחתון שבשכל אלקי, אמנם מאחר דכולם משתוים בכללות ענין אחד שהם מוגדרים, היינו שאין בהם מי שהוא בלתי גבול בעצם מהותו, הנה זה גופא מכריח שיש איזה יחס ביניהם, והיחס הזה אין הפרש כלל אם הוא יחס חיובי או הוא יחס שלילי, דבמושכלות הרי השלילי הוא תואר מגביל כמו החיובי, ואדרבא כל מה שהשכל הוא מופלא ומכוסה הגבלתו והבדלתו הוא ביחס שלילי יותר מכמו ביחס חיובי, דזהו כללות ההפרש בין שכל הטבעי לשכל האלקי, דהשכל הטבעי כל ענין הגבלתו שהוא תוארו הוא בחיוב, והשכל האלקי תוארו המגביל כללות ענינו הוא בשלילה<sup data-n=\"148\">148</sup>, דהחיוב והשלילה הן הנה שני קצוות מגבילות כללות ענין ההשכלה, וא\"כ יובן דהיחס הזה מגביל את המציאות בחלקי פרטי מרחב השכל ההוא, דבכל סוג שכל הלא המרחב וההתפשטות שלו הוא מריבוי מיני שכלים עצמים (איך שהם בעצם מציאותם טרם התלבשותם בהמושכלות כנ\"ל) שמהם הוא שמצטייר העליון ותחתון שבסוג שכל ההוא, א\"כ הרי היחס מסוג שכל אחר מגביל ומתאר מציאותן של העליון ותחתון שבו, וכמו עד\"מ שכל אנושי הרי אינו לא טבעי",[["147","147","הקיצור דשנת ה'שי\"ת: השגת הנשמה בהתלבשותה בגוף הוא יש לגבי השגתה קודם. יבאר זה בהקדים דכל שכל הוא מוכרח ההגבלה וההבדלה. הגדרת השכל בכלל הוא במעלה ומטה, עליון ותחתון, וכן בסוגי השכל אלקי אנושי טבעי."],["148","148","ראה המשך תרס\"ו ע' נח. סה\"מ תרפ\"ט ע' 106."]]],[2700520556,"ולא אלקי, דהאלקי הוא למעלה ממהותו והטבעי למטה מערכו, ובמרחבו העצמי של השכל האנושי היינו בהעליון ותחתון שבו בעצמו ה\"ה משיג ומכיר בהשכלה הטבעית, ומבין ומשער בהשגה<sup data-n=\"149\">149</sup> אלקית, הנה ההשגה וההכרה בהשכל הטבעי, וההבנה וההשערה בשכל האלקי, מגביל ומתאר את פרטי מהות העליון והתחתון שבשכל אנושי, ומבדיל אותו בכללותו בתוארו הכללי שאינו לא טבעי ולא אלקי, כ\"א שהוא אנושי, דזהו מהותו דשכל אנושי שהוא בחיר הנבראים, דבהשכלה טבעית מכירה ומשיגה, ובהשכלה אלקית הוא רק משער ומבין אותה. וכן הוא גם בשכל אלקי דהיחס דשכל אנושי וטבעי מגביל העליון ותחתון שבו, והיינו דזה מה שהשכל האנושי או הטבעי מקבלו הוא התחתון שבו. והנה הנשמה בירידתה למטה ובהתלבשותה בגוף הרי גם אז כל ענינה הוא בהשגת אלקות ובבחי' התפעלות אור אלקי, מ\"מ הרי השגה זאת יכולה להתקבל גם בשכל אנושי, וע\"י שכל האנושי יכולה לבוא הארתה גם בשכל הטבעי, שגם הנה\"ט יבין את השכל האלקי והאור האלקי, דשכל אלקי דבוק באור אלקי, והאור האלקי מתלבש בתוכו, ומובן שהנה\"ט אינו בערך כלל שיבין שכל אלקי כמו שהוא בעצם מהותו, ואינו בערך שיקבל בחי' אור אלקי ממש כמו שהוא, וא\"כ ההשגה האלקית שמתקבל גם בשכל הטבעי הרי בהכרח שאינו אלקות ממש, והוא בבחי' הגשמה ובבחי' יש ממש לגבי מהות מעלת מדריגת הכחות דשכל ומדות אהוי\"ר שיש לה להנשמה קודם ירידתה להתלבש בגוף. דהנה הנה\"א בעצם מהותה העצמי הוא שהוא חלק אלקה ממעל<sup data-n=\"150\">150</sup>, ומהות ענינו בהיותו למעלה שהוא בתכלית הביטול והדביקות, כביטול ודביקות החלק בהעצם שאינו נרגש כלל, ורק כשעלה ברצון הבורא ית' שיהי' נברא, ה\"ה מצטייר בכחות מוגבלים לנברא, אמנם כל כחותיו הם רוחניים ובבחי' התפשטות מן עצמות ומהות הנברא הזה ברצון הבורא ית', כדוגמת זיו המתפשט מן העצם, וכל ענינם של המתפשטים האלו, היינו הכחות, הוא בראי'<sup data-n=\"e23\">*</sup> באלקות, עד כי ההשגה והביטול אחד הוא, להיפך ממש מכמו שהוא בשכל אנושי, דבשכל אנושי הרי השגה הוא מציאות, וביטול הוא היפך המציאות, ובנשמה הרי ההשגה מביא את הביטול, והביטול מאמת את ההשגה, ובירידת הנשמה מתגשם עניני הנשמה, וההתגשמות הוא מה שהכחות מתגלמים בציורם המוגבל, ומתגדל ההשגה על הביטול, אמנם גם אז הרי<sup data-n=\"151\">151</sup> הנה\"א הוא נפלא ועצום ונקראים עובדי הוי' בנשמתן, וטעם הדבר הוא לפי דאמיתת כחות הנה\"א, היינו גם זה מה שהנה\"א בא בהצטיירות נברא גמור כעין ברואי בעלי הגוף, הוא מעין מהותו העצמי, וכנ\"ל דכחות הנפש לגבי הנפש הם",[["149","149","כ\"ה בכתי\"ק. ובספר המאמרים ה'שי\"ת שבהערה :1 בהשכלה."],["150","150","תניא רפ\"ב."],["151","151","בספר המאמרים ה'שי\"ת שם: הרי ביטול."],["e23","*","<b>בראי' באלקות:</b> להעיר בכהנ\"ל מד\"ה ויחלום, תש\"ח (קונטרס נב) פ\"ט ואילך [ספר המאמרים תש\"ח ע' 87 ואילך]. ד\"ה והר סיני, תש\"ח (קונטרס נח [ספר המאמרים שם ע' 209 ואילך])."]]],[2700520573,"כערך אברי הגוף לגבי הגוף, שכמו\"כ הוא בהנה\"א וכחותיו, הנה אמיתית כחות הנה\"א הוא כמו שהוא לעצמו ומשיג במדרי' העליונות שבאלקות, וכדאי' בתו\"א בד\"ה בכ\"ה בכסלו<sup data-n=\"152\">152</sup>, דהשגת והתבוננו' הנה\"א מצ\"ע הוא בענין ד' אחד<sup data-n=\"153\">153</sup> שזה מובן ומושג רק להנה\"א, וההשגה האלקית מה שמתקבל בשכל הטבעי ה\"ה בבחי' הגשמה ויש ממש.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דהגם שהעליון ותחתון שבכל א' מג' סוגי השכל חלוקים זה מזה, מ\"מ להיותם כולם מוגדרים בהגדרה כללית יש להם יחס והיחס אין הפרש אם הוא חיובי או שלילי, ובמילא הרי הא' מתאר ומגביל מהות זולתו, שמזה יובן הפרש כחות הנה\"א דקודם ירידתו ההשגה מביא את הביטול ובירידתו ההשגה מציאות<sup data-n=\"154\">154</sup>.</span>\n<b>ענינים.</b> ט הנה\"א א) למעלה השגה גורם ביטול, ב) למטה השגה מציאות.\nיד) <b>והנה</b> הכוונה העליונה בירידת הנשמה בגוף הוא שהנה\"א יבוא בהתלבשות בשכל הטבעי, דבהתלבשות זו הנה\"א בא לידי השגות מורגשות כאלו שלא הי' לה כזאת קודם, וכן התפעלות המדות שלה ה\"ה בבחי' התפעלות מורגשת בבחי' התגלות הלב. דהנה במדות אהוי\"ר הרי יש בזה ב' מדריגות<sup data-n=\"155\">155</sup>, הא' אהוי\"ר המכוסים, והב' אהוי\"ר המגולים, והגם דשניהם הם בלב, דמקום משכן המדות הוא בלב, אבל הם חלוקים זמ\"ז בתכלית, דאהוי\"ר המכוסי' הוא שהמדות אינן נפרדים מן המוחין, והיינו כאשר ההשגה וההתבוננות היא בבחי' פנימיות המוחין, דהיינו בבחי' אור האלקי כמו שהוא מופשט מלבושי השגה, והיינו בבחי' העצם דהאור האלקי, וכנ\"ל דשכל אלקי הוא דבוק באור אלקי, והאור האלקי מתלבש בשכל אלקי, דאז הנה מאיר גילוי אור המוחין ומתפשטי' בלב ג\"כ, והמדות שבלב נמשכין ממילא אחר המוחין, ולהיות שעצם אור האלקי מאיר אצלו (דלפעמי' מאיר רק שכל אלקי והאור מתעלם בתוכו, אבל כאשר עצם אור האלקי מאיר אצלו) הנה על האור הזה אין שום הגבלה והעכבה, היינו שאינו מתעכב במיצר הגרון<sup data-n=\"156\">156</sup>, ומאיר האור גם בלב והמדות נמשכים ממילא אחר המוח, ומפני שהאור האלקי מאיר בגילוי ממש בהמדות, לכן הן בבחי' התפעלות בלתי מורגשת ובבחי' ביטול ממש, והוא למעלה גם מהתפעלות השכל, והוא בפנימיות הלב מה שהלב נמשך ממילא אחר כוונת",[["152","152","כט, ב ואילך."],["153","153","ואתחנן ו, ד."],["154","154","הקיצור דשנת ה'שי\"ת: יכריח דיש יחס בין סוגי השכל, ויבאר דהיחס מגביל את מציאותו בעליון ותחתון. השגת אלקות דהנשמה בהתלבשותה בגוף מתקבלת גם בשכל אנושי וטבעי, וזה מכריח שאינו אלקות ממש, משא\"כ השגת נה\"א מצ\"ע."],["155","155","ראה גם קונטרס העבודה ע' 7. ספר המאמרים תרס\"ה ע' רמז ואילך. לקוטי שיחות חלק לט ע' 28. וראה מאמרי אדמו\"ר הזקן אתהלך לאזניא ע' נו. ועם הוספות וכו' - ספר המאמרים עזר\"ת ס\"ע פט ואילך."],["156","156","ראה תו\"א וארא נז, ג ואילך. ובכ\"מ."]]],[2700520586,"המוח, ובבחי' ביטול ממש, והאהוי\"ר המגולים דהיינו בהתגלות הלב הוא שהמדות הן נפרדים מההשגה שבמוחין, והיינו כאשר ההשגה היא בבחי' חיצוניות המוחין, שהאור האלקי הוא נתפס בלבושי השגה, וכנ\"ל דהאור האלקי מתלבש בשכל האלקי אבל מתעלם ונתפס בו, ועם היות שגם בזה יש ההרגש מהאור האלקי, אמנם זהו רק שנרגש אצלו בבחי' מקיף שמשיג אלקות, והיינו כנ\"ל דשכל אלקי ה\"ה מצטייר בהגדרה דשכל והגדרת השכל הוא הבנת דבר מה ממש בהבנה מסודרה, וא\"כ כשמבין הענין האלקי שעוסק בהשכלתו, ה\"ה השגת שכל מופלא ואלקות במוחש ממש, דמצד עריבות נעימות המושכלות דשכל אלקי הרי אינו מרגיש בהאור אלקי שמעולה ממנו, וכמו שאנו רואין במוחש, דכאשר האדם רואה או שומע דבר נפלא ונעלה, הנה מצד גודל ההתקשרות בעריבות נעימו' הדבר ההוא אינו יכול לנתק עצמו, אָפּרייסין זיך, ממנו, אפילו לענין וחידוש נעלה ממנו, וכן הוא בשכל אלקי והאור האלקי שבו, דבאמת הנה בעת השגתו הי' צ\"ל נרגש אצלו שמשיג אלקות וכל הענינים שמשיג הכל הוא באלקו', אבל מפני מעלת נעימות השכל אלקי, הנה בלתי נרגש כ\"כ האור האלקי, דזהו הסיבה מה שכמה מעובדי הוי', הגם שמתבוננים היטיב באיזה ענין אלקי, ומ\"מ אין להם חיות בזה ואינם מתפעלים ע\"ז, וסיבת הדבר הוא מפני שבעת ההתבוננו' אינו נרגש הענין אלקי, והיינו שנרגש אצלו רק השכלי ולא האלקות, ומה שנרגש אצלו הוא רק זה מה שמתבונן ומשיג השגה אלקית, ולהיות שההתעסקות שלו וטרדת שכלו הוא בההשגה האלקי' לא בעצם אור האלקי, וכן התקשרות נפשו הוא בההשגה ומזה הוא שמתפעל, לזאת הנה השגה כזאת אינה מאירה בגילוי בלב, רק שההתפעלות שכלי מה שמתפעל במוחו על הטוב דאלקות, הנה זה נעשה מקור להתפעלות המדות, דהתפעלות זאת היא בחיצוניות הלב ובבחי' מורגש ממש, וזהו האהוי\"ר המגולים שבהתגלות הלב שבאה במורגש בחיצוניות הלב, וכך היא המדה בירידת הנשמה למטה שצ\"ל ההתפעלות באופן כזה דוקא לפי שההתפעלות הזאת נרגשת גם בהנה\"ט, והיינו דלאחר שגם הוא יבין כל מה שאפשר לו להבין מההשגה האלקית, הרי גם הוא מתפעל מזה, וגם דאופן התפעלות זאת פועל יותר אח\"כ בההנהגה דכל היום, להיות כל מעשיו לש\"ש דוקא, דהאהוי\"ר בהתגלות הלב דוקא הן בבחי' גדפין<sup data-n=\"157\">157</sup> למעשה המצות, היינו שנותנים חיות בהמצוה ולהיות סו\"מ וע\"ט בבחי' אור וחיות פנימי, וכמ\"ש בסש\"ב פט\"ז<sup data-n=\"158\">158</sup> כי דו\"ר שבהתגלות לבו הם המתלבשים במעשה המצות להחיותם לפרחא לעילא|157. ונמצא דהעבודה צ\"ל בבחי' אהוי\"ר שבהתגלות הלב, אבל מ\"מ הרי גוף ועצם ההתפעלות היא בבחי' יש ובבחי' מורגש, דבהנשמה מצ\"ע אינו שייך התפעלות כזאת ולא ההשגה באופן כזה, הרי שהכחות הרוחנים מתפעלים ומשתנים ע\"י כחות הטבעים, וטעם הדבר הוא מפני שהן בבחי' התלבשות והתאחדות ממש בהכחות הטבעים, ממילא ה\"ה מתגשמים בערך הכחות הטבעים להיות בבחי' חיי בשר.",[["157","157","ראה תקו\"ז ת\"י (כה, ב)."],["158","158","כב, סע\"א."]]],[2700520599,"<span data-k=\"ks\"><b>קיצור.</b> יבאר דהכוונה העליונה שהנה\"א יתלבש בהטבעי, והגם שעי\"ז בא להשגות והתפעלות מורגשות, ויבאר כי באהוי\"ר המכוסים המדות נמשכים במילא ובביטול, והמגולים הנה הגם שהמדות נפרדים מההשגה, כי בנעימות השכל אינו נרגש האור האלקי, אבל יש בזה מעלה כי ההתפעלות היא במורגש ופועל גם בהטבעי.</span>\n<b>ענינים.</b> י אהוי\"ר, א) מכוסים, ב) מגולים. יא. השכל אלקי מעלים על האור האלקי. יב. התפעלות במורגש פועל בהטבעי.\n<b>וזהו</b> כי חק לישראל הוא משפט לאלקי יעקב, דתרין דרגין אינון יעקב וישראל, בקדמיתא יעקב שהוא עבודת הבירורים, ולבתר ישראל לי ראש, שהוא ההמשכה פנימית, ובהמשכות דר\"ה שהו\"ע תקעו בחודש שופר וכו', כנ\"ל דכללות ההמשכה הוא בב' בחי' שפע גשמי ורוחני, אומר כי חק לישראל, שהשפע גשמי הוא לבחי' ישראל, ומשפט לאלקי יעקב, שהוא השפע הרוחני, הטעם הוא לפי דישראל הוא ר\"ת יש ששים ריבוא אותיות לתורה<sup data-n=\"159\">159</sup>, והיינו שהתורה היא הכלי לברכה העליונה שבה וע\"י נמשך שפע ברכה. וזהו כי חק לישראל הוא בהשפעה גשמית לבחי' ישראל, בכדי דע\"י עבודתם בתומ\"צ ימשיכו בחי' אלקי יעקב, והיינו שיעשו את הגשמי כלי לאלקות<sup data-n=\"160\">160</sup>.\nסיום. מזונות לישראל בכדי שיעקב יעשה כלים לאלקות.\n-------------------- * --------------------",[["159","159","ראה זהר חדש רות פח, ד. מגלה עמוקות אופן קפו. וראה ספר המאמרים תרפ\"ט ע' 69."],["160","160","הקיצור דשנת ה'שי\"ת: הכוונה שיתלבש נה\"א בנה\"ט. אז בא להשגות והתפעלות מורגשות. אהוי\"ר המכוסים אינם נפרדים מן המוחין, משא\"כ אהוי\"ר המגולים. ותלוי אם ההשגה בפנימי' המוחין באור האלקי, או בחיצוני' המוחין בשכל האלקי. יתרון אהוי\"ר המגולים שגם נה\"ט מתפעל, ופועלים בהנהגה בכל היום."]]],[2700520056,"<b>אמר</b><sup data-n=\"161\">161</sup> רבא כל המעביר על מדותיו מעבירין לו על כל פשעיו שנא'<sup data-n=\"162\">162</sup> נושא עון ועובר על פשע, למי נושא עון למי שעובר על פשע, רב הונא ברי' דר\"י חלש, על רב פפא לשיולי בי', חזיי' דחליש לי' עלמא (שהי' ר\"ל מסוכן ומיואש מן החיים) אמר להו צביתו לי' זוודתא (הכינו לו צדה לדרך, מה היא צידת המתים תכריכין, רש\"י), לסוף איתפח (נתרפא, רש\"י), הוה מיכסף ר\"פ למחזיי', אמר לי' (לרב",[["161","161","בגוכתי\"ק כ\"ק אדמו\"ר מוהריי\"צ ב\"עניני מאמרי רצ\"ב\", נרשם: \"אמר רבא כל המעביר על מדותיו, ובו ה' פרקים. יח ענינים\". - נעתקו לקמן במקומם."],["162","162","מיכה ז, יח."]]],[2700520106,"הונא) מאי חזית (בעת החולי ר\"ל) אמר להו אין הכי הוה (שנקנסה עליו מיתה ר\"ל, אלא) דאמר להו הקב\"ה, הואיל ולא מוקים במילי' (אינו מעמיד על מדותיו, רש\"י) לא תקומו בהדי' (לא תדקדקו אחריו, רש\"י) שנא' נושא עון ועובר על פשע, למי נושא עון לעובר על פשע, לשארית נחלתו|162, אמר רבי אחא בר חנינא אלי' וקוץ בה, לשארית נחלתו ולא לכל נחלתו, למי שמשים עצמו כשיריים (ר\"ה די\"ז ע\"א). והנה המעביר על מדותיו הוא ע\"י עבודת הלב, דמקום משכן המדות הם בלב, ולהיות מעביר על מדותיו הוא ע\"י עבודת הלב, ולכאו' הרי עבודת המוח היא למעלה במעלה ומדריגה מעבודת הלב, ואומרו כל המעביר על מדותיו משמע דמדייק עבודת הטבת ותיקון המדות דוקא. דהנה בעבודת המוח הוא ג\"כ שפועל במדות שבלב, אלא שזה בא בדרך ממילא, מגילוי אור המוחין בלב, ועבודת הלב הוא הכוונה דכל עבודתו הוא בתיקון וזיכוך המדות דוקא, ועי\"ז הוא שמעבירין לו על כל פשעיו, ולא זו בלבד אלא שזוכה לחיים, ורק בתנאי למי שמשים עצמו כשיריים, דמשמע דמה שמשים עצמו כשיריים הוא המשך העבודה, והיינו שאינו שיריים ממש אלא שמשים עצמו כשיריים, והגם שרק משים עצמו כשיריים, הוא המשך העבודה האמיתית דמעביר על מדותיו שהוא עבודת הלב.\n<b>התחלה.</b> יקשה הלא עבודת המוח גבוה מעבודת הלב ולמה המעביר על מדותיו מעבירין וכו' וזוכה לחיים.\n<b>ולהבין</b> זה ילהק\"ת מה שנת\"ל דבכל הנבראים יש בהם ב' ענינים, הא' גוף הנבראי' שהוא חומר, והב' אור שפע האלקי השופע בו שהוא צורת הנבראי', ודבר זה הוא בשוה הן בהנבראי' התחתונים והן בהנבראי' העליונים, וחומר הנבראי' נקרא בשם חשך לגבי אור נפשם ונשמתם, אמנם בהתלבשות האור בהנברא נעשה כערכו ומהותו של הנברא, ויבאר בהנפש וכחותיו באופן שהם טרם התלבשותם שהם מופשטי' מהחוש דגשם לגמרי, ובהתלבשותם נעשי' כערך כחות הטבעים, ויבאר דשכל הוא מציאות, וכל מציאות מוכרח ההגבלה עליון ותחתון, ובכללותו נחלק לג' סוגי', שכל אלקי אנושי וטבעי, דכל אחד מתרחב במרחב רב, אמנם זהו ההצטיירות דפרטי חלקיו במציאותו העצמי ועם זה אינו יוצא מהגבלתו והגדרתו, אבל כולם מוגדרים בהגדרה כללית שזה מורה בהיחס שביניהם, וביחס זה אין הפרש אם הוא יחס חיובי או שלילי, דהיחס הזה לבד שמתאר מציאותן של חלקיו העצמיים במעלה ומטה שבו בעצמו ובכללות תוארו וענינו המוגבל, הוא גם מגביל חלקי המציאות של מי שהוא מתייחס אליו, ובזה יבאר כי מה שהשכל הטבעי משיג השגה אלקית הוא רק המדרי' היותר אחרונה והמטה שבשכל אלקי, ויבאר כי הכוונה העליונה בירידת הנשמה הוא זה שהנה\"א יתלבש בהנה\"ט, דע\"י התלבשות בא לידי השגות והתפעלות מורגשות, כי במדות יש אהוי\"ר מכוסי' ומגולים, וההפרש שביניהם, אמנם הכוונה העליונה בשביל העבודה בבירור וזיכוך הוא ע\"י אהוי\"ר המגולים שהם בהתגלות הלב, שבזה ב' ענינים, הא' דגם הנה\"ט יכול לקבלו ואפשר לו לבוא באהבה לד', והב' שנוגע בעבודה בפועל בכל היום שיהיו עשיותיו"],[2700520156,"לש\"ש כמ\"ש רבינו בסש\"ב כי דו\"ר שבהתגלות לבו הם המתלבשים במעה\"מ להחיותם לפרחא לעילא, הרי דכחות הרוחניים בהתלבשותם בכחות הטבעים מתגשמים כערך הכחות הטבעיים להיות בבחי' חיי בשר.\nטו) <b>והנה</b> כשם שהוא באור וחיות הנפש שמתלבש באברי הגוף הנה הגם שהוא רוחני ה\"ה מתגשם להיות בערך הכחות הטבעים, הנה כמו\"כ הוא בבחי' אור וחיות אלקי שבנבראים, דהגם שזהו בחי' הצורה והאור שבנבראים, מ\"מ הנה להיות שבא בהתלבשות ממש בהם ה\"ז בא בבחי' הגשמה לפ\"ע הנבראים. דכן הוא גם בנבראים העליונים, וכמו אופנים וחיות שהם ג\"כ כלולי' מחומר וצורה, הנה החיות המתלבש בתוכם להחיותם מאין ליש הרי נת\"ל שהוא באין ערוך לגבי כמו שהוא טרם שמתלבש בתוכם אשר מזה הוא התפעלות המלאכים והרצוא שלהם בהתפעלות ורעש גדול, וכנ\"ל דכל התפעלות היא באה בסיבת איזה התעוררות המביאה וגורמת ההתפעלות, דלכן הנה לפי אופן הסיבה כן יהי' גודל ההתפעלות, וכן הוא בהתפעלות המלאכים והרצוא שלהם, דלבד זאת שמשיגים איך שהתהוותם הוא מאין ליש, שזהו רק ע\"י הארה לבד, והיינו שזהו בחי' מל' דאצי' שנקרא זיו והארה, וכמא'<sup data-n=\"163\">163</sup> מלך שמו נקרא עליהם שהוא בחי' שם לבד, וכמו למטה הרי הנהגת המלוכה הוא בפקודת המלך וציוויו שהוא בעצמו סגור בהיכלו ורק שמו מתפשט בהמדינה, כמו\"כ הדוגמא מזה למעלה שספי' המל' הוא בחי' שם בלבד, אבל מהו\"ע ית' הוא קדוש ומובדל לגמרי, הנה מזה ה\"ה מתפעלים במאד, הנה לבד זאת, הנה כאו\"א מהם רואה ומשיג<sup data-n=\"e24\">*</sup> את החיות שלו המהווה ומחי' אותו מאין ליש, ואיך דבחי' חיות זה כלול ונמצא במקורו בבחי' מל' דאצי', ואופן התכללותו של החיות במקורו הוא ע\"ד כמו שנמצא האור והזיו של השמש במאור השמש, אשר שם הוא באופן נעלה הרבה יותר, והיינו שהוא בבחי' ביטול בתכלית שם, כמ\"ש בסש\"ב<sup data-n=\"164\">164</sup>, אשר כמו\"כ הנה חיות כל הנבראים נמצא וכלול בבחי' מל' דאצי', וכדאי' בע\"ח<sup data-n=\"e25\">*</sup> שיש כל מיני דצ\"ח באצי', והיינו כמו שהמל' נקראת בכמה שמות כמו בשם סלע אבן ובשם שושנה וכו' שזהו חיות הנבראי' הנמצא וכלול בבחי' מל' דאצי', והיינו שאותו הזיו והחיות הנמשך ממנו ית' להחיות האבן דבי\"ע הנה הוא מלובש בג' אותיו' אב\"ן<sup data-n=\"e26\">*</sup>, וזהו בחי' אבן דאצי', דהיינו החיות של האבן, וכן עד\"ז בשארי השמות שהמל' נק' בהם, וזהו שהאור והכח והחיות<sup data-n=\"e27\">*</sup> של כל נברא ונברא נמצא וכלול במקורו והוא שם",[["163","163","ע\"פ פיוט אדון עולם."],["164","164","פל\"ג. וראה שעהיוה\"א פ\"ג."],["e24","*","<b>רואה ומשיג:</b> להעיר מרמב\"ם הל' יסוה\"ת פ\"ב ה\"ח ופ\"ג ה\"ט."],["e25","*","<b>וכדאיתא בע\"ח:</b> בסופו [שער נ (שער קיצור אבי\"ע) ספ\"י]."],["e26","*","<b>בג' אותיות אב\"ן:</b> ראה שער היחוד והאמונה ספ\"ז [פד, ב]. תו\"א פ' משפטים ביאור לד\"ה ותחת רגליו [עח, סע\"ב]."],["e27","*","<b>שהאור והכח והחיות:</b> עמ\"ש בדרוש אוא\"ס בכחך הגדול [אוה\"ת ענינים ע' קלה] איך שכל נברא יש בו ג' מיני חיות והן בחי' אור וחיות וכח והיינו מבחי' האו\"מ והאו\"פ והכלים (ד\"ה וראיתי אני, חה\"ש תרע\"ד [המשך תער\"ב ח\"א ע' תפט])."]]],[2700520206,"במדרי' נעלית ומשובחת באין ערוך, והגם דזהו אור חיותו של נברא זה, היינו כל נברא ויצור בפרט, ובהכרח לומר דכשם שהנבראי' חלוקים בחומר גופם, כן הם מתחלקים בהאור ושפע האלקי הנמשך להם להחיותם, דזהו צורת הנבראי', ובחומר הנבראי' הרי אנו רואי' דאינו דומה גוף חומרו של הסלע ואבן לגוף חומרו של השושנה, דעם היות דשניהם הם גשמים וחומרים, ומ\"מ הרי בחומריות גופא הרי יש בזה חילוקי דרגות, וכמו בגוף האדם הרי חומר המוח עם היות שהוא כלי אל אור השכל והוא כלי מקבל פנימי, והיינו דבריבוי שקידה במושכלות מתגדל המוח, דהגדלה זו נעשית עי\"ז שהשכל עצמו נעשה מוח, אשר משו\"ז הנה מזמן לזמן הוא נעשה כלי יותר אל עמקי המושכלות<sup data-n=\"165\">165</sup>, דבשכל הרי העיקר הוא ההבנה והעומק, מ\"מ ה\"ה חומר גשמי, ועם היותו חומר גשמי ממש שהוא נתפס בכל ההגבלות וההגדרות דגשם, ונפעל מכל המקרים דגשם וחומר מתפעל ממנו<sup data-n=\"166\">166</sup>, ומ\"מ הרי אינו דומה לגשם וחומר בשר העקב, ואפילו לחומר בשר בכלל, והיינו דעם היות שהוא ג\"כ חומר, אבל הוא חומר אחר לגמרי, הרי אנו רואים במוחש דהחומרים אף שכולם מוגבלים בענינם ומוגדרים במהותם, ומ\"מ הרי יש בהם ריחוק הערך זה מן זה כאילו היו סוגים נבדלים זה מזה. והנה באור וחיות הנפש שמתלבש להחיות, הרי אופן המשכת החיות הוא לכל נברא שהוא לכל חומר לפי ערכו ומהותו, וכנ\"ל דכשם שבהגוף יש בו אברים כן הוא גם בנפש שיש בו אברים, ונת' דכשם שאברי הגוף בכל נברא הם מעצמות ומהות גופו שהוא חומרי ולא רוחני, הנה כמו\"כ אברי הנפש בכל נברא הוא מעצמות ומהות נפשו, א\"כ הרי בהכרח לומר דהאור והכח והחיות של כל נברא ונברא הנה גם בהיותו כלול ונמצא במקורו ה\"ה חלוקים בענינם לפי עצם מעלתם ומדריגתם, וא\"כ מהו מעלתו של החיות בהיותו כלול במקורו, הנה האמת הוא כן שגם שם הם חלוקים זמ\"ז, אמנם הנה לבד זאת דעמידתם שם הוא במדרי' נעלית ומשובחת באין ערוך, והיינו שהם במדרי' אחרת לגמרי, וכנ\"ל בענין שכל אנושי ושכל אלקי הרי גם השכל אלקי הוא מוגבל בענינו ומוגדר בזמן ומקום, ורק שהזמן ומקום דשכל אלקי הוא זמן ומקום רוחני, שזהו\"ע ענין<sup data-n=\"167\">167</sup> אחר לגמרי<sup data-n=\"e28\">*</sup> מזמן ומקום שלנו, הנה כמו\"כ הוא בזה דהאור והכח והחיות של כל נברא הנמצא כלול במקורו באופן מעולה ומשובח שהוא באופן אחר לגמרי, הנה לבד זאת הרי זה מה דכללות כולם משתווים בההגדרה כללית דבחי' ביטול בתכלית, כמו שהוא ביטול האור בהיותו כלול במקורו בהמאור, וכידוע דהא בהא תליא, דלפי מעלת",[["165","165","ראה גם ד\"ה שימני כחותם תר\"ץ. ספר המאמרים תרצ\"ז ע' 254. תש\"ד ע' 243."],["166","166","בספר המאמרים ה'שי\"ת שבהערה :1 מהם."],["167","167","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים שם: שזה הוא ענין."],["e28","*","<b>ענין אחר לגמרי:</b> ראה רמב\"ם הל' יסוה\"ת פ\"ב ה\"ו. לקו\"ת פ' בחוקותי ד\"ה בשברי לכם [מח, ב]. סהמ\"צ להצ\"צ סוף מצות האמנת אלקות. ובכ\"מ."]]],[2700520256,"האור בעצם כן הוא מעלת ביטולו<sup data-n=\"168\">168</sup>, א\"כ הרי הביטול הלזה שאינו עולה בשם אור וזיו כלל ה\"ז מורה על גודל מעלת האור, כמו\"כ הנה בהאור והחיות כמו שהוא כלול במקורו הוא במעלה משובחת ביותר.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דהאור האלקי שבא בהתלבשות מתגשם, התפעלות המלאכים א) משיגי' דהתהוותם מאין ליש, ב) משיגים חיותם הכלול במקורו מל' דאצי' מקור כל הנבראי' ולכן נקראת בשמות דצ\"ח. ויבאר דכשם שיש חילוקים במהות חומר הנבראים, כן יש חילוקים בחיות א\"כ מהו מעלתו דחיות הכלול במקורו, ויתרץ דכל אור ביטולו לפי מעלתו ויסביר מה הגדרה דשכל אלקי וטבעי<sup data-n=\"169\">169</sup>.</span>\n<b>ענינים.</b> א. התפעלות המלאכים, א) מהשגת מקור התהוותם, ב) מביטול חיותם במקורו. ב. הנבראים חלוקים בחיותם כמו בחומרם.\nטז) <b>והנה</b> כאשר המלאכים משיגים זאת איך דהריבוי רבבות נבראים הנה כולם בצביונם ישנם בהתכללות בבחי' מל' דאצי', ובאופן משובח ונעלה באין ערוך, הנה מזה הן מתפעלים מאד בבחי' יציאה מהגבלתן, וטעם הדבר הוא לפי דכל אור וחיות כמו שהוא במקורו הוא במדרי' נעלית בתכלית הרוחניות, והיינו דהגם שהוא אור וחיות המוגבל להחיות, וכל אור וחיות המוגבל להחיות ה\"ה כבר מצטייר באיזה ציור מוגבל להחיות, מ\"מ בהיותו עוד במקורו ה\"ה במדרי' נעלה ומשובח באין ערוך מכמו שהחיות בא אחרי כן בחיותו המוגבל להחיות בפועל. ולקרב אל ההבנה איך הוא זה אשר דבר מוגבל בציור פרטי, מ\"מ הנה בהיותו כלול במקורו הוא באופן מעולה ומשובח באין ערוך כלל לכמו שהוא בא בפועל, והיינו דהגם שבהיותו כלול במקורו ה\"ה באותו הציור ממש כמו שבא בפועל, ומ\"מ ה\"ה באופן מעולה ומשובח באין ערוך, הנה יובן דוגמתו בלבושי הנפש דמח' ודיבור, דהנה מחשבה ודיבור שניהם לבושי הנפש, דמח' היא ג\"כ רק לבוש אל הנפש, והדיבור הוא ג\"כ לבוש אל הנפש, רק דכל אחד מהם מוגדר בהגדרה מיוחדת, דגדר המחשבה שהוא רק לעצמו, וגדר הדיבור הוא שהוא גילוי אל הזולת, דהגדרה זו היא גם בדיבור שבמחשבה, ובמחשבה שבדיבור, דהנה<sup data-n=\"170\">170</sup> במח' יש<sup data-n=\"e29\">*</sup> מח' שבמח' דיבור שבמח' ומעשה שבמח', וכן בדיבור יש מח' שבדיבור דיבור שבדיבור ומעשה שבדיבור, דמח' שבמח' הוא מחשבת השכל והאותיות בלתי ניכרי', אמנם אין זה",[["168","168","ראה גם המשך תער\"ב ח\"ב ע' תקע."],["169","169","הקיצור דשנת ה'שי\"ת: חיות האלקי שבנבראים בא בהגשמה. יכריח דגם בהיותו כלול במקורו חלוק זמ\"ז לפי מהות הנבראים, יפרש א) דהוא שם באופן משובח באין ערוך, ב) דכולם משתווים בהביטול בתכלית, המורה על מעלתם."],["170","170","ראה גם לקמן ע' שטז ואילך."],["e29","*","<b>במחשבה יש:</b> ראה אגה\"ק סו\"ס יט [קכט, א]. לקו\"ת תזריע ד\"ה קאמיפלגי במתיבתא פ\"ב [כג, ב]. אמרי בינה שער הק\"ש פל\"א ואילך."]]],[2700520306,"שאין שם אותיות, דהרי מחשבה הנה כל ענינה הוא אותיות אלא שמפני עוצם הבהקת האור הרי האותיות בלתי ניכרים ובלתי נרגשים כלל, ומהמח' שבמח' בא בדיבור שבמח' שהוא התגלות האותיות, ועם היות דאותיות אלו הרי אינם כמו האותיות דמח' שבמח', אבל מ\"מ הרי גם אותיות אלו דדיבור שבמח' ה\"ה נשמעים אל השכל, והיינו שאין זה ליקוטי אותיות מבחוץ אלא שהם נלקטים ע\"י השכל עצמו. ויובן זה מענין הציור, דהכותב איזה ציור, הרי כתיבת הציור הגם שבא בציורי קוים בדוגמת אותיו' הכתב, ומ\"מ הרי אין זה בדומה כלל, דבאותיות הכתב הגם שהם כלים אל השכל, אבל הם עצמם אינם באים מן השכל עצמו, והם אינם אלא מה שהם מכילים בעצמם אור שכל זה, והיינו שהם כלים אל השכל, משא\"כ בכתיבת הציור הרי השרטוטים באים מן המושכל והנושא שבהציור, דזהו ההפרש בין פועל לאומן, דשניהם יודעים את נושא הציור, רק שהפועל הוא מה שעושה שרטוטים וקוים כאלו שהם מכילי' בעצמם הנושא והמושכל של הציור ההוא, משא\"כ האומן הנה הגם דגם הוא עושה שרטוטים וקוים, אבל השרטוטי' והקוים באים כמו בדרך ממילא מהמושכל בנושא הציור ההוא, דלהיותו מסור נתון ודבוק בהשכלת נושא הציור, דבכל ציור הרי יש בו נושא הציור, היינו כל חיותו ומחזה תנועותיו של הציור ההוא, דיא לעבעדיקייט און דיא אינערליכע תנועות פון דעם ציור, והמצייר האומן כשהוא כותב את הציור ה\"ה כולו מסור נתון ודבוק בהחיות פנימי שבהשכלת נושא הציור ההוא, ומתוך דביקותו הנה השרטוטים בהקוים בכללם ואופניהם בפרטיות בא כמו בדרך ממילא, דזהו ענין האימון מה שהוא אומן יד, שהאימון שבידיו מוציא, טראָגט אַרוייס, מן הכח אל הפועל, כמו בדרך ממילא אותו החיות פנימי והשכלת הנושא שבהציור ההוא, כפי שהוא בעומק פנימיות הרגשתו כפי כשרון כחו בציור<sup data-n=\"171\">171</sup>, א\"כ הרי אין זה מה שהמצייר עושה שרטוטים וכותב קוי הציור, אלא שזהו מה שהציור עצמו מצטייר ע\"ג הנייר בכל חיותו ובכל חזיונו, כאילו הוא נצב חי ממש, והוא בא ע\"י אימון ידיו של האומן וחכם גדול בחכמת הציור, דזהו מעלתו לגבי הפועל, דהפועל הגם דגם הוא כותב ציור, וגם בהציור שהוא מצייר יש בו כללות הנושא של השכלת הציור ההוא, אבל זהו רק בדוגמת אותיו' הכתב שמכילים בעצמם האור שכל שמתלבש בהאותיות ההם, דבאותיות השכל דהגם<sup data-n=\"172\">172</sup> דכל השכל ההוא בכל עומקו נמצא בהאותיות אבל הוא בההעלם<sup data-n=\"173\">173</sup>, דזה מה שאותיות מחכימות<sup data-n=\"174\">174</sup> הוא דוקא לאחר הבנת הענין מדקדק בהאותיות והן מחכימות אותו, אבל גוף ועצם האותיות הרי אין בהם החיות של המושכל ההוא, וכן הוא גם בשרטוטים וקוי הציור של הפועל שהם מורים על נושא הציור בלבד, משא\"כ בהשרטוטים וקוי הציור דאומן יד וחכם בחכמת הציור, שהשרטוטים וקוי הציור באים כמו בדרך ממילא מהציור עצמו, דאז הנה נראה ונגלה בהם החיות פנימי",[["171","171","בספר המאמרים ה'שי\"ת שבהערה :1 שבציור."],["172","172","שם: הגם."],["173","173","שם: בהעלם."],["174","174","של\"ה קצא, ב. מגדל עוז לרמב\"ם הל' אישות פ\"ד ה\"ט. הל' גירושין פי\"א הט\"ו. ובכ\"מ."]]],[2700520356,"ככל<sup data-n=\"175\">175</sup> עומק השכל נושא הציור ההוא. וכמו\"כ יובן בדיבור שבמח' שהאותיות נשמעים אל השכל, ואין זה מה שהוא מלקט אותיות שיהיו כלים אל השכל ההוא, והיינו דהשכל עצמו מצטייר באותיו' אלו. וההפרש בין אותיות אלו דדיבור שבמח' להאותיות דמח' שבמח' הוא בב' ענינים, הא' דבמח' שבמח' הגם שישנם להאותיו' אבל הם בלתי נרגשים כלל, דכל ההרגש הוא אור, אַלץ ואָס עס הערט זעך איז אַלץ שכל, אַלץ אור, און דער אור ויא ער איז לעצמו. ובדיבור שבמח' הוא התחלת הרגשת הכלי אל אור, והב' דבמח' הוא באופנים שונים ובדיבור שבמח' הוא בא מפורט בענין אחד. והרהור הוא מעשה שבמחשבה, דבהרהור הרי האותיות באים בהגבלה כללית. דכ\"ז הוא בהציור קומה דמחשבה, דבכללותו הוא מוגדר בהגדרתו המיוחדת שהוא לעצמו.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דהחיות הכלול במקורו הגם שהוא פרטי הוא נעלה ומשובח, ויבאר ענין המח' א) הגדרתה שהיא לעצמו, ב) עיקרה אותיות ג) יש בה מחדו\"מ, מח' שבמח' אין האותיות ניכרים, דיבור שבמח' השכל מלקט אותיותיו בדוגמת מצייר אומן שהקוים באים מרגש נפשו, מצייר פועל כתב שבציור, מח' שבמח', א) הבהקת השכל, ב) באופנים שונים, דיבור שבמח', א) הרגש אותיות, ב) מפורט באופן א'<sup data-n=\"176\">176</sup>.</span>\n<b>ענינים.</b> ג. מחשבה א) הגדרתה לעצמו, ב) יש בה מחדו\"מ, ג) עיקרה אותיות. ד. מח' שבמח' א) הבהקת השכל, ב) באופנים שונים. ה דיבור שבמח', א) ליקוטי אותיות, ב) אופן פרטי, ג) בדוגמת מצייר אומן. ו מעשה שבמח' א) הרהורי אותיות, ב) מוגבלים ומסודרים, ג) בדוגמת מצייר פועל. ז צייר, א) אומן, ב) פועל.\nיז) <b>והנה</b> לבוש הדיבור יש בו ג\"כ ג' ענינים מחשבה שבדיבור, ודיבור ומעשה שבדיבור, ולהיות שהדיבור הגדרתו הכללית שהוא בשביל הזולת, לזאת הנה גם המח' שבדיבור הוא בהתחלקות, והוא בב' ענינים, הא' הוא מה שאמרה ד\"פ בינו לבין עצמו<sup data-n=\"e30\">*</sup>, דאמירה זו ענינה המדידה וההגבלה שיהי' לפ\"ע מהותו של המקבל, והב' הוא המח' בעת הדיבור שהוא הסתכלות פנימי בהענין איך הוא מתקבל אצל המקבל, ובא בדיבור מפורש בדברים ברורים ובשפה ברורה כמ\"ש<sup data-n=\"177\">177</sup> אמר לחכ' אחותי את, בהלכה ברורה<sup data-n=\"e31\">*</sup>, ולא בדברים דמשתמעי לתרי אפי, ובא במעשה שבדיבור בגילוי אל הזולת בשכל מוגבל ומפורט, דהאותיות האלו הן הנה האותיות שבמחשבת",[["175","175","כ\"ה בהעתקה. בכתי\"ק ובספר המאמרים ה'שי\"ת שבהערה :1 בכל."],["176","176","הקיצור דשנת ה'שי\"ת: יבאר דהאותיות דמחשבה שבמח' אין נרגשים, והם באופנים שונים, דדיבור שבמח' נרגשים ובאופן אחד אבל באים במילא מהשכל וכדוגמת האומן, דמעשה שבמח' הם בהגבלה כללית."],["177","177","משלי ז, ד."],["e30","*","<b>שאמרה .. עצמו:</b> ע\"פ שמות רבה רפ\"מ. וראה לקו\"ת ר\"פ האזינו [עא, ג]."],["e31","*","<b>בהלכה ברורה:</b> הכוונה למרז\"ל שבת קמה, ב."]]],[2700520403,"השכל, ובכל המשך השתלשלותם הרי לא התחדש בהם דבר כלל, כי גם בהיותם במחשבה שבמחשבה מכוסים בעוצם הבהקת אור השכל היו אותיות אלו ממש, דג' חכמים אומרים שכל וסברא א' וכל אחד אומרה באותיותיו כפי גילוי אור שכלו בהלבוש דמח' שבמח', וכמו הרי\"ף הרמב\"ם והרא\"ש<sup data-n=\"e32\">*</sup> אומרים כולם סברא אחת כל אחד באותיותיו דוקא, דזהו חלקי ד' אמרה נפשי<sup data-n=\"178\">178</sup>, ולכן בדקדוק לשונם מוציאי' סברות להלכה, א\"כ הרי אותיות אלו כשבאי' בדיבור שבדיבור הרי אין בהם התחדשות כלל, כי גם בהיותם במח' שבמח' היו כבר מצויירים ומוגבלים, ומ\"מ הרי אין ערוך אותיות כמו שהם במח' שבמח' לכמו שהם במעשה שבדיבור. דכמו\"כ יובן בדרך דוגמא בהאור והחיות המוגבל להחיות, דבהיותו כלול במקורו ה\"ה במדרי' נעלה ומשובח בתכלית הרוחניות, וכאשר המלאכים משיגים זאת בכלל, ובפרט בהרגש חיותן, לכן הנה ההתפעלות שנעשה מהשגה זו היא אופן התפעלות יציאה מגדר הגבלה, והיינו דלפי שהחיות כמו שהוא במקורו הוא באין ערוך בדרך מובדל לגמרי לזאת הנה גם ההתפעלות הנעשה מזה הוא באופן יציאה מגדר ההגבלה. אמנם הנה אור וחיות זה כמו שמתלבש בהנברא ה\"ה בא בהגשמה לפ\"ע מהות הנברא, דהנה כללות האור שנמשך אל הנבראי' להוותם ולהחיותם הוא בבחי' כח הפועל בנפעל, וכח הפועל בנפעל בד\"כ הוא באין ערוך לגבי מקורו, לפי שכח ופועל הרי אין הכוונה שהנפעל הוא גשמי לגבי כח הפועל כ\"א גם כח הפועל בהנפעל הוא כמו גשמי לגבי רוחני, והיינו שהוא באין ערוך לגבי מקורו, דבכחות הנפש אנו רואין דענין הכח הוא ענינו לפעול פעולת דבר מה בהתחדשות דוקא, ובא בכמה אופנים שונים, בכל כח לפי מהותו וענינו, כמו כח השכל, כח הראי', כח הדיבור וכח המעשה, שהם כולם כחות פועלים ופעולותיהם שונות לפי מהותם, והגם שאינו דומה כח השכל להכחות דראי' ומעשה, דכח השכל הגם שהוא בא בהשגת דבר מה שחוץ לעצמו שה\"ה משכיל ומשיג בדבר שחוץ ממנו, מ\"מ ה\"ה הכל בו בעצמו<sup data-n=\"179\">179</sup>, משא\"כ בראי' הגם שהוא ג\"כ בדבר שחוץ ממנו, אבל אופן פעולתו הוא לקרב את הדברים שחוץ ממנו לעצמו, וכח הדיבור הנה פעולתו הוא לגלות במה שחוץ ממנו, היינו לזולתו, אמנם עכ\"פ אינו נפרד מהאדם עצמו, אבל כח המעשה הרי פעולתו הוא אך ורק בדבר שחוץ ממנו ונתעצם בו, שהארת כח הפועל נמצא תמיד בהנפעל, אשר באמת כן הוא בהחיות אלקי שהוא בבחי' כח הפועל בנפעל, שהאין האלקי הוא",[["178","178","איכה ג, כד."],["179","179","בספר המאמרים ה'שי\"ת שבהערה :1 מ\"מ הרי הכל הוא בעצמו."],["e32","*","<b> הרי\"ף הרמב\"ם והרא\"ש:</b> להעיר עד כמה מדויק גם ענין שבדרך אגב הבא בדא\"ח: בכ\"מ מובאים לדוגמא ראשונים אחרים, וכמו בלקו\"ת ראה רד\"ה ושמתי כדכד (הראשון [כד, ד]) מביא את תוס' רא\"ש והר\"ן. - והחילוק מובן, דבלקו\"ת מדבר בשכל ובסברתו ולכן מביא ראשי הפרשנים. ומתחיל בתוס' שיש בו ריבוי אותיות, משא\"כ פרש\"י, ועליו מונה הרא\"ש והר\"ן המביאים לעתים תכופות ביותר סברות התוס' גופא. אבל כאן מדבר בשכל ובהחלטתו, הלכה ברורה, ולכן מובאים הרי\"ף הרמב\"ם והרא\"ש שהם \"עמודי ההוראה אשר הבית בית ישראל נשען עליהם בהוראותיהם\" (הקדמת הבית יוסף [לטור או\"ח])."]]],[2700520450,"עומד תמיד בהיש להוותו ולקיימו, וכתי'|119 לעולם הוי' דברך נצב בשמים, דהדבר הוי' דיהי רקיע עומד תמיד בשמים להוותו ולהחיותו, ואם ח\"ו יופסק כרגע יבטל הכל והי' כלא הי', דזהו ההפרש בין כח הפועל של הנברא לאמיתת ענין כח ופועל, דזה מה שהכח נמצא תמיד בהפעולה אשר פעל, הרי אין זה לצורך קיום הנפעל, אלא שכן הוא ענינו של כח הפועל, דגם לאחר שפעל את פעולתו וסילק את כחו, הרי גם אז הנה רישומו ניכר<sup data-n=\"e33\">*</sup> כל משך קיומו של הנפעל ההוא, והוא מצד התקשרות הפועל בפעולתו, אבל בפועל של מעלה ית' הרי הכח מהוה את הפועל ומקיימו, ורק זה לבד הוא כל קיומו של הנפעל, ומבלעדו הרי יבטל כל<sup data-n=\"180\">180</sup> מציאותו לגמרי והי' כלא הי'. א\"כ יובן דבכח ופועל הרי לא זה בלבד שהגשמי הנפעל נקרא בשם פעולה, אלא דגם כח הפועל עם היות שהוא רוחני ה\"ה ג\"כ נקרא בשם פעולה, והוא באין ערוך לגבי מקורו, וכנודע<sup data-n=\"e34\">*</sup> דבחי' מל' דאצי' שמתלבשת בבריאה להיות בבחי' מקור וחיות לנבראים דברי' זהו ע\"י בקיעת הפרסא שבין אצי' לברי', שזהו בחי' אור של תולדה בלבד שבאין ערוך לגבי האור שלפני הפרסא, ולזאת הנה בהתלבשות האור בנבראים ה\"ה נעשה לפ\"ע מהות הנבראים.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דהדיבור א) הגדרתו לזולתו, ב) יש בו מחדו\"מ, מח' שבדיבור, א) בינו לבין עצמו, ב) מסתכל איך מתקבל, דיבור שבדיבור דיבור מפורט, מעשה שבדיבור שבא בגילוי לזולתו, מעשה שבדיבור הוא הגילוי דמח' שבמח', ויבאר דכח ופעולה גם הכח נק' פועל לגבי מקורו<sup data-n=\"181\">181</sup>.</span>\n<b>ענינים.</b> ח. דיבור, א) הגדרתו לזולתו, ב) יש בו מחדו\"מ. ט מח' שבדיבור, א) בינו לבין עצמו, ב) בעת הדיבור. י דיבור שבדיבור, דיבור מפורט. יא. מעשה שבדיבור, הגילוי לזולתו. יב כח ופועל, א) בכחות הנפש, ב) באור האלקי.\nיח) <b>והנה</b> בחי' האור הזה שמתלבש בנבראים, וכמו\"כ כללות האור השייך אל הנבראים, עם היות שהוא בבחי' אור וחיות אל הנבראים, ומהות וחומר הנברא נק' חושך לגבי' כנ\"ל, הנה מ\"מ גם האור הזה נק' חושך, וטעם הדבר הוא<sup data-n=\"182\">182</sup> דמאחר שהוא בא להאיר את החושך לזאת הנה גם הוא בהתלבשותו בהם, וגם כללות האור הזה ה\"ה בבחי' חושך. אמנם להיותו אור לזאת|180 נק' בשם אש , וכמ\"ש<sup data-n=\"183\">183</sup> כי",[["180","180","בספר המאמרים ה'שי\"ת שבהערה 1 ליתא תיבה זו."],["181","181","הקיצור דשנת ה'שי\"ת: יבאר מחדו\"מ שבדיבור. האותיות דמעשה שבדיבור ה\"ה האותיות דמח' שבמח', ומ\"מ הם באין ערוך, ועד\"ז הוא ג\"כ חיות הנברא בהתלבשותו, וכשהוא כלול במקורו. כח הפועל בנפעל הוא באין ערוך לגבי מקורו."],["182","182","ראה גם ספר המאמרים עטר\"ת ע' נו. תרח\"ץ ע' קט."],["183","183","ואתחנן ד, כד."],["e33","*","<b> רישומו ניכר:</b> ראה שער האמונה - לאדמו\"ר האמצעי - ספכ\"ז [מח, ב]. ד\"ה ויבוא עמלק תש\"ט (קונטרס סב) פ\"ד [ספר המאמרים תש\"ט ס\"ע 37 ואילך]."],["e34","*","<b>וכנודע דבחינת:</b> ראה אגה\"ק ס\"כ [קלא, ב]. תו\"א פ' לך ד\"ה והבדילה הפרוכת [יב, ג ואילך]."]]],[2700520492,"ה\"א אש אוכלה הוא שנמשל לאש, אבל להיותו אור המתלבש להחיות נק' אש שחורה, וכידוע שיש שני מיני אור שהם ב' סוגי אש, והם אש שחורה ואש לבנה, דאור כמו שהוא למעלה מגדר אור המאיר לנבראי' נק' אש לבנה, והאור המאיר אל הנבראים הגם שהוא בחי' אור ואש נק' אש שחורה. וכמו בפתילה<sup data-n=\"e35\">*</sup> הנה האור הסמוך להפתילה נק' נהורא אוכמא<sup data-n=\"184\">184</sup>, וטעם הדבר להיותו סמוך אל הפתילה, והגם שהוא שורף ומכלה את הפתילה, אבל להיותו סמוך אל הפתילה, והפתילה היא חושך, הנה הגם שהוא שורפו ומכלה אותו נק' גם האש נהורא אוכמא, ועליו שורה נהורא חיוורא|184 הוא אור הבהיר. וכמו\"כ הוא בהאור וחיות האלקי שבנבראי' הנה מאחר שבא להתלבש בהם ה\"ה ג\"כ נק' בשם חושך, כדוגמת האור הסמוך אל הפתילה שנק' נהורא אוכמא. ויובן זה בקירוב יותר איך שהוא בעבודה בנפש האדם, דהנה כתי'<sup data-n=\"185\">185</sup> והנה סולם מוצב ארצה וראשו מגיע השמימה, דקאי<sup data-n=\"e36\">*</sup> על העבודה שבלב זו תפלה|13, שהיא סולם ההתקשרות דבה ועל ידה הנה הנשמה היורדת למטה להתלבש בגוף להחיותו מתקשרת באוא\"ס ב\"ה, וכנ\"ל דע\"י ירידתה למטה ה\"ה נעשית כערך חושי שכל הטבעי, וע\"י התפלה הנה גם בהיותה בהתלבשותה הרי מתגלים בה הכחות העצמיים שלה בגילוי, ובה וע\"י היינו ע\"י התפלה מקשרים את כל עניני עולם התחתון באלקות, וכנ\"ל<sup data-n=\"186\">186</sup> בענין היחודים שנעשים ע\"י העבודה דתפלה, וכדאי' באוה\"ח<sup data-n=\"187\">187</sup> דכל מגמתינו הוא לכלול נפשותינו בהיחוד הזה, דעי\"ז גם התחתונים נקשרים בהרוחניות, וזהו דתפלה הו\"ע ההתחברות וההתקשרות, דכל המיני התקשרות הן התקשרות הנשמה והן ההתקשרות של עניני העולם הנה הכל כאשר לכל הרי התקשרותם הוא ע\"י הסולם דתפלה, ואופן עמידת הסולם הזה הוא שמוצב ארצה וראשו מגיע השמימה, דארצה ושמימה הם ב' קצוות הפכים, עומק תחת ועומק רום, דארצה הוא עומק תחת ר\"ל בתכלית השפלות, ושמימה הוא עומק רום בתכלית המעלה והעילוי, וסולם זה דתפלה עמידתו באופן כזה דגם ר\"ל מי שהוא ארצה בתכלית הגריעות והשפלות, ומקושר או גם ח\"ו משועבד לענינים לא טובים או גם רעים ביותר, שהוא עצמו יודע שהוא רע, ומ\"מ אינו יכול ר\"ל לצאת מזה, וכמו בחטא הידוע דלבד זאת שמאבד ר\"ל נפשו ומשחית כחותיו<sup data-n=\"188\">188</sup>, ה\"ה נעשה",[["184","184","ראה זהר ח\"א נא, א."],["185","185","ויצא כח, יב."],["186","186","פרק י (לעיל ע' כב)."],["187","187","באור החמה. הובא לעיל שם."],["188","188","ראה רמב\"ם הל' דעות פ\"ד הי\"ט."],["e35","*","<b>וכמו בפתילה:</b> נתבאר בארוכה בתו\"א פ' מקץ ד\"ה ת\"ר מצות נ\"ח [לג, סע\"ב ואילך] וד\"ה כי אתה נרי [מ, ב ואילך] במקומות המתאימים בדרושי חנוכה שבסידור ובשערי אורה. ובכ\"מ."],["e36","*","<b>סולם .. דקאי:</b> זח\"א רס\"ו, ב. ח\"ג שו, ב. ת\"ז תי' מה. ועייג\"כ ד\"ה ויחלום תש\"ח (קונטרס נב [ספר המאמרים תש\"ח ע' 80 ואילך]). שיחת י\"ב תמוז תש\"ז (ליקוט כז [לקוטי דיבורים ח\"ג תצז, ב ואילך. ספר השיחות תש\"ז ע' 143 ואילך]). ובמקומות המסומנים שם."]]],[2700520529,"ר\"ל חולה ומוכה ביסורין, והוא יודע מזה, ומ\"מ אינו יכול לצאת מזה, והוא לפי שהוא קשור ומשועבד ר\"ל לרע, וע\"י הסולם דתפלה שהו\"ע התחנונים ובקשת רחמי' על נפשו, הרי יכול לצאת משפלותו, ולעלות מדרגא לדרגא עד עלותו למדריגה גבוה ונעלה בחי' שמימה, שהם בחי' מקיפים שבנפש שיאירו בפנימיות. אמנם סדר העלי' הוא בהשליבות של הסולם דתפלה, והיינו<sup data-n=\"189\">189</sup> דאופן העלי' הוא כאשר עולה בסדר דרגא אחר דרגא דוקא, וכמו בגשמיות הרי הסולם יש בו שליבות והעלי' הוא בסדר והדרגה דוקא, הנה כמו\"כ הוא בהעבודה דתפלה שהוא ההתקשרות באלקות, וכל התקשרות הוא ע\"י הדעת וההתבוננות המביא את הדעת וכמ\"ש<sup data-n=\"190\">190</sup> דע את אלקי אביך ועבדהו בלבב שלם, דעבודה שבלב שהו\"ע התפלה הוא ע\"י הדעת וההתבוננות<sup data-n=\"e37\">*</sup> באלקות, והוא ההתבוננות בגדולת ד' כל חד וחד לפי כחו להלהיב נפשו ולבו לעבודת ד', והתבוננות זאת היא בפסוד\"ז בהתהוות כל הנבראים מאין ליש, ואיך שכולם בטלים להאור והחיות האלקי, שזהו\"ע אמירת השירה שלהם, וכמו הללו את ה' מן השמים<sup data-n=\"191\">191</sup>, דמהשמים וצבא השמים אנו יודעים את בחי' אוא\"ס הבלתי בע\"ג שלמעלה מהעולמות, דצבא השמים חלוקים מצבא הארץ בזה דצבא הארץ קיימים במין, אבל לא באיש, שהאישים בכל מין הוים ונפסדים, וצבא השמים קיימין גם באיש, דצבא השמים הם ג\"כ נבראים מוגבלים ומורכבים מגוף ונפש, ומצד עצמם הרי הם אפשרי ההפסד, ורק ברצון הבורא ית' הם קיימין באיש, והם חזקים כיום הבראם<sup data-n=\"192\">192</sup>, אשר מזה גופא מובן אשר כח בלתי בע\"ג מחי' אותם, כי מצד החיות עצמו שמלובש בהם כיון שהוא מוגבל ומצומצם לפ\"ע הגוף, שבגוף מוגבל הרי א\"א<sup data-n=\"e38\">*</sup> שיהי' החיות שבו בלתי מוגבל, כ\"א בהכרח שהחיות מוגבל, וחיות מוגבל הרי בהכרח שיחלש פעולתו, או ישתנה, וכמו בגוף האדם שבמשך הזמן נחלש, ובצבא השמים שאינו כן, הנה מזה מובן דאור וחיות בלתי בע\"ג מחי' אותם מאין ליש. וזהו השמים מספרים כבוד אל<sup data-n=\"193\">193</sup>, ופי' בת\"י דמסתכלין בשמיא משתעין יקרא דה', ופי' מסתכלין בשמיא הו\"ע ההתבוננות בצבא השמים, משתעין יקרא דה' שהוא בחי' כבוד אל, דכבוד הוא מקיף<sup data-n=\"e39\">*</sup>, שהוא בחי' סוכ\"ע, השמים מספרים כבוד אל, דמההתבוננות בצבא מעלה, הנה מזה אנו יודעים כבוד אל שהוא אור הסוכ\"ע. וזהו",[["189","189","בספר המאמרים ה'שי\"ת שבהערה :1 דהיינו."],["190","190","דברי הימים-א כח, ט (ושם: בלב)."],["191","191","תהלים קמח, א."],["192","192","ראה ירושלמי ברכות פ\"א ה\"א. ספר החקירה להצ\"צ ד, א. סב, א. קג, א ואילך. המשך מים רבים תרל\"ו פל\"ג."],["193","193","תהלים יט, ב."],["e37","*","<b>ע\"י הדעת וההתבוננות:</b> ראה בארוכה בקונטרס התפלה ובקונטרס העבודה."],["e38","*","<b>שבגוף מוגבל הרי א\"א:</b> ספר האמונות ודעות מ\"א פ\"א. מו\"נ ח\"ב הקדמה יב. הובא ונתבאר בספר החקירה (דרך אמונה) להצ\"צ בתחילתו [א, א]."],["e39","*","<b>דכבוד הוא מקיף:</b> ראה לקו\"ת פ' אמור ביאור דונקדשתי פ\"ד [לד, ד]. שם ר\"פ ויקרא [א, א]."]]],[2700520557,"הללו את הוי' מן השמים הללוהו במרומים, דמן צבא השמים וסיבובם שהו\"ע השירה שלהם, דאז הוא חיותם<sup data-n=\"e40\">*</sup> ואז הם פועלים פעולתם בסיבובם, וכמ\"ש (יהושע י' י\"ב) שמש בגבעון דום, דום מלאמר שירה<sup data-n=\"194\">194</sup>, וע\"י השירה הוא הביטול שלהם, ואז הם פועלים פעולתם בההשפעה כפי גזירת ההשגחה העליונה<sup data-n=\"195\">195</sup>, הנה מזה אנו יודעים בחי' אוא\"ס הסוכ\"ע, והללו את ד' מן הארץ הוא האור דממכ\"ע בכל נברא לפי מהותו וענינו.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דאור האלקי המתלבש בנבראי' נק' אור הנבראי' ונק' חשך ולהיותו אור נקרא אש, והאור שלמעלה מהתלבשות נק' אש לבנה, ואור המתלבש אש שחורה, תפלה סולם, דגם מי שהוא מקושר ארצה בדברים שפלים יכול לצאת, והעלי' בסדר והדרגה, ההתבוננות דפסוד\"ז, מצבא השמים יודעים אוא\"ס הבל\"ג<sup data-n=\"196\">196</sup>.</span>\n<b>ענינים.</b> יג. חיות הנבראים אש שחורה. יד תפלה סולם. טו התחלת ההתבוננו' מגשמיות. טז. מצבא השמים יודעים אוא\"ס הבל\"ג.\nיט) <b>אמנם</b> הנה סדר ההתבוננות בהעבודה דתפלה, הנה תחלה צריכים להתבונן בדברים תחתונים כדומם וצומח הגשמיים, דבכל נברא ויצור פרטי הרי יש בו כח אלקי המהווה ומגדל אותו תמיד מאין ליש, וכמא'<sup data-n=\"197\">197</sup> אין לך עשב מלמטה שאין לו מזל מלמעלה המכה בו ואומר לו גדל, שעי\"ז הוא הצמיחה של העשב מקטנות לגדלות, ובלעדי זאת הרי לא הי' בו בהעשב שום צמיחה וגידול כלל, וכן הוא בכל הנבראים הגשמיים שהשפעת החיות שלהם הוא ע\"י המזלות העליונים, וכמ\"ש<sup data-n=\"198\">198</sup> אני אענה את השמים והם יענו את הארץ, שהמזלות משפיעים<sup data-n=\"199\">199</sup> בכח האלקי שבהם בכל צבא הארץ בדצח\"מ ובהד' יסודות ארמ\"ע, ולכן הרי הגשמי הנה באמת הוא טפל ובטל אל הרוחני, וכמו הגוף שטפל ובטל אל הנפש לפי שהנפש",[["194","194","פרש\"י עה\"פ."],["195","195","ראה סידור עם דא\"ח שער המילה קמב, א ואילך. ועם הוספות כו' מאדמו\"ר הצ\"צ: סהמ\"צ שלו מצות מילה (ה, א ואילך). אוה\"ת: במדבר (שבועות) ע' קט ואילך; נ\"ך ח\"ב ע' תשלח ואילך; סידור ס\"ע שיב ואילך."],["196","196","הקיצור דשנת ה'שי\"ת: אור המתלבש או השייך אל הנבראים נק' אש שחורה. יודיע דתפלה הוא סולם המקשר, ובא על ידי התבוננות. יבאר דמההתבוננות בצבא השמים יודעים סוכ\"ע."],["197","197","ראה ב\"ר פ\"י, ו. זהר ח\"א רנא, א (בהשמטות). ח\"ב קעא, ב. מו\"נ ח\"ב פ\"י. תניא אגה\"ת פ\"ו (צו, א). אגה\"ק סוס\"כ (קלב, א). מאמרי אדמו\"ר הזקן על מארז\"ל ע' קלה ואילך. מאמרי אדמו\"ר האמצעי דברים ח\"ג ע' תתעו ואילך. ספר המאמרים תרפ\"ט ע' 153."],["198","198","הושע ב, כג (ושם: אענה נאם ה' אענה את השמים והם יענו את הארץ)."],["199","199","\"יענו\" לשון השפעה - ראה סידור עם דא\"ח שג, א. תורת חיים בראשית כא, ג. שער האמונה לד, ב. שערי תשובה ח\"א כ, א. ועוד."],["e40","*","<b> הוא חיותם:</b> ראה בכ\"ז תורת חיים [בראשית] רד\"ה ותלד עדה [לג, ד ואילך]. שער האמונה פל\"ז [סב, א]."]]],[2700520574,"הוא החיות המחי' אותו, ובלעדי הנפש הרי אין בו חיות כלל, ולזאת הנה הגוף בטל אל הנפש ונגרר אחריו ומתנהג בכל עניניו רק עפ\"י רצון הנפש, ודבר זה הרי האדם עצמו יודע זאת ומרגיש בעצמו שאין הגוף מנהיג אותו כ\"א הנפש, והגוף נגרר אחר הנפש, וכמו שאנו רואין במוחש שלפעמים הרי האדם עושה כמה ענינים בעניני חיי בשר, ואפילו בעסק מו\"מ, שאינו לפי הבנתו ולא לפי טובתו הגופנית, אלא שהוא מפני המשכת לבו לזה בלא טעם ושכל, דהמשכה זו היא המשכה מרוחניות הנפש<sup data-n=\"e41\">*</sup>, שבא בהמשכת לבו להדבר, והגוף נגרר אחר הנפש לפי שבטל אל הנפש, וע\"י ביטול הגוף אל הנפש הנה עי\"ז הוא חי מהנפש, דזהו דכללות<sup data-n=\"200\">200</sup> הענין דגוף ונפש, דחיות הגוף הוא ע\"י ביטולו אל הנפש דוקא, וכן הוא גם בפרטי אברי הגוף וגשמיותן, דזה מה שהאבר הוא כלי אל אור וחיות הנפש, הוא דוקא כשהוא בטל אל הנפש, ולכן הנה אם ח\"ו יש איזה קלקול באברי הגוף דאז אינו כלי אל אור הנפש, הרי אז הנה האבר ההוא אינו מקבל חיות מהנפש עד שיתרפא ויתתקן האבר להיות כלי לאור וחיות הנפש, וענין רפואתו ותיקונו הוא מה שנעשה בטל ונגרר אחר חיות הנפש, וטעם הדבר הוא לפי דכל קבלת חיותו של הגוף מן הנפש הוא ע\"י ביטול הגוף אל הנפש, וכן הוא בכל הנבראים והיצורים שהן בטלים באמת לגבי הכח הרוחני השופע חיות בהם, כי כל חיות הוא ע\"י הביטול דוקא, שע\"י שהוא בטל לאלקות הנה עי\"ז דוקא הוא כלי שיחי' מהאור והחיות אלקי וכמ\"ש<sup data-n=\"201\">201</sup> יראת ד' לחיים, ולכן<sup data-n=\"202\">202</sup> מלאכים העליונים חיים יותר מפני הביטול שבהם<sup data-n=\"203\">203</sup>, דבאמת הוא כן גם בנבראים התחתונים דכולם בטלים לאלקות, ועי\"ז הם חיים מהאור וחיות אלקי הנמשך להם ע\"י המזלות ברצון הבורא ית', רק שבנבראי' התחתונים אינו נראה בהם הביטול האמיתי מפני הגשמיו' והחומריות שלהם, והיינו דבסיבת חומריות גשמיותם אינו נראה בהם הביטול האמיתי כמו שהוא, אלא שבא בביטול טבעי כמו זה מה שהגוף נגרר אחר הנפש כנ\"ל, וסיבת הדבר מה שהביטול האמיתי אינו נראה הוא בסיבת ירידת העולם ע\"י חטא עה\"ד, דהרי קודם החטא הרי גם בנבראי' התחתונים הגשמיים<sup data-n=\"e42\">*</sup> הי' נראה בהם הביטול האמיתי באמת, וע\"י חטא עה\"ד ירד העולם ונתגשם<sup data-n=\"204\">204</sup> ואינו נראה",[["200","200","בספר המאמרים ה'שי\"ת שבהערה :1 כללות."],["201","201","משלי יט, כג. וראה עבודת הקודש ח\"א (חלק היחוד) ספכ\"ו. לקו\"ת שלח מה, ג. אוה\"ת בראשית ח\"ה תתקמו, א. ספר המאמרים תרס\"ה ע' נה. ועוד."],["202","202","ראה בשם הרב המגיד ממעזריטש: סידור עם דא\"ח פב, ג. סהמ\"צ להצ\"צ טז, ב. וראה גם מאמרי אדמו\"ר האמצעי קונטרסים ע' שטו. ספר המאמרים עטר\"ת ע' רסט. תרפ\"ז ע' קיט. ועוד."],["203","203","בספר המאמרים ה'שי\"ת שבהערה :1 שלהם."],["204","204","ל\"ת להאריז\"ל פ' בראשית (ד\"ה ונבאר). שער מאמרי רשב\"י לזח\"ג פג, א. לקו\"ת מסעי פט, ג. ובכ\"מ."],["e41","*","<b>מרוחני' הנפש:</b> ראה ד\"ה ויחלום תש\"ח (קונטרס נב) פ\"ט ואילך [ספר המאמרים תש\"ח ע' 87 ואילך]."],["e42","*","<b>בנבראים התחתונים הגשמי':</b> להעיר מפרד\"א פי\"א: כסבורין (הבריות) שהוא בוראן ובאו כולם להשתחוות לו. ובת\"ז תי' נו: כגוונא דאדם דלעילא דהוה סגדין לי' הכי הוו סגדין לאדם דלתתא. ועייג\"כ זח\"א רכא, ב. זח\"ב נה, א. זח\"ג קז, ב."]]],[2700520587,"הביטול האמיתי כמו שהוא לאמיתתו, אבל באמת הרי כל נברא גשמי בטל הוא אל הכח האלקי השופע בו, ועד\"ז הוא ביטול המזלות הרוחנים לגבי העליונים מהם, וכמ\"ש<sup data-n=\"205\">205</sup> וגבוה מעל גבוה שומר וכו', שהמזלות מקבלי' שפעם משמרי האופנים, והאופנים מקבלים שפע חיותם מהחיות, וכנ\"ל<sup data-n=\"206\">206</sup> דרוח החי' באופני', דבאופנים וחיות הרי ביטול האופנים אל החיות כמו<sup data-n=\"207\">207</sup> ביטול כל עלול אל העילה שלו, וגבוה מעל גבוה עד מקור הראשון שמהוה עולם היותר עליון דבי\"ע שהמהווה הוא דבר ד' ורוח פיו ית' דבחי' מל' דאצי' שהיא עיקרא ושרשא דכולהו עלמין, דהארת בחי' המל' ה\"ה מתפשט<sup data-n=\"208\">208</sup> בכל העולמות עד גם בעולם התחתון שהשפעת החיות הוא מהמזלות, הרי עיקר החיות ויסודו הוא בחי' הארת המל' שמתלבש בהם ונשפע על ידן. וזהו דכתיב|121 אתה עשית את השמים וגו', שהוא עולם הבריאה, הארץ וכל אשר עלי' עולם העשי', הימים וכל אשר בהם עולם היצי', ואח\"כ אומר ואתה מחי' את כולם וגו' דהן אותיות הדיבור עליון<sup data-n=\"209\">209</sup> דבחי' מלכות דאצי', שזהו ואתה האותיות מא' ועד תי\"ו<sup data-n=\"210\">210</sup>, והוא\"ו הוא האור פנימי היינו רצון העליון בציור הנבראי' כמו שהוא בח\"ע, ובא ונמשך לבחי' אתה, שהוא בחי' דיבור העליון להיות מחי' את כולם, דאור וחיות זה נמשך בכל העולמות, וכולם בטלים באמת אל הדבר ד' המחי' אותם, רק שבזה יש הפרש בין נבראי' העליונים הרוחנים להנבראים התחתונים הגשמיי', דבנבראים העליונים נראה ונגלה הביטול שלהם, ובנבראים התחתונים אין זה נראה ונגלה, אבל באמת הנה גם הם בטלים בתכלית אל החיות האלקי, דבאמת הנה לבד זאת דכל הנבראים בטלים בעצם מציאותם, שהרי כל מציאותם של הנבראים הוא רק מהכח האלקי המהווה אותם וממילא הרי אינן מציאו' לעצמן כלל, לבד זאת הרי גם כמו שהם במציאות הנראה<sup data-n=\"211\">211</sup> ה\"ה בטלים בתכלית אל החיות האלקי המתלבש בתוכן ומחי' אותם.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דסדר ההתבוננות צ\"ל תחלה בדברים התחתונים, הגוף נגרר אחר הנפש, המשכת הלב בלי טעם, ואם אינו בטל הוא חולי, הנבראים העליונים והתחתונים קבלת חיותם ושפעם הוא ע\"י ביטול וההפרש העליונים מרגישים ונראה הביטול, והתחתונים הגשמיות מכסה הביטול.</span>\n<b>ענינים.</b> יז התחלת ההתבוננות מדצ\"ח. יח. נבראים, א) עליונים ביטולם נראה, ב) תחתוני' ביטולם בהעלם.",[["205","205","קהלת ה, ז (בשינוי לשון)."],["206","206","סעיף יא (לעיל ע' כד)."],["207","207","כ\"ה בכתי\"ק, בהעתקה ובספר המאמרים ה'שי\"ת שבהערה 1. ואוצ\"ל: הוא כמו."],["208","208","כ\"ה בכתי\"ק ובהעתקה. שם: מתפשטת."],["209","209","כ\"ה בכתי\"ק, בהעתקה, בספר המאמרים ה'שי\"ת שם. ובספר המאמרים עת\"ר שבהערה :1 דיבור העליון."],["210","210","ראה זהר ח\"א טו, ב. ח\"ב רסא, א. תניא שעהיוה\"א פ\"ב."],["211","211","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שבהערה :1 הנברא."]]],[2700520600,"<b>וזהו</b> כל המעביר על מדותיו מעבירים לו על כל פשעיו, דמעביר על מדותיו הוא בא ע\"י העבודה בהתגלות הלב דוקא שנוגע<sup data-n=\"212\">212</sup> בעבודה בפועל, והגם דהעבודה דפנימית הלב הרי יש בזה מעלה עליונה יותר, אמנם זהו המעלה במעלת ההשגה, אבל להיות עבודה בפועל הוא ע\"י התגלות הלב דוקא, ולכן מעבירים לו על כל פשעיו, אבל בתנאי למי שמשים עצמו כשיריים, והיינו שיהי' נרגש אצלו בו בעצמו שהוא רק שיריים בלבד, והעיקר הוא האור וחיות אלקי, ואז מעבירין לו על כל פשעיו, וגם אם ח\"ו נקנסה עליו איזה ענין לא טוב ר\"ל, הנה מאחר שמעביר על מדותיו ונרגש אצלו כי כל הענינים הם רק שיריים, והגם שעדיין לא בא לידי מדריגה זו לפנימיותה ועצמותה, אבל כאשר הנהגתו בכל עניניו הוא באופן כזה להיות מעביר על מדותיו, אז הנה מעבירין לו על כל פשעיו וזוכה לחיים<sup data-n=\"213\">213</sup>.\n<b>סיום.</b> מעלת עבודת המוח בהשגה, ועבודת הלב בפועל, מעביר על מדותיו בפועל זוכה לחיים.\n-------------------- * --------------------",[["212","212","כ\"ה בכתי\"ק ובהעתקה. שם: שנוגע לו."],["213","213","הקיצור דשנת ה'שי\"ת: יבאר ההתבוננות בצבא הארץ שהעיקר הוא החיות והנפש, והגוף טפל ובטל אליהם ועי\"ז חי. וכן הוא בכל הנבראים לגבי חיות האלקי. למטה אינו ניכר הביטול האמיתי מפני גשמיותם."]]],[2700520057,"<b>אתה</b><sup data-n=\"214\">214</sup> הבדלת אנוש מראש ותכירהו לעמוד לפניך<sup data-n=\"215\">215</sup>, והנה בקריאת שם מין המדבר הרי יש ד' שמות, אדם איש גבר אנוש<sup data-n=\"216\">216</sup>, דכל אחד מהשמות הללו הם תואר מיוחד במעלת ומדריגת מין המדבר, דתואר אדם הוא מורה על המעלה היותר עליונה שהוא מעלת ההשכלה וההשגה, תואר איש הוא כינוי למדות וכמ\"ש<sup data-n=\"217\">217</sup> כאיש גבורתו, והגם שאינו אותה המעלה דמדריגת אדם שהוא בעיקרו שכלי, ומדות ישנם בבע\"ח ג\"כ, דזהו ההפרש כללי בין אדם ובהמה, דבהמה הם מדות ואדם שכל, ומ\"מ הלא גם איש שהו\"ע המדות הרי גם בהם יש איזה מעלה להיותם מדות בני אדם שהם מדות שבאים עפ\"י השכל<sup data-n=\"218\">218</sup>, וגבר ואנוש הרי אינם כלל במעלת אדם",[["214","214","בגוכתי\"ק כ\"ק אדמו\"ר מוהריי\"צ ב\"עניני מאמרי רצ\"ב\", נרשם: \"אתה הבלדת אנוש מראש, ובו ג' פרקים. ז ענינים\". - נעתקו לקמן במקומם."],["215","215","תפילת נעילה דיוהכ\"פ."],["216","216","ראה זח\"ג מח, א. לקו\"ת שה\"ש כה, א-ב. אוה\"ת ויקרא ח\"ד ע' א'מח ואילך. ספר המאמרים תרכ\"ט ע' קעא ואילך. עטר\"ת ע' שלג ואילך."],["217","217","ספר שופטים ח, כא."],["218","218","ראה גם ספר המאמרים ה'ש\"ת ע' 96."]]],[2700520107,"ואיש, ויש מעלה בגבר על אנוש, דאנוש מורה על החלישות, וכמ\"ש<sup data-n=\"219\">219</sup> עקוב הלב מכל ואנוש הוא, דאנוש פירושו חלוש, והוא היותר נמוך מכולם, ואדם הוא למעלה מכולם, וכתיב<sup data-n=\"220\">220</sup> אדם אתם ואמרז\"ל (יבמות דס\"א ע\"א) אתם קרוים אדם. ולכאו' א\"מ דלאחר העבודה דיוהכ\"פ הנה בתפלת נעילה כשבא להזכיר במעלת ישראל למה מכנה אותם בשם אנוש, ומהו\"ע ותכירהו לעמוד לפניך.\n<b>התחלה.</b> אדם שכל, איש מדות, גבר תוקף, אנוש חלוש, ויקשה מהו המעלה באנוש שמזכירהו בנעילה לשבח.\n<b>ולהבין</b> כ\"ז ילהק\"ת משנת\"ל דאור וחיות הנבראי' כמו שבא להתלבש בהנבראי' ה\"ה מתגשם לפי ערכם ומהותם של הנבראים, וכן הוא גם בנבראי' העליונים, דאינו דומה חיות הנברא בהתלבשותו לכמו שהוא כלול במקורו שהוא נעלה ומשובח באין ערוך, ומזה הוא התפעלו' המלאכים, והגם דחיות כל הנבראי' בהיותם כלולים במקורם הרי גם שם הם חלוקים זה מזה, ומ\"מ הנה עמידתם שם הוא באופן משובח באין ערוך, וע\"ד הגדרת זמן ומקום רוחני להגדרת זמן ומקום גשמי, וכן אופן הביטול מורה על גודל מעלתם בהיותם כלולים, ויבאר בענין לבושי מח' ודיבור, דמעשה שבדיבור שהוא גילוי ממש אל הזולת הן הנה האותיות דמח' שבמח', ומ\"מ הם באין ערוך כלל לכמו שבא בגילוי ממש, וכן הוא בחיות הנבראי', דהגם שהם כבר חיות מוגבל להחיות, הנה בהיותם עודם כלולי' במקורם, ה\"ה במעלה משובח באין ערוך, וכאשר אור וחיות זה בא להתלבש בהנבראי' נתגשם כערך<sup data-n=\"221\">221</sup> הנברא להיותו כח הפועל בנפעל, והכח עצמו נקרא פעולה, ויבאר ההפרש בין כח ופועל דכחות הנפש שהוא רק התקשרות הפועל בנפעל שאינו לצורך קיומו של הנפעל, ואמיתת כח הפועל בהנפעל נמצא בו תמיד לצורך קיומו של הנפעל, ולכן האור והחיות עצמו נקרא ג\"כ חושך שהוא נהורא אוכמא. ויבאר ענינו בעבודה דכל ההתקשרות הוא ע\"י התפלה בעבודת ההתבוננות, הללו את ה' מן השמים, דמצבא השמים אנו יודעי' אוא\"ס הסוכ\"ע, השמים מספרים כבוד אל, והעלי' בסולם ההתקשרות הוא בסדר, דתחלה צ\"ל ההתבוננות בדברים התחתונים דדומם וצומח, שהעיקר הוא החיות והגוף נגרר, וע\"י ביטולו של הגוף והאברי' מקבל חיותו מהנפש, ובקלקול ח\"ו אינו מקבל, וכן ע\"י הביטול לאלקות הוא כלי לקבל חיות מאלקות, יראת ה' לחיים, ובאמת כל הנבראים בטלים רק שמפני גשמיותם אינו ניכר בהם הביטול האמיתי, והוא מפני ירידת העולם בחטא עה\"ד, וכן המזלות הרוחני' בטלים לגבי למעלה עד שרשם הראשון בחי' מל' דאצי'. וזהו אתה עשית את השמים בריאה, הארץ וכל אשר עלי' עשי', הימים וכל אשר בהם יצי', ואח\"כ אומר ואת\"ה, וא\"ו ההמשכה מא' עד תי\"ו להחיות את כולם, ולכן הנה כל הנבראים טפלים ובטלים ונגררים אחר החיות האלקי המתלבש בתוכן ומחי' אותם.",[["219","219","ירמי' יז, ט."],["220","220","יחזקאל לד, לא."],["221","221","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שבהערה :1 בערך."]]],[2700520157,"כ) <b>והנה</b> כאשר יתבונן בכל זה, בהתבוננות פרטית, עד אשר יוקלט במוחו היטיב, והיינו לבד זאת דהתבוננות אמיתי הוא דוקא כשבא בפרטיות<sup data-n=\"e43\">*</sup>, דהרי גם בלימוד הרי הידיעה האמיתית הוא דוקא כאשר יודע פרטי הענינים היטיב, ומכש\"כ בהתבוננות שהיא צריכה להיות בפרטיות דוקא, הנה לבד כל זאת הנה בכדי שיוקלט במוחו היטיב הוא כאשר ההתבוננות היא בפרטיות דוקא, ולזאת כאשר יתבונן בכל הנ\"ל באופן שיוקלט במוחו היטיב, איך שהעיקר הוא האור והחיות האלקי שהוא מקורא ושרשא דכולהו, וכל העולמות והנבראי' העליונים והתחתונים טפילין ובטילין לגמרי לגבי מקורם הראשון, אז הנה ודאי כי יתפעל במוחו ולבו להיות לו רצון וחשק לדבקה בו ית', שהוא העיקר ושרש ומקור הכל, והיינו דהוא ית' הוא מקור כל החיים העליונים ותחתונים, ולא יחפוץ להתקשר בהטפל, אלא דכל חפצו ורצונו יהי' להתקשר לעיקר ומקור הכל, והיינו דהגם שהמזלות הרוחנים הם שלוחי השפע בהכח האלקי, ונקראים משפיעים בעניני הגשמיות, דבכדי שההשפעות הגשמים יהיו בערך הנבראים ובהטוב להם הוא ע\"י המזלות הרוחנים, ומהם להמזלות הגשמיים, וכמ\"ש<sup data-n=\"222\">222</sup> ממגד תבואת שמש וממגד גרש ירחים, ולמעלה מהם הם האופנים שהם למעלה יותר ורוחנים יותר מכמו המזלות הרוחנים, וגבוה עליהם הם חיות הקודש, שהם רוח החי' באופנים, והם הממשיכים ומשפיעים שפע חיותם של האופנים כנ\"ל, הנה בכל זה הרי לא יחפוץ להתקשר בכל אלו להיותם רק נבראים מחודשים מאין ליש, וה\"ה טפילין ובטילין בתכלית, וכ\"ש שלא יהי' חפצו ורצונו בהדברים הגשמים הנשפעים מהמזלו' הרוחני' ולא יחשבם לעיקר כלל, כ\"א כל חפצו ורצונו יהי' בבחי' האור והחיות האלקי, וכן בהדברים הגשמים גופא יהי' תכלית רצונו בחי' האלקות שבהם, והוא שלא ירצה להתענג בהם בתענוג גשמי, כ\"א לשם שמים, דהיינו בשביל עבודת ד' בתורה ותפלה, ושהאור האלקי שבהם יאיר בנפשו בתוס' אור וחיות, ובד\"כ ירצה שיהי' גילוי אלקות בעולם, והיינו ע\"י שיתבונן בהתבוננות הנ\"ל איך שהעיקר הוא האלקות וכל הנבראי' העליונים ותחתונים בטלים וטפילים לגמרי להאור וחיות אלקי, הנה עי\"ז נעשה אצלו ג\"כ עניני האלקות לדבר עיקרי, ועניני הגשמים שלו נעשים אצלו טפלים, כי ההנחה וההחלטה הזאת שהונח והוחלט אצלו שהאלקות הוא העיקר, והגשמי הוא הטפל לגמרי<sup data-n=\"223\">223</sup> אל האלקות, הרי זה פועל בנפשו שיהיו אצלו עניני גופו כענינים טפלים והאלקות יהי' אצלו ענין עיקרי, ועוד זאת ירצה שיהי' הגילוי של האור והחיות האלקי, והיינו שהאלקות יאיר בגילוי בעולם, שיהי' נראה ונגלה האור האלקי, ולכן הנה גם בעניניו הגשמים אינו רוצה בהגשמי עצמו להתענג בו, כ\"א לקבל חיות מהאור אלקי",[["222","222","ברכה לג, יד (ושם: וממגד. וכ\"ה בספר המאמרים ה'שי\"ת שם). וראה מקומות שצויינו בהערה 195."],["223","223","בספר המאמרים ה'שי\"ת שבהערה 1 ליתא תיבה זו."],["e43","*","<b>כשבא בפרטיות:</b> ראה שער היחוד - לאדמו\"ר האמצעי - בתחילתו. קונטרס התפלה בתחילתו."]]],[2700520207,"שבהגשמי, דמשו\"ז לא ירצה אלא רק מה שהוא מוכרח אליו ולא במה שהוא מותרות, וגם במה שמוכרח הנה תכלית חפצו ורצונו הוא לקבל חיותו מהאור וחיות אלקי שבהם, והיינו לעשותם כלים לאלקות, ומואס בהחומריות שבהגשמיות גופא, דהנה כתיב<sup data-n=\"224\">224</sup> ראה נתתי לפניך היום את החיים ואת הטוב ואת המות ואת הרע, ומסיים<sup data-n=\"225\">225</sup> ובחרת בחיים למען תחי' אתה וזרעך, ופי' חיים ומות<sup data-n=\"226\">226</sup> הרי אין הכוונה דחיי' הוא בעת שהנברא חי, ומות הוא לאחר פירוד וסילוק חיותו של הנברא, דע\"ז הלא<sup data-n=\"227\">227</sup> אין צריכים אזהרה, וגם אפילו התעוררות עצה טובה דובחרת בחיים, דמי הוא זה אשר לא יבחר בחיים, ומי הוא הפתי אשר יבחר בהיפך החיים, אלא דפי' חיים ומות קאי על הנברא החי, דכל נברא ונברא בעת שהוא בחיותו וקיומו הנה אז גופא הרי יש בו בעצמו חיים ומות, וכנ\"ל דכל נברא ונברא כלול מב' ענינים, שהוא גוף הנברא, ואור שפע האלקי השופע בו, שהם גוף ונפש, דהגוף הוא חומר גשמי, והנפש הוא צורה רוחנית, דבכל נברא ונברא הנה גשמיותו שהוא החומריות הוא מות, לפי שהוא כלה ונפסד, וכאשר האדם רואה במוחש בכל נברא<sup data-n=\"228\">228</sup> שהוא נפסד מזמן לזמן, וכן האדם מרגיש בעצמו כליון הכחות הגופנים שלו, דכלים ונפסדים מזמן לזמן, והרוחניות שהוא הכח האלקי השופע בכל נברא ונברא, הוא החיים שאין בזה כליון והפסד ח\"ו, כ\"א הוא בקיום נצחי, דגם זה מרגיש האדם במוחש בעצמו, דכחותיו הרוחנים הרי אדרבא במשך השנים עד ימי הזקנה והשיבה הן מתחזקים יותר, דהחלישות הוא רק מצד הגוף בכחות גשמי', אבל כחותיו הרוחנים ה\"ה מתחזקים ומתיישבים וכמא'<sup data-n=\"e44\">*</sup> סבא דעתי' סתים, דכח שכלו בעצם ה\"ה מתחזק ומתיישב, וכמא'<sup data-n=\"229\">229</sup> זקני ת\"ח כ\"ז שמזקינים דעתם מתיישבת, דמזה הרי נראה במוחש דהאור וחיות אלקי הוא חיות וקיום נצחי, וזהו חיים ומות רוחניות וגשמיות, דהגשמיות מצ\"ע שהו\"ע החומריות הוא מות הוה ונפסד, והרוחניות שהוא אור ושפע האלקי הוא חיים, וזהו לאהבה את ה\"א כי הוא חייך<sup data-n=\"230\">230</sup>, שהוא חיי הנשמות. וע\"י ההתבוננות הנ\"ל דכל המדריגות העליונות עם היות שבהם וע\"י נמשך השפע האלקי בכל הנבראי', אבל כללות כולם ה\"ה נבראי' מחודשים וכולם טפלים ובטלים לאור וחיות האלקי השופע בהם בעצמם, הנה ע\"י התבוננות זו ה\"ה בא לאהבה את ה\"א כי הוא חייך לדבקה באוא\"ס ב\"ה חיי החיים.",[["224","224","נצבים ל, טו."],["225","225","שם, יט."],["226","226","ראה ספר המאמרים תרס\"ט ע' קח ואילך. המשך תער\"ב ח\"א ע' רכג ואילך (ושם: וכמ\"ש באורך בד\"ה תקעו, עת\"ר [ספר המאמרים עת\"ר הנ\"ל הערה 1]). ספר המאמרים תש\"ז ע' 157. לקוטי שיחות חכ\"ה ע' 7. וראה מקומות שצויינו בהערה 240."],["227","227","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שבהערה :1 הרי."],["228","228","כ\"ה בכתי\"ק ובהעתקה. שם: נברא ונברא."],["229","229","קנים בסופה."],["230","230","ס\"פ נצבים."],["e44","*","<b>וכמאמר סבא:</b> זח\"ג קכח, ב."]]],[2700520257,"<span data-k=\"ks\"><b>קיצור.</b> יבאר דהתבוננות צריכה להיות בפרטיות דוקא, ואז נקלט אצלו ומשתוקק בהאור והגילוי, ההנחה שהאלקות עיקר פועל בו דעניניו הגשמיים נעשים טפלים אצלו, ויבאר דראה נתתי לפניך וגו' חיים הצורה וחיות ומות החומר והגוף, גשמיות הוה ונפסד, רוחניות נצחי, כי הוא חייך חיי הנשמות<sup data-n=\"231\">231</sup>.</span>\n<b>ענינים.</b> א התבוננות צ\"ל בפרטיות. ב ההנחה שהאלקות עיקר פועל שהגשמיות נעשה טפל. ג כחות, א) גשמיים נחלשים, ב) רוחנים מתחזקים.\nכא) <b>וזהו</b> ראה נתתי לפניך היום את החיים ואת הטוב את<sup data-n=\"232\">232</sup> המות ואת הרע, ואומר החיים והטוב פירושו הטוב שבחיים, וכמ\"ש<sup data-n=\"233\">233</sup> כי טוב חסדך מחיים, לפי שהוא ית' בחי' חיי החיים. דהנה יש ב' בחי' חיים, חיי הגוף וחיי הנשמה, דחיי הגוף הוא ג\"כ חיים רוחנים אבל הוא החיות דאור הממכ\"ע, וחיי הנשמה הוא האור דסוכ\"ע, והם הב' שמות דהוי' ואלקים, וש' אלקים בגימ' הטבע<sup data-n=\"234\">234</sup>, שזהו האור והחיות דממכ\"ע מה שהטביע הקב\"ה בהנבראי' בכל נברא ונברא לפי מה שהוא, ובהאדם הנה חיות זה הוא האו\"פ מה שבא בהתלבשות ממש בגוף האדם, ואור הסוכ\"ע הוא חיי הנשמות<sup data-n=\"235\">235</sup>, ונק' חיי החיים, בחי' נשמתא לנשמתא, וזהו הטוב שבהחיים, וכאמרז\"ל<sup data-n=\"236\">236</sup> (יומא דע\"א ע\"א) מחייה חיים יתן לך חיים ארוכים וטובים ומתוקנין, והיינו שהרוחניו' נקרא חיים, והוא בחי' ממכ\"ע, דבהאדם הוא מה שאור וחיות הנפש שהם הכחות ואברי הנפש שמתלבשי'<sup data-n=\"237\">237</sup> באברי הגוף להחיותם, ובעולמות הוא מה שאור וחיות אלקי שבא<sup data-n=\"238\">238</sup> בהתלבשות בעולם ונבראי' להחיותם מאין ליש שהוא בחי' אור הממכ\"ע, מה שבא בכל עולם ובכל נברא לפי ערכו וענינו להחיותו בחיות פרטי, ובחי' אור הסוכ\"ע הוא מה שלמעלה מבחי' רוחניות, דלגבי' רוחניות וגשמיות שוין, זהו חיי החיים, והוא בחי' הטוב שבחיים. וכמו\"כ בהיפך כתיב את המות ואת הרע, דהגשמיות וחומריות הנברא הנה בעצם ענינו ה\"ה מות, לפי שהוא כלה ונפסד, וההפסידות בו הוא תמידי, וזהו דהכינוי האמיתי של הנבראי' הוא הוה ונפסד, שבעת שהוא עודנו הוה הנה גם אז הוא נפסד, דצבא השמים עם היות דגם הם נפסדים מצד עצמם כנ\"ל, ומ\"מ הרי רק שהם אפשרי ההפסידו' ועתה",[["231","231","הקיצור דשנת ה'שי\"ת: ימשיך דהתבוננות בפרטיות זו פועל שירצה רק בהאלקות וגילויו שהוא העיקר. יסביר דגשמיות ורוחניות הם מות וחיים."],["232","232","בכתוב: ואת. וכ\"ה בספר המאמרים ה'שי\"ת שם."],["233","233","תהלים סג, ד."],["234","234","פרדס שער יב (שער הנתיבות) פרק ב. ראשית חכמה שער התשובה פרק ו ד\"ה והמרגיל (קכא, ב). של\"ה פט, א (דאיתא בזהר); קפט, א (ומרומז בזהר); שח, ב. שו\"ת חכם צבי סי\"ח (הובא בלקו\"ת פ' ראה כב, ריש ע\"ג). תניא שעהיוה\"א רפ\"ו. לקו\"ת שם כב, סע\"ב ואילך."],["235","235","ראה גם קונטרס העבודה פ\"ד (ע' 34. ומציין שם לד\"ה אחת שאלתי עת\"ר הנ\"ל הערה 1)."],["236","236","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שבהערה :1 וכמארז\"ל."],["237","237","כ\"ה בכתי\"ק ובהעתקה. שם: מתלבשים."],["238","238","כ\"ה בכתי\"ק ובהעתקה. שם: בא."]]],[2700520307,"ברצון הבורא ית' הם חזקים כיום הבראם<sup data-n=\"e45\">*</sup>, וכתיב (ישעי' נ\"א ו') כי שמים כעשן נמלחו וארץ כבגד תבלה וגו', אבל כ\"ז שרצון הבורא ית' בהם שיהיו קיימין באיש אינם נפסדי', משא\"כ בצבא הארץ הרי ההפסידות שלהם הוא תמידי, וכמא' הבחיי<sup data-n=\"239\">239</sup> דהתינוק משעה שנולד מתחיל להתייבש, לפי שהגשם בכלל הוא כלה ונפסד. והרע הוא עוד גרוע הרבה יותר מהמות<sup data-n=\"240\">240</sup>, דכמו שהטוב מעולה מהחיים כנ\"ל, כך הנה להיפך הרי הרע בעיני ד' הוא באמת רע ומר יותר מהמות, שהרי המות הוא רק היפך החיים כמו הגשמיות שהוא היפך הרוחניות, אבל הרע הוא היפך ומנגד לבחי' חיי החיים, שהרי כל דבר איסור הוא היפך רצון העליון שהוא חיי החיים, בחי' סוכ\"ע, וכיון שהרע הוא מנגד ומונע גילוי בחי' חיי החיים, מה שטוב ומעולה לאין קץ מבחי' חיים, דהחיים הוא רק כלי אל חיי החיים, הרי בהכרח שהרע הוא עוד קשה מהמות שהוא רק מנגד והיפך החיים. והנה בעניני העולם הנה מות קאי על הגשמיות של העולם, וכנ\"ל דחוק הגשם הוא להיות כלה ונפסד, שבעת הוייתו הוא הפסידו, וענין הרע שהוא עוד קשה מהמות הוא התאוה מה שרוצה בהדבר למלאות תאוותו, דהתאוה הוא רע וגרוע הרבה יותר מהמות, דהמות הוא רק כליון והפסידות הדבר, אבל תאוה הוא מציאות מנגד, וכמ\"ש<sup data-n=\"241\">241</sup> ולתאוה יבקש נפרד, דגם דבר שהוא טוב מצ\"ע אם עושה זאת למלאות תאוותו ה\"ה עושה אותו לרע כו', וזהו ולתאוה יבקש נפרד שעושה אותו למציאות מנגד לחיי החיים, וכ\"ש תאות איסור ר\"ל שהוא עוד גרוע יותר. וזהו ראה נתתי לפניך היום את החיים, שהכח האלקי המתלבש בהעולם הוא בחי' חי וקיים, וכמ\"ש<sup data-n=\"242\">242</sup> ודבר אלקינו יקום לעולם, דהדבר אלקינו שהוא האור והחיות הנמשך בעולם ונבראים יקום לעולם, שהוא המקיים את העולם, והוא יקום לעולם שהוא בקיום נצחי, ובד\"כ הוא החיים שעפ\"י התורה, ואת הטוב הוא הכח והחיות אלקי שנמשך בנש\"י שנקראים עם קרובו, וכתיב<sup data-n=\"243\">243</sup> וירם קרן לעמו, דע\"י קיום התומ\"צ באים לבחי' אוא\"ס ב\"ה חיי החיים, והיינו דע\"י העבודה בתו\"מ ממשיכי' בהחיים דעולם הגילוי דבחי' חיי החיים. וזהו אמר רבה כי מיפטרי רבנן מהדדי בפומבדיתא, דענין דלימוד התורה הוא בשביל לשמור לעשות ולקיים בקיום",[["239","239","ראה בחיי בראשית א, כח (ספר המאמרים תשי\"א ע' 142). וראה ספר המאמרים תרכ\"ז ע' תעט. תרל\"ג ח\"ב ע' תקמט. המשך מים רבים תרל\"ו פל\"ג. תרס\"ט ע' קיא. תער\"ב ח\"ב ע' א'קמג. תרפ\"ו ע' סא. ועוד."],["240","240","ראה מאמרי אדמו\"ר הזקן תקס\"ב ח\"א ע' צ ואילך - (ועם הוספות וכו' - מאמרי אדמו\"ר האמצעי ואתחנן ע' קסב ואילך. אוה\"ת ואתחנן ס\"ע קמז ואילך. ד\"ה קטנתי תשכ\"ד). המשך תער\"ב וספר המאמרים תש\"ז שבהערה 226."],["241","241","משלי יח, א."],["242","242","ישעי' מ, ח."],["243","243","תהלים קמח, יד."],["e45","*","<b> חזקים כיום הבראם:</b> ראה ירושלמי ברכות פ\"א ה\"א. ונתבאר בארוכה בס' החקירה להצ\"צ בההקדמה (הוא ד\"ה שאו מרום עיניכם. נדפס בהוספות לס' הנ\"ל [קג, א ואילך]) ובח\"א פ\"ג [ד, א]."]]],[2700520357,"המצות מעשיות בפו\"מ, ובמדות טובות בפועל, אמרי הכי מחיי' החיים<sup data-n=\"244\">244</sup> יתן לך חיים ארוכים, דתכלי' הכוונה הוא שיהי' הגילוי דחיי החיים בהחיים דעולם. וזהו את החיים ואת הטוב, דגם חיי העולם יהי' במדריגת טוב שהוא בחי' חיי החיים, אבל גשמיות וחומריות העולם הם מות בעצם דכלה ונפסד, והתאוה גם תאות היתר הוא רע שגרוע יותר כנ\"ל, וכאשר יתבונן בכ\"ז הרי בודאי כי ימאס בדברים החומריים, ולא יחפוץ בכל הענינים<sup data-n=\"245\">245</sup> הגשמיים, ויתעורר באהבה ורצון לד' לבדו, שהוא בחי' החיים והטוב, דאהבה זו עם היותה מדרי' גבוה ונעלית מ\"מ נקראת נהורא אוכמא, וכנ\"ל<sup data-n=\"246\">246</sup> בהנר דהאור שהוא סמוך אל הפתילה, הנה הגם שהוא שורף ומכלה את הפתילה, דשריפת הפתילה ע\"י האור הרי אין זה שמאבד את הפתילה, כ\"א אדרבה שפועל ועושה להפך את הפתילה לאור המאיר, דבאור הנר הנה כשם שאי אפשר בלי שמן כך אי אפשר בלא פתילה, ואמיתת בהירת אור הנר הוא כאשר השמן ופתילה הם במזיגה והרכבה נכונה, ומשניהם כאחד הוא שבא האור בכלל, ובשניהם יחדיו תלוי בהירת האור ופעולתו להאיר, והעושה את הפתילה לאור, הוא האור הסמוך אל הפתילה, ובכ\"ז הנה בהיותו סמוך אל הפתילה, והפתילה עצמה היא חושך, לזאת הנה הגם שהוא שורפו ומכלהו ומהפכו לאור נקרא נהורא אוכמא, הנה כמו\"כ באהבה זו דהגם שהיא מדריגה גבוה, אמנם מאחר שבאה להאיר חשכת הגוף והנה\"ט, ושיפעל גם בהנה\"ב, דהרי עבודה זו אין זה עבודת הנשמה מצ\"ע, דהנשמה היא חלק אלקה ממעל כנ\"ל, והשגתה הוא בהאור וחיות אלקי שלמעלה מההארה האלקית שמתלבשת בעולם ושנעשה מקור להם, א\"כ מובן שהאהבה הנעשה ע\"י ההתבוננות בשרש ומקור העולמות, הרי אין זה עבודת הנשמה מצ\"ע, כ\"א הוא עבודת הנשמה להאיר את העולם, לזכך את הנה\"ט, ולברר את הנה\"ב, ולכן נקרא נהורא אוכמא שהוא אש שחורה.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר כי הטוב שבחיים הוא חיי הנשמה סוכ\"ע, חיי הגוף והעולם ממכ\"ע, גשמיות רע וחומריות מות, מות מנגד לחיי החיים ויבאר כי התאוה בכלל ואיסור בפרט ממית ומפריד מאלקות, לימוד התו' כדי לידע המצות ולקיימן כהלכתן דאז הוא טוב שבחיים, ויסביר דגם שמתבונן ובא לידי אהבה נקראת נהורא אוכמא<sup data-n=\"247\">247</sup>.</span>\n<b>ענינים.</b> ד תאוה מנגד לחיי החיים. ה בתו\"מ מגיעים לטוב שבחיים.\nכב) <b>וביאור</b> הענין הוא דהנה כתיב (ש\"ה ב' ה') סמכוני באשישות רפדוני בתפוחים כי חולת אהבה אני, ואי' במד\"ר (במקומו פ\"ב פיסקא י\"ד) סמכוני באשישות בשתי אשות, באש של מעלה ובאש של מטה, ופי' במ\"כ<sup data-n=\"248\">248</sup> שאע\"פ שהאש",[["244","244","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שבהערה :1 חיים."],["245","245","כ\"ה בכתי\"ק ובהעתקה. שם: ענינים."],["246","246","פרק יח (לעיל ע' מ)."],["247","247","הקיצור דשנת ה'שי\"ת: יבאר דחיי הגוף וממכ\"ע נק' חיים. חיי הנשמה וסוכ\"ע נק' חיי החיים וטוב שבחיים. מות ורע הם הגשמיות והתאוה. ובחרת בחיים ובכל זה נקרא זה אש שחורה."],["248","248","במתנות כהונה."]]],[2700520404,"יורד מן השמים מצוה להביא מן ההדיוט<sup data-n=\"249\">249</sup>, דזהו תכלית ירידת הנשמה למטה, וכנ\"ל בענין אהוי\"ר המגולים בהתגלות הלב, שזהו הכוונה העליונה, לפי שהוא בקירוב אל הנה\"ט דגם הוא יכול להתעורר באהבה לד', ועוד כי האהוי\"ר בהתגלות הלב הנה אח\"כ הרי העבודה היא להיות כל מעשיו לש\"ש, וכ\"ז הוא לפי שתכלית ועיקר ירידת הנשמה למטה הוא בשביל לברר את הנה\"ב. והענין הוא דהנה כתיב<sup data-n=\"250\">250</sup> גם את זה לעומת זה עשה אלקים, דהנה\"א והנה\"ב עם היות שהם חלוקים בעצם מהותם, ולכן זה נקרא אדם, וזה נקרא בהמה, ומ\"מ ה\"ה משתוים בציורם, דכמו שבהנה\"א הרי יש בו חו\"ב שהם השכלות והשגות אלקית, ומדות קדושים שמולידים אהוי\"ר, וגם לבושים קדושים שהם המחדו\"מ שהן האותיות דתורה ותפלה וכוונת הלב בהרהורי תשובה שהן מעשה בפועל, וכמא'<sup data-n=\"251\">251</sup> מחשבה טובה הקב\"ה מצרפה למעשה, ונת\"ל<sup data-n=\"252\">252</sup> דבמח' גופא הרי יש בה מחדו\"מ, דהרהור הוא המעשה שבמח', דזהו כללות הציור דהנה\"א, הנה כמו\"כ הוא בהנה\"ב דיש בו ג\"כ ציור קומה שלם, דמוחין ומדות והלבושי' דמחדו\"מ, והגם דכללות מהותו הוא בהמי, ומ\"מ הרי יש בו שכל ומדות, רק דשכלו ומדותיו רעים, וכן המחדו\"מ שלו הן לא לד' המה, שהן רק רע ולא טוב כלל, וכמו להתחכם לרעה ולהרע, וכמו שאנו רואין במוחש דישנם כאלו ר\"ל, אשר כל מעינם הוא לחשוב מחשבות איך להרע, ויא צוא מאַכין שלעכט און טוט ויי, והגם שהם בעצמם אינם פועלי הרע בפועל, אלא שהם מתחכמי' להמציא כל מיני רע ביסורי הגוף והנפש, וישנם כאלו ר\"ל אשר ענינם להתחכם לעשות רע בפועל, וכמ\"ש<sup data-n=\"253\">253</sup> הבה נתחכמה לו, שזהו ההתחכמות<sup data-n=\"254\">254</sup> דלעו\"ז איך לצוד את הנה\"א ולהביאו לידי רע ח\"ו, וכמ\"ש<sup data-n=\"255\">255</sup> חכמים המה להרע, ובהנה\"ב בד\"פ הוא ההתחכמות|254, איך לבוא לידי איזה דבר תאוה וחמדה, דאין היצה\"ר שולט אלא במה שעיניו רואות<sup data-n=\"256\">256</sup>, וזהו ההתחכמות של היצה\"ר לצייר ציורים רעים כאילו הדבר לנגד עיניו, ולהחטיא את האדם, וכן כל התחכמותו בהשכלותיו והשגותיו הוא להשכיל ולהשיג את הטוב של הדברים הגשמים, ויא גשמיות איז גוט און גישמאַק, ואָס פון דיא השכלות און השגות הרי נולד בלבו המדות רעות להתמשך אחרי תאוות רעות, שהמדות רעות הם מקור למחשבות רעות במחשבות זרות, דפי' מחשבה זרה מה שבאמת ענין זה מצ\"ע הוא זר לו, שאינו לפי ערך מהותו כלל, ורק שהיצה\"ר מביאו למח\"ז והרהורים רעים ובדיבורים של הוללות ופריקות עול, וכן במעשה שנמשך אחרי שרירות לבו, וע\"ז הוא שצריך להיות מלחמת האדם ללחום עם הנה\"ב,",[["249","249","יומא כא, ב."],["250","250","קהלת ז, יד (ושם: האלקים). וראה תניא פרק ו."],["251","251","ראה קידושין מ, א."],["252","252","פרק טז (לעיל ע' לה)."],["253","253","שמות א, י."],["254","254","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שם: התחכמות."],["255","255","ירמי' ד, כב."],["256","256","סוטה ח, א. סנהדרין מה, א."]]],[2700520451,"ולבער הרע דמדות רעות, ואז הנה בדרך ממילא יבטלו המח\"ז והרהורים ודיבורים רעים. דהנה אנו רואים דמן המעשה בנקל יותר למנוע מכמו למנוע מן הדיבור, ומן הדיבור בנקל יותר מכמו המח', ולזאת העצה האמיתית היא שיהיו דברי תורה חקוקים במוחו, שיוכל לחשוב בהם בכל עת ובכל זמן, וכל השתדלות האדם החס על נפשו צ\"ל לעצור מוחו ולבו שלא לחשוב מחשבת חוץ בהרהורים רעים, ולבלום את פיו שלא לדבר בדיבורים רעים, דהעצה לזה שלא ילכד הוא מה שבד\"כ ימעט הדיבור של חול, וענין המיעוט הכוונה שבד\"כ הדיבור שלו בעניני עולם יהי' שלא בהרחבת הפה והלשון, וכנודע שבדיבור הרי יוצא כל עומק עצם הנפש לידי גילוי, וכמ\"ש בכתהאריז\"ל<sup data-n=\"257\">257</sup>, דהנה כשם שהדיבור דקדושה מגלה ומוציא עצם נפשו, בחי' עומק הטוב שבה, וכנ\"ל דע\"י האותיות דקדושה בתורה ותפלה מטהרים את הנפש, ונת\"ל<sup data-n=\"258\">258</sup> בענין נפשי יצאה בדברו<sup data-n=\"259\">259</sup>, דדברים היוצאי' מן הלב<sup data-n=\"260\">260</sup> מקרבים גם את הזולת ופועלים בו פעולה רבה במאד, לפי שהם המגלים עצם נפשו ובחי' עומק הטוב שבה, הנה כמו\"כ להיפך<sup data-n=\"261\">261</sup> הרי בדיבורי' של הוללות ופריקת עול והדומה יוצא ומתגלה כל עומק הרע של הנה\"ב בגילוי, והיינו שבא בהתגשמות, דקודם שמדבר הוא בהעלם עכ\"פ וע\"י הדיבור ה\"ה מתגלה ומתגשם, ולא מיבעי דיבורים אסורים שהם רע גמור, וכנ\"ל שהוא עוד קשה ממות ר\"ל, אלא גם דיבורי דברים בטלים, הרי הרחבת פיו ולשונו בדברים בטלים, זהו מצד הפר\"ע שבו, שאין פחד אלקים לנגד עיניו<sup data-n=\"262\">262</sup>, וכמ\"ש<sup data-n=\"263\">263</sup> שפתינו אתנו מי אדון לנו, וכנ\"ל דריבוי הדב\"ט גורמים היזק גדול לנפש, דבכדי לטהרה צריכים העונש דכף הקלע ר\"ל|48, ועוד זאת שהם הגורמים מח\"ז, ובאים לידי הרהורים שונים אשר מענין לענין בא ר\"ל לידי הרהורי עבירה ר\"ל, דהנה כתיב (ישעי' ה' י\"ח) הוי מושכי העון בחבלי השוא וכעבות העגלה חטאה, דההתחלה הוא חבלי השוא קורי עכביש<sup data-n=\"264\">264</sup> דב\"ט שאין בהם ממש כלל, או גם חלק הרשות שבדיבור כמ\"ש הרמב\"ם<sup data-n=\"e46\">*</sup>, ולבסוף נעשה חטאה כעבות העגלה, דזהו אומנתו של היצה\"ר אשר מוריד את האדם ח\"ו מדחי אל דחי, עד",[["257","257","ראה גם תורת חיים בא רא, ב (בהוצאה החדשה - קז, ג)."],["258","258","ראה ד\"ה ביום השמע\"צ תרצ\"א. בספר המאמרים ה'שי\"ת שבהערה :1 ונת' במ\"א."],["259","259","שיר השירים ה, ו."],["260","260","ראה ספר שירת ישראל לר' משה אבן עזרא ע' קנו: \"וכבר נאמר דברים היוצאים מן הלב נכנסים אל הלב\". ובספר הישר לר\"ת שער יג - הובא בשל\"ה סט, א: \"כי כל דבר שיצא מן הלב יכנוס בלב\"."],["261","261","ראה תורה אור ויחי קב, סע\"ג ואילך. מאמרי אדמו\"ר האמצעי ויחי ע' תעז ואילך. וראה גם תורת חיים בא שם."],["262","262","תהלים לו, ב."],["263","263","שם יב, ה."],["264","264","ראה פרש\"י ישעי' עה\"פ. סוכה נב, א ובפרש\"י."],["e46","*","<b>כמ\"ש הרמב\"ם:</b> בפיה\"מ לאבות ספ\"א."]]],[2700520493,"שמביאו לידי איסור ר\"ל. וזהו דכתיב (משלי כ\"א כ\"ג) שומר פיו ולשונו שומר מצרות נפשו, דישנם ר\"ל צרות הנפש, דצרות הנפש הם קשים באין ערוך מכמו צרות הגוף, וכמו שהאדם רואה במוחש דחולי הרוח ר\"ל קשים מחולי הגוף ח\"ו, וצרות הנפש באים ע\"י הריבוי בדברים בטלי', ומילוי התאווה גם בדברים המותרים מצ\"ע, וזהו שומר פיו ולשונו, ופי' הראב\"ע שומר פיו מלאכול, ולשונו מדיבור הרע, ואז הוא שומר מצרות נפשו. ולהיות דמחדו\"מ דנה\"ב הן התפשטות המדות רעות, לזאת העבודה היא לפעול הביטול בהמדות דנה\"ב, והוא ע\"י ההתבוננות בגדולת ד' בהתהוות העולמות והנבראי', ואיך שבאמת הכל טפל ובטל לאלקות, שכ\"ז יבין גם הנה\"ט ע\"י שמרגיש זה בנפשו, וכנ\"ל בענין שכל הטבעי, והיינו דגם בהנה\"ט יובן ויושג שגשמיות העולם מצ\"ע הוא מות, והתאוה והחמדה הוא רע שעוד קשה ממות, דע\"י השגה זו הרי גם הנה\"ט מתפעל ומתבטלי' המדות שלו, שלא זו בלבד שלא ירצה בגשמיות העולם, אלא עוד זאת שגם הוא ירצה שיהי' גילוי אלקות בעולם.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דמצוה להביא מן ההדיוט, האהבה הבאה בעבודה בבירור הנה\"ב, הנה\"ב יש בו ציור קומה, התחכמות להרע, מדות רעות ומהם באים הרהורים ודיבורים רעים, והעצה להיות ד\"ת חקוקים במוחו, ויבאר גודל החטא בדיבורים רעים שמעוררי' הרע הנעלם, שומר פיו מלאכל, ולשונו מלדבר שומר נפשו מצרות רוחנים.</span>\n<b>ענינים.</b> ו הנה\"ב ציור שלם במוחין ומדות. ז דיבורים רעים מעוררים רע הנעלם.\n<b>וזהו</b> אתה הבדלת אנוש מראש, דהנה ביוהכ\"פ כל ישראל הם במעלה ומדריגה נפלאה דלפני הוי' תטהרו, דבזה כל ישראל שוים להיות עצומו של יום מכפר וכמ\"ש|17 כי ביום הזה יכפר עליכם, ומ\"מ הרי בהעבודה דיוהכ\"פ יש בזה ג\"כ סדר והדרגה, דההתחלה הוא בתפלת מנחה דעיוהכ\"פ, ואח\"כ בהוידוי הכללי שקודם התחלת העבודה דעצומו של יום, וכל התפלות עד תפלת נעילה שהוא גילוי בחי' ימין העליון לקבל שבים, הנה אז הוא ההתעוררות גם מצד הגוף, שהוא החיים בשרים, וכמאמר|215 למען נחדל מעושק ידינו, דהתעוררות זו הוא גם מה שהנה\"ט מתפעל בהתפעלות גדולה, ואדרבא מצד כללות ענין ההתפעלות הרי בהנה\"ט הוא ביותר, דזהו ההפרש בין אדם לבהמה, דאדם הוא שכלי ותחלה הוא מבין ואח\"כ מתפעל על זה שהבין, ובבהמה הרי תחלה היא ההתפעלות, וכן הוא בהנה\"ט שההתפעלות היא ביותר, וזהו דאנוש שהוא חלוש ביותר והוא נמשך אחרי עניני הגוף, ומ\"מ ה\"ה עלול להתעורר לטוב, והוא ע\"י העבודה בהתבוננו' בסדר והדרגה דוקא. וזהו אתה הבדלת אנוש מראש, דגם מדרי' אנוש הוא נבדל ובלתי מקושר בהענינים הלא טובים, והוא ע\"י השמירה שלמעלה<sup data-n=\"265\">265</sup>, ולא זו בלבד אלא עוד ותכירהו לעמוד לפניך, דע\"י העבודה בהתבוננות בסדר והדרגה הוא העלי' בסולם",[["265","265","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שם: שמלמעלה."]]],[2700520530,"ההתקשרות דתפלה, עד כי גם הנה\"ט יכיר את האמת, כי העיקר הוא האור וחיות אלקי, ובא לכלל רצון לחפוץ שיהי' גילוי אלקות בעולם<sup data-n=\"266\">266</sup>.\n<b>סיום.</b> התפעלות הטבעי יותר מהשכלי, ואחר עבודת יו\"כ גם אנוש מתעלה.\n-------------------- * --------------------",[["266","266","הקיצור דשנת ה'שי\"ת: יודיע דהתכלית הוא בירור נה\"ב, דיש בו חו\"ב מדות ומחדו\"מ, ובאים זמ\"ז. יבאר נזק המח\"ז ודיבורים רעים, והעצה לזה ביטול מדות נה\"ב."]]],[2700520058,"<b>יהי</b><sup data-n=\"267\">267</sup> ה' אלקינו עמנו כאשר הי' עם אבותינו אל יעזבנו ואל יטשנו<sup data-n=\"268\">268</sup>, וצ\"ל תוכן בקשה זו דיהי ה\"א עמנו כו', ועוד דלאחר שאומר יהי ה\"א עמנו כו' הרי ע\"י העבודה דתפלה ממשיכים זאת, א\"כ מהו אומרו אל יעזבנו ואל יטשנו, דמשמע מזה דהגם שפועלים בקשה זו דיהי ה\"א עמנו וכו', מ\"מ יכול להיות עזיבה ונטישה ולזאת הוא הבקשה דאל יעזבנו ואל יטשנו, וצ\"ל מהו ענינם<sup data-n=\"269\">269</sup>.\n<b>התחלה.</b> יקשה דמאחר דיהי ה\"א עמנו כאשר הי' עם אבותנו מהו תוכן הבקשה אל יעזבנו ואל יטשנו.\n<b>ולהבין</b> כ\"ז ילהק\"ת דלאחר שההתבוננות הפרטית איך דעיקר הוא האור והחיות וכל הנבראי' העליוני' והתחתונים טפלים ונגררים אחר חיותם עד מקורם הראשון, יוקלט במוחו, הנה כל חפצו יהי' להתקשר בעיקר ומקור כל החיים העליונים והתחתונים, והגם דכל ההשפעות בא ע\"י הממוצעים הרוחנים, הנה חפצו בהאור והחיות האלקי שבהדברים הגשמי' ומואס בהחומריות שבגשמיות, דזהו ראה נתתי לפניך היום את החיים ואת הטוב את המות ואת הרע, דגשמיות הוא מות דכלה ונפסד, ולכן נקרא הוה ונפסד דבעת הוייתו הוא נפסד, והרוחניות הוא חיים בקיום נצחי, ויבאר כי הטוב שבחיים הוא חיי הנשמות, שמעולה לאין קץ מחיים שהוא רק כלי אל חיי החיים, ואת המות ואת הרע, דרע גרוע ממות לפי שהוא מנגד לחיי החיים, וזהו ראה נתתי לפניך את החיים, האור וחיות אלקי שבעולם ונבראי', ואת הטוב שבחיים הוא חיי נשמות ישראל, והעבודה להמשיך בחיי עולם בחי' הטוב שהוא חיי החיים, ויבאר המאמר מחיי' חיים יתן לך חיים ארוכים, וע\"י ההתבוננות בכל הנ\"ל באריכות ובפרטיות ה\"ה חפץ להדבק בחיי החיים, ומ\"מ הנה אהבה זו",[["267","267","ריש וסוף מאמר זה הועתק בריש וסוף ד\"ה יהי ה\"א עמנו תש\"ז (ספר המאמרים תש\"ז ע' 153. ע' 158 ואילך).\nבגוכתי\"ק כ\"ק אדמו\"ר מוהריי\"צ ב\"עניני מאמרי רצ\"ב\", נרשם: \"יהי ה\"א עמנו כאשר הי' עם אבותנו, ובו ג פרקים. ט ענינים\". - נעתקו לקמן במקומם."],["268","268","מלכים-א ח, נז."],["269","269","ראה ד\"ה יהי ה\"א עמנו דש\"פ קרח תשכ\"ד (מאמר ב')."]]],[2700520108,"נקרא<sup data-n=\"270\">270</sup> נהורא אוכמא, לפי שאין זה העבודה דנה\"א מצ\"ע, ויבאר דהעבודה הוא באש של מטה דמצוה להביא מן ההדיוט, דזה לעו\"ז עשה האלקים, וכשם שהנה\"א יש בו מוחין ומדות ולבושי הנפש דקדושה, כן הנה\"ב ציור קומה במוחין ומדות ולבושי' רעים, וכמו הבה נתחכמה דלעו\"ז, וכל השכלותיו דנה\"ב להשכיל בטוב הגשמיות דעי\"ז נולדי'<sup data-n=\"271\">271</sup> המד\"ר<sup data-n=\"272\">272</sup> המביאים מח\"ז וכו', והעצה לזה להיות ד\"ת חקוקים במוחו ולהשתדל לעצור בעד המחשבת<sup data-n=\"273\">273</sup> חוץ ולבלום פיו מלדבר דיבורים רעים, כי הדיבור מגלה עומק הטוב שבנפש, בקדושה הם אותיות התורה והתפלה ובלעו\"ז עומק הרע דנה\"ב שבא בהתגלות ובהתגשמות, וכתיב הוי מושכי עון<sup data-n=\"274\">274</sup> בחבלי השוא, וע\"י אומנות היצה\"ר נעשה כעבות העגלה חטאה, וזהו שומר פיו באכילה במה שמוכרח לו ולשונו בדיבור בעניני עולם שלא בהרחבת הפה והלשון הוא שומר מצרות נפשו, דצרות הנפש ר\"ל קשים מצרות הגוף ר\"ל, ושמירתם ע\"י שמירת הפה והלשון, ולהיות דמחדו\"מ של הנה\"ב הוא התפשטות המד\"ר ע\"כ כל העבודה צ\"ל בביטול והעברת הרע דמד\"ר ובמילא יבטלו המח\"ז והרהורים ודיבורים רעים המתפשטים ממנו, והוא ע\"י העבודה בהתבוננות בגדולת ד' בהתהוות העולמות והנבראי', ועי\"ז גם הנה\"ט מתפעל וירצה שיהי' גילוי אלקות בעולם.\nכג) <b>והנה</b> אהבה זו הבאה מצד ההתבוננות באור וחיות אלקי המהווה את העולם והנבראי' הרי כללות אהבה זו היא בחיצוניות הלב לבד, ועם היות דמעלתה בב' ענינים כנ\"ל, מה שהיא בקירוב לשכל הטבעי ע\"י שכל אנושי, ומה שנוגע בעבודה בפו\"מ בכל היום להיות עשיותיו לש\"ש, והיינו העסק בתו\"ע<sup data-n=\"275\">275</sup> ובקיום המצות בפו\"מ במדות טובות, ומה שמחלקים זאת בב' עניני' דלכאו' הוא ענין א', דמאחר שגם הנה\"ט מתפעל באהבה וחפץ שיהי' גילוי אלקות בעולם הרי אז ודאי דכל עשיותיו צריכים להיות לש\"ש. אך הענין בזה הוא, דלבד זאת שבעת ההתבוננות בכל הנ\"ל איך שהעיקר הוא האור והחיות האלקי וכל הנבראים טפלים ונגררים אחרי חיותם כנ\"ל, הנה בעת ההתבוננות צריך להרגיש זאת בעצמו, דערהערין דאָס אין זיך, ער דאַרף דאָס דערהערין אין זיך, דאָס הייסט אַז אין זיך דאַרף ער פיהלין אָט דאָס ואָס ער פאַרשטייט ויא דאָס איז בכל הנבראים, הנה לבד זאת הרי בעת ההתבוננות צ\"ל אצלו כוונה מיוחדת אודות הענין פרטי שלו כמו המדה פרטית שמברר אותה, דהנה כל עבודה ובירור צ\"ל בסדר והדרגה, כי בפעם א' אי אפשר לברר הכל ולתקן את הכל כ\"א לאט לאט<sup data-n=\"e47\">*</sup>, הנה בהמדה שהוא עסוק",[["270","270","כ\"ה בכי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שבהערה :1 נק'."],["271","271","כ\"ה בכתי\"ק ובהעתקה. שם: נולדו."],["272","272","המדות רעות."],["273","273","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שם: המחשבות."],["274","274","בכתוב (הנ\"ל ע' נג) \"העון\". וכ\"ה בסה\"מ ה'שי\"ת שם."],["275","275","בתורה ועבודה."],["e47","*","<b>כ\"א לאט לאט:</b> להעיר מקונטרס העבודה בסופו."]]],[2700520158,"בה לתקנה צ\"ל שיחשוב בזה בעת ההתבוננות, ואז הנה יהי' זה נוגע אל הפועל ממש בהעבודה דכל היום, ולולי זאת הרי יכול<sup data-n=\"276\">276</sup> כי גם הנה\"ט יתפעל באהבה בעת ההתבוננות ואחר התפלה בבואו בעניני עולם הרי נשכח ממנו כל הענין בהנוגע לעבודה, וזהו ב' הענינים בפעולת ההתבוננות הנ\"ל, ומ\"מ הרי כללות אהבה זו היא האהבה דנה\"א בכדי להאיר חשכת הנה\"ב בלבד, אבל האהבה והרצוא שבנה\"א מצ\"ע היא בחי' פנימיות הלב. והנה בהעבודה דפנימיות הלב הרי יש בזה כמה מדריגות זו למעלה מזו, דכל אחת מהם כלולה ממדריגו' שונות, והיינו דלבד זאת שנת\"ל<sup data-n=\"277\">277</sup> דענין פנימיות הלב הוא מה שהמדות נמשכין ממילא אחר כוונת המוח, הרי יש בזה עוד בחינות ומדריגות, דבאמת הנה בזה גופא מה שבפנימיות הלב הרי המדות נמשכים אחר המוח הנה גם בזה גופא יש ב' מדריגות, הא' מה שהמדות נמשכים אחר המוח בכלל, והיינו דהגם דמוחין ומדות הם חלוקים בעצם טבעם, דטבע המוחין הם בהתיישבות ובמנוחה דוקא, וטבע המדות בהתפעלות והתרגשות ושלא בהתיישבות, פי' במה שבעצם ענינו אינו מתיישב אצלו, ומ\"מ להיות זה בפנימיות הלב הרי המדות דשם הוא<sup data-n=\"278\">278</sup> הגם שהם מוגבלים ומוגדרים בהגבלה והגדרה של מדות, מ\"מ הנה זה ענינם שהם נמשכים אחר המוח, והיינו שהם בעצמם נשארים בטבע מהותם כמו שהם רק שנמשכים אחרי המוח, דההתפעלות שלהם היא בלתי מורגשת כ\"כ כמו שהוא בטבע המדות מצ\"ע, ונמשכים אחר המדה בכלל. ויש עוד מדרי' נעלית בסוג זה בכלל והוא זה, דמה שהמדות נמשכים אחר המוח אין זה שנמשכים אחר המוח בכלל, אלא שנרגש בהם גם כוונת המוח. דהנה ההפרש הכללי בין חיצוניות הלב ופנימיות הלב הוא מה שבחיצוניות הלב הרי המדות הם בצלמם ודמותם העצמי שהם התפעלות והתרגשות, דזה מה שמוחין ומדות הם בגדרים מיוחדי' ה\"ה הפכים זה מזה, דבמוחין שהוא התיישבות ומנוחה הוא הא בהא תליא, שהמנוחה הוא כלי אל ההתיישבות, דכל מה שהמנוחה יותר, ההתיישבות בפנימיות, וישוב גדול ביותר, צריך מנוחה יותר, וכן זה מה שהתפעלות הוא בהתרגשות ורעש הוא ג\"כ הא בהא תליא, שההתרגשות הוא כלי אל ההתפעלות, דכל מה שההתפעלות ביותר ההתרגשות הוא ביותר, וכל שההתרגשות יותר מרגיש טוב טעם בהתפעלות יותר, וכללות ענינו של המדות הוא בהב' קוין דדוקא באופן כך ולא באופן אחר כלל, והיינו דאינו נותן מקום כלל לזולתו, ופנימיות הלב הוא מה שהמדות נמשכים אחר המוח, הרי בהמשכה זו מה שהמדות נמשכים אחר המוח הוא כעין ביטול מהותם, דמהותם העצמי הוא שלא לתת מקום כלל לזולתם, וכאן כשנמשכים אחר המוח ה\"ה נותנים מקום ולא לבד לזולתם אלא גם להפכם. דכ\"ז הוא במדרי' הא', ובמדרי' הב' הרי הם מרגישים גם הכוונה שבמוח, שזהו עוד נעלה יותר, ועם זה ה\"ה נשארים במהותם העצמי שהם מדות, רק שההתפעלות הוא כמו שבעל השגה מתפעל, וכמו שאנו רואין במוחש בטבעי בנ\"א, יש שהוא שכלי, ויש",[["276","276","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שם: יכול להיות."],["277","277","פרק יד (לעיל ע' כט)."],["278","278","בספר המאמרים ה'שי\"ת שם - ליתא תיבה זו."]]],[2700520208,"שהוא איש לבבי, אַ האַרציקער, דשניהם יש להם שכל ומדות, רק דמי שהוא שכלי להיות שהשכל הוא קר לכן הגם שהוא מתפעל הוא ג\"כ שלא בחמימות בוערת, ומי שהוא לבבי הרי ההתפעלות שלו הוא בחמימות מתלהטת, כי הבעל השגה הגם שהוא מתפעל אבל גם זה בישוב, ומ\"מ הרי התפעלות אינו שכל, וכן הוא באופן הב' דפנימי' הלב, דהמדות הם כמו במדריגת המוחין, והיינו שאינו רק הנתינת מקום למוחין כמו שהוא באופן הא', אלא שהמדות נמשכים אחר כוונת המוח. אמנם כ\"ז הוא בכלל האהבה שע\"פ טו\"ד, שהרי האהבה הזאת בכללותה גם מדרי' הב' היא מה שבאה ע\"י ההשגה וההתבוננות באלקות, רק שההתבוננות היא בעצם האור האלקי, שזהו כמו שהענין אלקי מובן בהשגה שכלית דשכל אלקי, ובשכל אלקי גופא כמו שמפשיטו מלבושי השגה, שבהם יהי' היחס דשכל אנושי כנ\"ל, ומקשר א\"ע בעצם הענין האלקי שמלובש בהשכל אלקי כנ\"ל, והגם שזהו אור המושג, והיינו שבא בהשגה, וכל השגה הוא מה שכבר הצטייר הדבר בשכל מושג ומוגבל, אבל הוא זה מה שהאור אלקי מאיר במוחו. ויובן זה במכש\"כ מלבושי הנפש, דהגם שהאור מבהיק, במח' שבמח' הוא מלובש באותיות, והראי' דאותיות אלו עצמן באים אח\"כ במעשה שבדיבור כנ\"ל, מ\"מ הרי במח' שבמח' הוא גילוי אור רב, א\"כ יובן במכש\"כ כמו שהוא כאשר האור אלקי מאיר במוחו, לזאת הנה גילוי זה מתפשט גם בלב בפנימיות לבו, שהמדות נמשכים ממילא אחר המוח, וכנ\"ל דלהיות שעצם האור מאיר בגילוי בהמדות לכן הנה המדות הם בבחי' התפעלות בלתי מורגשת, דכ\"ז הוא בחי' השגה בטו\"ד, והוא מבחי' בינה, דהשגה הוא מה שהמושכל כבר בא מצוייר בעניניו, ונת\"ל דכל הציורים הם מבחי' בינה, דבינה ציירא ציורים בהנקודה דחכ', ולזאת הנה השגה זו היא בבחי' בינה רק שזהו בחי' פנימיות בינה. והנה יש עוד מדרי' בפנימיות הלב שהיא למעלה מאהבה זו, והיא האהבה והדביקות שמבחי' ראי' דחכ', דהיינו בחי' אהבה בתענוגים, דענין הראי' היא ג\"כ ידיעה שכליית, וכאומר אַז ער זעט אַז דיא זאַך איז אַזיי, דידיעה זו באה אחר ההשגה, והיינו דכאשר יודע את עומק המושג ומקשר א\"ע בעצם הענין האלקי ה\"ה בא אח\"כ לידי ראי' שהוא בחי' ההתאמתות וההנחה בנפש, דער לייג אין נפש מעצם הענין, וההרגש והתענוג בזה הוא בבחי' אור פנימי בנפש, דזהו סיבת הדביקות שלו, והיינו דאין זה בהנפש מצד עצמו, ר\"ל מצד עצם התקשרותו, כ\"א מצד התענוג שמתענג על ה', וכ\"ז הוא בחי' פנימיות הלב שנכלל בכלל העבודה שע\"פ טו\"ד.\n<b><b>קיצור</b>.</b> יבאר כי ההתבוננו' פרטית בהחיות אלקי שבנבראים צריך להרגיש גם בעצמו ולהתעסק בתפלה בבירור מדה פרטית, ויבאר כי אהבה זו באה מהנה\"א להאיר חשכת הנה\"ב, אבל האהבה דנה\"א היא פנימית הלב, ויסביר דבחיצוניות הלב המדות מתפעלים מההשגה שבמוח, ובפנימיות הלב המדות נמשכים א) אחר המוח, ב) אחר כוונת המוח, שנרגש בשכל האלקי, וכ\"ז השגה דבינה, ראי' דחכ' אהבה בתענוגים<sup data-n=\"279\">279</sup>.",[["279","279","הקיצור דשנת ה'שי\"ת: בהתבוננות דביטול הנבראים למקורם צריך להרגיש זאת בעצמו ולכוון לענין פרטי שלו. יבאר מדרי' בפנימיות הלב, שהמדות נמשכים אחר המוחין אף שהם הפכים, או שגם מרגישים כוונת המוחין, או כשבאים מראי' דחכמה."]]],[2700520258,"<b><b>ענינים</b>.</b> א בתפלה להתעסק בבירור מדה פרטית. ב פנימיות הלב, א) מדות נותנים מקום למוחין, ב) נמשכים אחר כוונת המוח, ג) דביקות הבאה מראי' דחכ'.\nכד) <b>והנה</b> יש בחי' פנימיות הלב שלמעלה מטו\"ד, והוא רעו\"ד, שזהו בחי' התעוררות עצמי שבנפש שלמעלה מטו\"ד, והוא רק מה שנמשך לשרשו ומקורו. דהנה זה שנת\"ל בענין רעו\"ד הוא רק בכללות הענין בההפרש שבין תשובה ורעו\"ד, דלכאו' הרי תשו' ורעו\"ד הרי שניהם הם במרוצה גדולה בהתעוררות עצמי שבנפש, ונתבאר שהם ב' תנועות חלוקים זמ\"ז, דתנועת התשובה הגם שהיא במרוצה גדולה וכבורח מן המות ר\"ל, הנה סיבתה הוא הריחוק, ותנועת רעו\"ד סיבתה הקירוב, והגם דבבריחה זו הרי נרגש יוקר החיים, וכנ\"ל דמי שהוא ר\"ל במקום סכנה ה\"ה מרגיש יוקר החיים, האמת הוא דבתנועה דתשו' הוא הרגשת יוקר ובתנועה דרעו\"ד הוא הרגש החיים, ולכן התשובה עיקרה ברצוא ורעו\"ד עיקרה בהמשכה, דבהמשכה זו הרי יש בה ג\"כ ב' מדרי'<sup data-n=\"280\">280</sup>, הא' ההתעוררות שנעשה ע\"י ההשגה בהפלאת אוא\"ס ב\"ה איך שמופלא מהעולמות, דע\"י השגה זו ה\"ה נמשך לאוא\"ס ב\"ה, ועם היות שההמשכה והרצוא הוא מצד עצם נפשו שרוצה בעצם באלקו', מ\"מ הרי סיבת ההתעוררות היא ע\"י ההתבוננות וההשגה בהפלאת אוא\"ס ב\"ה, והגם שאין זה בבחי' השגה ממש כ\"א בבחי' ידיעת השלילה, הרי נת\"ל<sup data-n=\"281\">281</sup> דבמושכלות הרי גם יחס שלילי הוא תואר מוגבל, לפי שידיעה הבא' בדרך שלילי הוא ידיעה ממש, ומאחר שיש סיבה אל הרצוא ממילא ה\"ה בבחי' מורגש, והיינו שיש מבוקש בהרצוא, ובמבוקש זה גופא יש ב' אופנים, הא' שרוצה בהגילוי אור, והב' שרוצה להיכלל באוא\"ס ב\"ה, וא\"כ הרי אהבה זו הגם שהיא רמה ונשאה מ\"מ היא ג\"כ מבחי' בינה, אמנם עיקר בחי' רעו\"ד הוא המדרי' הב', דהיינו שאין שום סיבה כלל אל ההמשכה והרצוא, דכל סיבה הוא טעם שהטעם הוא סיבת הדבר, והמשכה ורצוא זה הוא למעלה מטו\"ד לגמרי, גם לא בחי' השגת הפלאת אוא\"ס ב\"ה, כ\"א מה שהנפש נמשך ממילא לעצמות אוא\"ס ב\"ה לפי שהוא שרשו ומקורו, דזהו ההתקשרות עצמי של הנפש באוא\"ס, והיינו שבעצם נפשו ה\"ה מקושר ממש בעצמות אוא\"ס ב\"ה, וכאשר מתגלה בחי' ומדרי' זו ה\"ה נמשך ממילא לאוא\"ס ב\"ה בלי שום מורגש ובלי מבוקש כלל כ\"א מה שעצם הנפש נמשך ציט זעך ממילא לעצמות אוא\"ס ב\"ה, והיא בחי' אה\"ר שבנה\"א הכלולה בחכ' שבנפשו, כמ\"ש רבינו נ\"ע<sup data-n=\"282\">282</sup> בפי\"ט דבחי' חכ' הוא הביטול שלמעלה מטו\"ד, שעז\"נ|137 נר הוי' נשמת אדם, דכמו שאור הנר הרי טבעו לעלות למעלה, דטבע זה הוא בהאור שלמעלה מן הפתילה, דהאור הזה נק' נהורא חיוורא השורה על האור דנהורא אוכמא, דנהורא אוכמא הוא האש השורף את",[["280","280","ראה ספר המאמרים עטר\"ת ע' לה. ע' רסח. המשך תער\"ב ח\"א ע' נט."],["281","281","פרק יג (לעיל ע' כז)."],["282","282","בתניא."]]],[2700520308,"הפתילה, ונת\"ל דענינו הוא מה שעושה ומהפך את הפתילה לאור והוא נח בהפתילה, והגם דזה מה שטבע האש לעלות למעלה הרי טבע זה ישנו באור זה ג\"כ, מ\"מ ה\"ה נאחז בהפתילה באופן כזה דזה מה שטבעו לעלות הרי אינו ניכר ונגלה, ומה שנגלה הוא שנח<sup data-n=\"283\">283</sup> בהפתילה, ועיקר הטבע מה שעומד תמיד בתנועה דהסתלקות למעלה הוא בנהורא חיוורא, היינו באור הבהיר שלמעלה מן הפתילה, ועלי' והסתלקות זו היא בטבע בהאור, ואף<sup data-n=\"284\">284</sup> שעי\"ז יכבה ולא יאיר כלום למטה, וגם למעלה בשרשו יתבטל אורו במציאות בשרשו, אעפ\"כ בכך הוא חפץ בטבעו, כך נשמת האדם, וכן בחי' רוח ונפש חפצה וחשקה בטבעה ליפרד ולצאת מן הגוף ולידבק בשרשה ומקורה בה' חיי החיים ב\"ה, הגם שתהי' אין ואפס ותתבטל שם במציאות לגמרי ולא ישאר ממנה מאומה ממהותה ועצמותה הראשון, אעפ\"כ זה רצונה וחפצה בטבעה<sup data-n=\"285\">285</sup>, וכ\"ז אינו מצד ההשגה שמשיג אלקות כ\"א הוא מצד שזהו שרשה ומקורה, דשרש הנשמות הוא בבחי' פנימיות ועצמות אוא\"ס ב\"ה וכמ\"ש|90 בנים אתם לה\"א, ולזאת הנה בעצם נפשו הוא באמת בבחי' התקשרות תמידי בעצמות אוא\"ס ב\"ה, וכמא'<sup data-n=\"286\">286</sup> חבוקה ודבוקה בך, דעצם הנפש הוא תמיד חבוק ודבוק בעצמות אוא\"ס ב\"ה, שעז\"נ (שה\"ש ח' ו') שימני כחותם על לבך כחותם על זרועך וגו', ואי' בזח\"א דרמ\"ד ע\"ב ארחי' דחותם כיון דאתדבק באתר חד אע\"ג דאתעדי מיני' הא אשתאר רשימו בההוא אתר ולא אעדי מיני', דדרכו של חותם הוא כיון שנדבק במקום א' אעפ\"י שאח\"כ הוא מתפרד ממנו, מ\"מ הלא רושם נשאר, ואינו רושם בעלמא רק במקום א', אלא דכל רשימו וכל דיוקנא דילי' בי' אשתאר, כך אמרה כנס\"י הא אתדבקנא בך אע\"ג דאתעדי מינך ואזיל בגלותא, מ\"מ הרי דיוקני אשתאר בך<sup data-n=\"287\">287</sup>, הרי במילא דיוקנך אשתאר בי, וזהו הא אתדבקנא בך, דשרש הנשמות מהעצמות ובבחי' דביקות בהעצמות ממש, אע\"ג דאתעדי מינך בירידת הנשמה בגוף, ואזיל בגלותא בגוף שמתעלמת בנה\"ב, ולפעמים היא בבחי' ריחוק, והיינו בהעדר עבודתה בהתבוננות באלקות ובהתעוררות אהוי\"ר, שאז מתגברים הכחות דנה\"ב שמעלימים ביותר, ופועל זה גם בנה\"א, וכנ\"ל דהנה\"א מתלבש בהנה\"ט, מ\"מ הרי דיוקני אשתאר בך, דבמילא הרי דיוקנך אשתאר בי לעולם, דבחי' עצם נקודת הנשמה היא בבחי' התקשרות תמידי בעצמות אוא\"ס ב\"ה<sup data-n=\"288\">288</sup>.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר ההפרש בתנועת המרוצה, דבתשובה הוא מצד הרגש יוקר החיים, ועיקרו ברצוא, וברעו\"ד הוא הרגש החיים עצמו, ועיקרו בהמשכה, ומבוקשו, א) גילוי אור, ב) להכלל באוא\"ס, ויסביר דעיקר מדריגת רעו\"ד הוא ענין</span>",[["283","283","בספר המאמרים ה'שי\"ת שבהערה :1 מה שנח."],["284","284","לשון אדמו\"ר הזקן בתניא שם."],["285","285","עכ\"ל אדמו\"ר הזקן בתניא שם."],["286","286","נוסח הושענות (יום ג')."],["287","287","בספר המאמרים ה'שי\"ת שבהערה 1 יש כאן הגהה, וז\"ל: (וע' בזח\"ב דקי\"ד ע\"א דמפרש דיוקני דכנס\"י למעלה, אמנם בדא\"ח מבואר כמ\"ש כאן). ונשמט בהעתקה."],["288","288","ראה גם לקו\"ת שה\"ש מה, סע\"ג ואילך. אוה\"ת שם ח\"ב ע' תשלג."]]],[2700520358,"<b></b><span data-k=\"ks\">הב' להכלל, וזה מצד עצם נפשו שאין חל בזה ל' הרגש ומבוקש אלא שזהו עצמות ענינו, והוא רושם חותם העליון, דיוקנך אשתאר בי, דגם שהגוף ונה\"ב מעלימים עצם הנשמה בהתקשרות תמידי<sup data-n=\"289\">289</sup>.</span>\n<b><b>ענינים</b>.</b> ג תשובה, א) מרוצה, ב) הרגש היוקר דחיים, ג) עיקרו רצוא. ד רעו\"ד, א) מרוצה, ב) הרגש החיים עצמו, ג) עיקרו המשכה, ד) מבוקשו, א) גילוי אור, ב) להכלל. ה דיוקני אשתאר בך דיוקנך אשתאר בי.\nכה) <b>והנה</b> התקשרות זאת היא בבחי' התקשרות עצמית, דבעצם הנשמה מאיר ונרגש בה בחי' עצמו' אוא\"ס ולזאת היא תמיד בבחי' התקשרות בעצמות אוא\"ס ב\"ה, וכאשר מתגלה בחינה ומדריגה זו ה\"ה בבחי' תוקף הרצוא לצאת מגדר הכלים ולהפרד מן הפתילה הוא הגוף ולהיכלל בעצמות אוא\"ס והיא כשלהבת העולה מאלי' לדבקה בו, וכמו\"כ האהבה והרצוא דהנה\"א מצד ההשגה הרי השגת הנה\"א מצ\"ע הוא בבחי' מהות אלקות לא בבחי' המציאות לבד, וכמו השגת הנשמו' בג\"ע ה\"ה משיגים<sup data-n=\"290\">290</sup> מהות הזיו, וכנ\"ל<sup data-n=\"291\">291</sup> דזיו השכינה שבג\"ע הוא הארת האצי', והשגת הנשמות בג\"ע הוא שמשיגים מהות הזיו, אשר באמת הוא כן גם בהנשמה למטה, שהרי הנשמה באה למטה שלא בבחי' שינוי המהות, וכנ\"ל|291 דבירידת הנשמה הרי גם הנפש אינו משתנה בעצם מהותו, וכתיב<sup data-n=\"292\">292</sup> ויפח באפיו נשמת חיים, שלא יש שום דבר המפסיק ומבדיל בין הנופח ובין ההבל היוצא בנפיחתו<sup data-n=\"293\">293</sup>, ובמילא הרי היא בלי שום שינוי המהות כלל, והיינו דמפני דשרשה הוא מבחי' עצמות אוא\"ס ב\"ה, דמאן דנפח מתוכי' נפח<sup data-n=\"294\">294</sup>, פי'<sup data-n=\"295\">295</sup> מתוכיותו ומפנימיותו, לזאת הנה המשכתה של הנשמה הוא באופן כזה שאינה משתנית, ומשו\"ז הנה גם בירידתה למטה ה\"ה מצ\"ע משגת בחי' מהות אלקות, וזהו דכתיב (ישעי' כ\"ה ט') ואמר ביום ההוא הנה אלקינו זה, דביום ההוא קאי על לע\"ל, דלע\"ל הנה גם בכללות נש\"י יהי' בחי' גילוי המהות ממש, דהנה עכשיו הרי הנה\"ב מחשיך על הנה\"א ומכסה העין דנה\"א שאינו רואה, וכנ\"ל בענין הכחות דנה\"א כמו שהם קודם הירידה הוא בבחי' ראי', והיינו דכל הכחות שלה כמו שהם למעלה ה\"ה במדריגת ראי' במהות האלקות, אמנם בירידתה למטה הרי ההתלבשות מכסה על העין דנה\"א שאינה רואה, אבל לע\"ל לאחר גמר הבירורים יהי' בכאו\"א גילוי בחי' המהות דאלקות, וכמו\"כ הוא גם עכשיו בצדיקים הגדולים ובנשמות הגבוהות המופשטות מן הגשם, דהגשם",[["289","289","הקיצור דשנת ה'שי\"ת: ימשיך במדריגות דפנימיות הלב, רעו\"ד כשבאה ע\"י סיבה, כשבאה ממילא, התקשרות עצמי בלי מורגש ומבוקש, נהורא חיוורא."],["290","290","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שם: הוא שמשיגים."],["291","291","פרק יב (לעיל ע' כה)."],["292","292","בראשית ב, ז."],["293","293","ראה תניא אגה\"ת פ\"ה."],["294","294","תניא רפ\"ב בשם הזהר. וראה \"מ\"מ, הגהות והערות קצרות לתניא שם\". וש\"נ."],["295","295","תניא שם."]]],[2700520405,"אינו חוצץ וכו', ובפרט נשמות הכללים דראשי אלפי ישראל. והנה כל ענין ירידת הנשמה למטה להתלבש בלבוש נוגה הגופני הוא כדי להראות גם את הנה\"ב דנוגה בחי' גילוי אלקות כדי שעי\"ז יתברר ויתתקן, והוא ע\"י ההתבוננות בענין התהוות יש מאין, דהרי הנשמה לא ירדה בשביל עצמה<sup data-n=\"296\">296</sup>, דהנשמה מצ\"ע ה\"ה דבוקה בעצמות ומהות אוא\"ס ב\"ה כנ\"ל, דאופן דביקותה הוא כאופן דביקות החלק בהעצם, רק ירידתה הוא בכדי לפעול הביטול דנה\"ב, וענין ביטולו הוא שיבוא באהבה לה', וא\"א לבוא לידי אהבה או יראה כ\"א ע\"י השגה, ובכדי להראות את הנה\"ב גילוי אלקות א\"א כ\"א ע\"י ההתבוננות בענין יש מאין בבחי' השגת המציאות בלבד, כי משם הוא מקור חוצבו של הנה\"ב דהיינו רק מבחי' התפשטות כח האלקי, ולזאת הנה ההתבוננו' ג\"כ צ\"ל בענין מקור חוצבו, דזה יכול גם הוא להבין במקצת עכ\"פ, וזה יפעול עליו להבטל<sup data-n=\"297\">297</sup>. וזהו דכתיב<sup data-n=\"298\">298</sup> אתה הראת לדעת כי הוי' הוא האלקי', דהנה\"א ירד ונתגלה למטה בגוף בכדי לגלות דיעה גם בעניני בשר הגופני, דגם השכל הטבעי יוכל להבין ענין הארה אלקית מה שביכולתו להבין ושע\"י השגה זו הרי יתבטל בבחי' ביטול היש עכ\"פ, וזהו אתה הראת, דוא האָסט באַויזין, לדעת בשביל גילוי הדיעה האמיתית, דהוי' הוא אלקים<sup data-n=\"299\">299</sup>, דע\"י ידיעה והשגה זו נעשה שבירה בהחומרית של הנה\"ב, וזהו לדעת שיש בו ב' פירושים, הא' דעה והשגה, והב' מל' שבירה וכתיתה<sup data-n=\"300\">300</sup>, וכמ\"ש<sup data-n=\"301\">301</sup> וידע בהם אנשי סוכות, דע\"י הדעת בהשגה<sup data-n=\"302\">302</sup> אלקות הנה עי\"ז הוא שבירת וזיכוך החומריות דגוף ונה\"ב, וכמו למען דעת כל עמי הארץ, דע\"י הדעת שוברים את הארציות והחומריות, וע\"י שבירת החומריות דנה\"ב הנה עי\"ז יתגלה אור הנה\"א, וכמו דע\"י שבירת קליפת האגוז מתגלה הפרי<sup data-n=\"303\">303</sup>, כמו\"כ ע\"י שבירת וכפיית הנה\"ב מאיר אור הנשמה בהשגתה מצ\"ע בבחי' השגת המהות דאלקות, דעי\"ז נעשה ביטול הנה\"ב בדרך ממילא ובעצם המהות שלו, דהביטול הנ\"ל הוא ע\"י התעסקות הנה\"א לברר ולתקן את הנה\"ב, שז\"ע ששת ימים תעבוד<sup data-n=\"304\">304</sup>, שהנה\"א עובד עבודתו לתקן הנה\"ב, וזהו רק בעניני' השייכי' להנה\"ב שהן שרשו ומקורו, ופועלים בו הביטול כמהות ענינו, והיינו ביטול היש לבד, אבל אח\"כ כאשר מאיר אור עצם הנשמה נעשה הביטול ממילא בנה\"ב ובבחי' ביטול במציאות. וזהו סמכוני באשישות, בב' אשות, אש של מטה ואש של מעלה, והן נהורא אוכמא ונהורא\nחיוורא, דנהורא אוכמא הוא אש<sup data-n=\"305\">305</sup> של מטה להאיר חשכת הנה\"ב, ונהורא",[["296","296","ראה תניא פל\"ז (מח, ב)."],["297","297","ראה גם תו\"א וישב ל, ב ואילך. לקו\"ת ויקרא ב, ב. תצא לד, ד."],["298","298","ואתחנן ד, לה."],["299","299","בספר המאמרים ה'שי\"ת שם: האלקים."],["300","300","ראה תו\"א וארא נז, א. לקו\"ת דרושים לשמע\"צ פח, סע\"ג. ספר המאמרים תרס\"ט ע' מז. ובכ\"מ."],["301","301","ספר שופטים ח, טז (ושם: את אנשי סוכות) ובתרגום שם."],["302","302","אוצ\"ל: בהשגת."],["303","303","ראה ספר החקירה לאדמו\"ר הצ\"צ צד, סע\"ב ואילך. ובכ\"מ."],["304","304","יתרו כ, ט. ואתחנן ה, יג."],["305","305","בספר המאמרים ה'שי\"ת שבהערה :1 אור."]]],[2700520452,"חיוורא הוא אור עצם הנשמה כמו שמשגת בחי' מהות ועצמות אלקות, וזהו נהורא חיוורא שאינה להאיר את החושך כ\"א עצם בחי' האור.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דבעצם הנשמה ההתקשרות תמיד, ובהתגלותה הוא תוקף הרצוא והיציאה מגדר כלים, ויבאר דהשגת הנה\"א מצ\"ע הוא במהות אלקות ודביקותה הוא כחלק בהעצם, דבירידתה למטה הוא כמו בהיותה למעלה, אלא שהנה\"ב מחשיך, וכל ענין ירידתה בשביל בירור הנה\"ב והוא ע\"י ההלבשה בלבושי השגה, אתה הראת לדעת, דע\"י גילוי זה נעשה שבירה בהחומריות, השגת הנה\"ב נהורא אוכמא, אור עצם הנשמה נהורא חיורא.</span>\n<b>ענינים.</b> ו עצם הנשמה, א) מקושר תמיד, ב) בהתגלותה תוקף הרצוא. ז הנה\"א, א) השגתו במהות אלקות, ב) דביקותו כחלק העצם, ג) ירידתו לברר הנה\"ב. ח נהורא אוכמא השגת הנה\"ב. ט נהורא חיורא אור עצם הנשמה.\n<b>וזהו</b> יהי ה' אלקינו עמנו כאשר הי' עם אבותינו וכו'|269, דאבותינו הם חו\"ב<sup data-n=\"e48\">*</sup> שבנפש, דחכ' שבנפש הוא הביטול האמיתי שהוא היו\"ד דשם הוי' שבנפש, והיא האה\"ר שבנפה\"א כנ\"ל, ובינה שבנפש הו\"ע ההשגה באלקות שישנו לכאו\"א מישראל מצד שהוא בעצם נפשו מקושר בעצמות אוא\"ס ב\"ה, אמנם כ\"ז הוא מצד הנפש והנשמה, אבל בהתלבשות הנשמה בגוף הרי ההתלבשות מכסה גם על העין דנה\"א שאינו רואה מהות אלקות ורק ידיעתו והשגתו היא השגת המציאות בלבד, וכן בעניני העבודה הרי העיקר הוא לפעול ביטול הנה\"ב ובירור עניני עולם התחתון, דכ\"ז הוא ע\"י ההתבוננות בכללות בענין ההתהוות בריאה יש מאין ובפרטיות בנבראי' התחתונים דדו\"צ ובאופן חיותם, הנה זאת היא תוכן הבקשה דיהי ה\"א עמנו בעבודתנו בעבודת הבירורי', כאשר הי' עם אבותינו, חו\"ב שבנפש כמו שהם, והגם כי מצד החו\"ב שבנפש הוא גם עתה כן, וכנ\"ל דבאמת הוא כן גם בהנשמה למטה, שהרי הנשמה באה למטה שלא בבחי' שינוי המהות כנ\"ל רק שהוא בהעלם, לזאת הבקשה שאל יעזבנו ואל יטשנו, ובעבודה ענינו שלא יטעה בעניני עבודתו ללכת בדרכי ההפלאה מאתו, וכן לפעמים להיפך שלא יפול רוחו עליו. וזהו יהי ה\"א עמנו בעבודת הבירורים כאשר הי' עם אבותינו בחו\"ב שבנפש, ואל יעזבנו ואל יטשנו הוא בנתינת כח על עבודת הבירורים ושלא יהיו עניני טעות בעבודה בפרט, וכ\"ז הוא בעבור אבותינו, דזכות אבות לא יתמו\n<sup data-n=\"306\">306</sup> לעד<sup data-n=\"307\">307</sup>.",[["306","306","ויק\"ר פל\"ו, ו. וראה ספר המאמרים תרפ\"ט ע' 165 הערה 30. וש\"נ."],["307","307","הקיצור דשנת ה'שי\"ת: ימשיך דההתקשרות הוא בעצמות וכן האהבה דהשגה דנה\"א הוא במהות, ולע\"ל יתגלה בכאו\"א. דנה\"ב רק במציאות, ולכן התחלת ביטולו ביטול היש, ע\"י התבוננות בזה. עי\"ז נתגלה נה\"א ופועל ביטול במציאות דנה\"ב."],["e48","*","<b> דאבותינו הם חו\"ב:</b> ראה תניא רפ\"ג. לקו\"ת דרושים לשבת תשובה ד\"ה שובה (השני) ספ\"ג [סז, א]. ובכ\"מ."]]],[2700520494,"<b>סיום.</b> אבותנו חו\"ב, חכ' ביטול בינה השגה, אמנם בהתלבשות הוא ידיעת המציאות ועבודה בפועל, וזהו הבקשה דיהי ה\"א עמנו בהעבודה בפועל כמו שהוא בחו\"ב ואל יעזבנו כו' שלא יהי' עניני טעות בעבודה, דזכות אבות לא יתמו לעד.\n-------------------- * --------------------"],[2700520059,"<b>בסכת</b><sup data-n=\"308\">308</sup> תשבו שבעת ימים כל האזרח בישראל ישבו בסכת<sup data-n=\"309\">309</sup>, והנה סוכה הוא מקיף, וישיבה הו\"ע ההתיישבות וצ\"ל איך שייך התיישבות במקיף, דזהו כל ענין המקיף שאינו בבחי' התיישבות, דפנימי הוא בהתיישבות ומנוחה, ומשמע מזה דסוכה ענינה מקיף שבא' בהתיישבות, ומ\"מ הוא נשאר במדריגתו העצמי שהוא מקיף, ומהו תשבו שבעת ימים במספר מוגבל, דמקיף הוא עיגול ואיך שייך בעיגול שיהי' בבחי' מספר בכלל, דזהו ההפרש בין קו לעיגול, דבקו הוא סדר ומדריגות מעלה ומטה עליון ותחתון ובמילא שייך בזה מספר, אבל במקיף שהוא עיגול איך שייך ענין המספר בכלל, ומהו המספר שבעה. ועוצ\"ל כפל הענין כל האזרח בישראל ישבו בסכת, דלאחר שאומר בסכת תשבו שבעת ימים מהו חוזר וכופל דכל האזרח בישראל ישבו בסכת, ובזה אינו מזכיר ענין הזמן כמו שהוא אומר בתחלה שבעת ימים, דמובן מזה שהיא מדריגה אחרת. ומכללות הענין מובן דזה אשר בסכת תשבו שבעת ימים הוא לפי דכל האזרח בישראל ישבו בסכת, והיינו דלהיות כי כל האזרח בישראל ישבו בסכת, לזאת הנה בסכת תשבו שבעת ימים, וצ\"ל מהו כללו' ענין זה. והנה בגמרא (סוכה דכ\"ז ע\"ב) אי' כל האזרח בישראל ישבו בסוכות מלמד שכל ישראל ראוים לישב בסוכה אחת, וצ\"ל מהו המעלה דסוכה אחת, ומהו דכל ישראל ראוים לישב בסוכה אחת, ומהו הסוכה אחת דכל ישראל ראוים לישב בה, ומאחר דכל ישראל ראוים לזה הנה מצד למעלה הרי הוא כן דכל ישראל יושבים בסוכה אחת.\n<b>התחלה.</b> יקשה איך שייך ישיבה במקיף ומספר בעיגול, ומספר דז', ומהו ישיבת האזרח ובלי זמן מוגבל, ומהו הסוכה אחת דכל ישראל יושבים בה.\n<b>ולהבין</b> כ\"ז ילהק\"ת כללות ענין שנת\"ל<sup data-n=\"310\">310</sup> דבבריאת והתהוות העולמות מצינו שני לשונות, דפעם כתיב כל אשר חפץ ד' עשה, דבריאת והתהוות העולמות והנבראים הוא מבחי' חפץ ורצון ד' לבד, ופעם כתיב בדבר ד' שמים נעשו ובע\"מ נבה\"ע, דבריאת והתהוות העולמות והנבראים הוא במאמר ודיבור, ולא רק מבחי'",[["308","308","בגוכתי\"ק כ\"ק אדמו\"ר מוהריי\"צ ב\"עניני מאמרי רצ\"ב\", נרשם: \"בסכות תשבו שבעת ימים, ובו ה פרקים. טו ענינים\". - נעתקו לקמן במקומם."],["309","309","אמור כג, מב."],["310","310","פרק ט (לעיל ע' יט)."]]],[2700520109,"חפץ ורצון ד' לבד, כ\"א שבא בגילוי במאמר ודיבור מפורט, ונת' כי כל נברא יש בו חומר וצורה, דחומר הוא גוף הנברא וצורה הוא אור השפע האלקי שהוא חיות הנברא המתלבש בו להחיותו, דהתהוות ובריאת חומר הנבראים הוא במאמר ודיבור, אבל התהוות צורת הנבראי' הוא בחפץ ורצון ד' שלא בא עדיין לכלל מאמר ודיבור, וטעם הדבר מפני מה גם חומר הנבראי' לא נתהוו בבחי' חפץ ורצון בלבד, לפי דאם גם חומר הנבראי' הי' התהוותם בבחי' חפץ ורצון ד', שלא בדיבור ומאמר, אז הי' הכל ברוחניות, והי' הכל בטל, כמו שהוא הביטול מצד החכ', דאיהו וחיוהי חד|126, והכוונה העליונה היא שיהי' עבודה דוקא, ונת' כי בכל נברא הנה גופו הוא חשך לגבי נשמתו, דכן הוא באדם דכחותיו הגלוים בהתלבשות הנשמה בגוף הם חשך לגבי כמו שהם טרם שנתלבשו, וכן בהעבודה בהכחות דנפה\"א, וכן הוא בהחיות דנבראי', דההתגלות הוא באין ערוך לכמו שהחיות כלול במקורו, והמלאכים משיגים זאת, וכן מושג הדבר היטב בהתבוננות פרטית בתפלה, שהיא סולם ההתקשרות, המקשר את האדם ועניני עולם התחתון באוא\"ס, ומ\"מ נק' זה נהורא אוכמא, שהוא חשך לגבי העבודה האמיתית דנה\"א מצ\"ע, שהיא נהורא חיורא, האה\"ר דבחכ' שבנפשו, שזהו מצד התקשרות עצמי, ולזאת היתה התהוות חומר הנבראי' במאמר ודיבור, בכדי שיהי' יש ומציאות, ויהי' ענין העבודה בביטול היש לאין.\nכו) <b>והנה</b> דוגמת בחי' חומר וצורה שבנבראי' דבי\"ע, דחומר הוא גוף, וצורה הוא אור וחיות הנפש המתלבש בגוף להחיותו, יש בדוגמא כזאת גם באצי', דבאצי' יש ג\"כ בחי' חומר וצורה, דאצי' הוא ג\"כ עולם, ויש בו ג\"כ בחי' חומר וצורה גוף ונפש, והן בחי' או\"כ דאצי' שנק' ג\"כ בשם חומר וצורה, דאור הוא צורה, וכלי הוא חומר, דכן הוא בעולם האצי' דאורות דאצי' הוא צורת עולם האצי', והכלים דאצי' הוא החומר דעולם האצי', והיינו דשרש חומר וצורה דנבראים דבי\"ע הוא מבחי' חומר וצורה דעולם האצי' שהן האו\"כ דאצי'<sup data-n=\"311\">311</sup>, וכמאמר דפתח אלי'<sup data-n=\"312\">312</sup> וכמה גופין תקינת לון דאתקריאו גופין לגבי לבושין דמכסין עליהון כו', ואחר שמפרט ומפרש סדרם וענינם אומר וההוא נביעו איהו כנשמתא לגופא דאיהו חיים לגופא. הנה וכמה גופין תקינת לון קאי על הכלים דאצי' שנקראים בשם גופים, והגם דזה שנקראי' בשם גופים הוא לגבי הלבושים שמכסים עליהם, ומ\"מ ה\"ה בבחי' גופים שהם בחי' חומר דאצי', והיינו דכמו שבנבראי' דבי\"ע הרי חומר הוא גוף הנבראי', הנה דוגמתו בעולם האצי' הם בחי' הכלים שהם בחי' החומר דעולם האצי', וההוא נביעו איהו כנשמתא לגופא קאי על גילוי הקו, דאיהו חיים לגופא קאי על האורות דאצי', שהם הנמשכים ומתגלי' להאיר את הכלים דאצי' ולהחיותם, דזהו מה שהאורות דאצי' הם בחי' צורת האצי', דכשם שבנבראי' דבי\"ע הנה האור והחיות שמתלבש בהנבראים בגוף שהוא חומר, הוא הנפש שהוא צורת הנבראי', הנה כמו\"כ",[["311","311","וכמ\"ש בסי' בד\"ה להבין ההפרש בין ק\"ש לתפלה [עג, ג ואילך] - ספר המאמרים עת\"ר שבהערה 1."],["312","312","תקו\"ז בהקדמה (יז, א)."]]],[2700520159,"הוא בעולם האצי', דאורות דאצי' המתלבשים בכלים דאצי', דזהו חומר האצי', הם צורת האצי'. והנה טעם הדבר מה דכלים דאצי' נקראים בשם חומר, הוא לפי דשרש ומקור התהוות הכלים, הוא ע\"י הצמצום והסתלקו' האור שנכלל בהמאור<sup data-n=\"313\">313</sup>, ונשאר רק בחי' רשימו בלבד<sup data-n=\"314\">314</sup>, והיינו כי הרשימו שנשארה במקום החלל ומקום פנוי מהאור הקודם, הנה ע\"י הצמצום זהו בחי' שרש ומקור הכלים, וכדאי' בע\"ח (היכל א\"ק דרוש עגו\"י ענף ב') דע כי טרם שנאצלו הנאצלים ונבראו הנבראי', הי' אור עליון פשוט ממלא כל המציאות, ולא הי' שום מקום פנוי בבחי' אויר ריקני וחלל, אלא הכל הי' ממולא מן אור א\"ס פשוט ההוא, ולא הי' לו<sup data-n=\"315\">315</sup> בחי' ראש ולא בחי' סוף, אלא הכל הי' אור א' פשוט שוה בהשואה א', והוא הנק' אור א\"ס, והיינו שבמקום החלל הי' מאיר גילוי אוא\"ס ב\"ה הבל\"ג, שהוא אור א' פשוט שוה בהשואה א', שהאור הוא מעין המאור<sup data-n=\"316\">316</sup>, שהוא בבחי' א\"ס ממש, דהגם שהוא בחי' אור וזיו המתפשט בלבד, שעש\"ז נק' בשם אור להורות שהוא בחי' הארה לבד לא בחי' העצמות, וכמו שדייק הרמ\"ז<sup data-n=\"317\">317</sup> בלשון הע\"ח (הנ\"ל) שאמר ואז צמצם את עצמו א\"ס בנקודה האמצעית אשר בו באמצע אורו ממש, ודייק אורו לאפוקי עצמותו, והוא כדרך הנשמה שאינה מחזקת מקום, רק אורה מתפשטת בכל הגוף להחיותו, כך כל הדברים האלו הם באור המתפשט מעצמותו, והיינו כמו אור<sup data-n=\"318\">318</sup> וזיו השמש שהיא הארה מתפשטת מהשמש, או אור וחיות הנפש, שזהו רק הארה מתפשטת מהנפש, מ\"מ הרי אומר שהוא אור א' פשוט שוה בהשואה א', היינו שהאור הוא מעין המאור, וכמו אור וחיות הנפש הרי גם כללות התפשטותו בגוף, ה\"ה בבחי' כח כללי לבד. דהנה<sup data-n=\"e49\">*</sup> זה מה שהכחות שהם אברי הנפש מתלבשי' באברי הגוף להחיותם, הרי תחלה הוא התפשטות אור וחיות הנפש בבחי' אור כללי להחיות, דאור זה הוא כללי והוא בבחי' גילוי מהנפש להחיות, והגם שהוא רק התפשטות וגילוי העצמות לבד, אבל מ\"מ ה\"ה דומה אל העצמות באופן זה מה שאינו בא באיזה אור ושפע פרטיות מיוחדת, אלא כולל הכל, היינו כל המיני חיות שבאברי הגוף, דכולם הם בהשואה גמורה. וכמו\"כ יובן הדוגמא מזה באור א\"ס שהוא בחי' אור כללי, ואינו שייך לפרטים כלל, והיינו שאינו ניכר בו עדיין בחי' התחלקות אורות מיוחדים. והנה הגם",[["313","313","ראה עץ חיים שער א (דרוש עגולים ויושר) סוף ענף ג. המשך תער\"ב ח\"א ע' יג ואילך. ובכ\"מ."],["314","314","ראה לקו\"ת הוספות לויקרא נד, א. סידור עם דא\"ח קסה, ד ואילך."],["315","315","בספר המאמרים ה'שי\"ת שבהערה :1 ולא הי' לו לא."],["316","316","ראה תניא אגה\"ק ס\"כ (קל, סע\"א ואילך). ספר המאמרים תרנ\"ו ע' רנו. המשך תרס\"ו ע' קסח. ובכ\"מ."],["317","317","הובא בהגהות וביאורים לעץ חיים שם."],["318","318","בספר המאמרים ה'שי\"ת שבהערה :1 באור."],["e49","*","<b>דהנה זה:</b> עדכ\"ז בארוכה ראה ד\"ה אשרנו ש\"ת (בספר המאמרים ת\"ש - תש\"ב. נמצא בדפוס [נדפס לאח\"ז בספר המאמרים ה'ש\"ת ע' 31 ואילך])."]]],[2700520209,"דלהבין ענין זה במקצת עכ\"פ שהאור הוא אור כללי, הנה אומרים ע\"ז המשל מגילוי הנפש להחיות שהוא התפשטות כללי, הנה עם זה יובן דאינו דומה כלל זה מה שגילוי הנפש להחיות הוא כללי, לזה דהאור הוא כללי, והיינו דאין המשל דומה לנמשל, דגילוי הנפש באור וחיות להחיות, עם היות שהוא כולל הכל, ומ\"מ<sup data-n=\"319\">319</sup> הרי אינו מושלל מהכחות, אלא אדרבא הוא כמו כלל אל פרטי הכחות, דאין בכלל אלא מה שבפרט, והיינו שהכחות ישנם שם בבחי' כללות עכ\"פ, דהדוגמא מזה בעולמות ופרצופים עליונים, הוא רק במדרי' שאחר הצמצום, כמו פרצוף א\"ק שנק'<sup data-n=\"e50\">*</sup> אור כללי, או בחי' עקודים שהכל כלול, דזהו פי' עקודים שעקוד בכלי אחד<sup data-n=\"320\">320</sup>, אבל אור א\"ס שלפני הצמצום אינו בגדר וענין זה שהוא כלל, והיינו שיהי' בגדר לאמר עליו שהוא בבחי' כלל לאורות פרטיים<sup data-n=\"321\">321</sup>. ובאמת הנה בעומק ההבנה במקום שמתבאר הענין דפרצופים העליונים בפרטיות, הרי גם בפרצופי א\"ק ועקודים אינו שייך עדיין ענין כלל ופרט, וכמו שהכחות<sup data-n=\"e51\">*</sup> ההיולים העצמיים שמושללים לגמרי ואינם בגדר בחי' כלל ופרט, וכידוע דכח ההיולי והגילוי' המתגלי' ממנו אינו בבחי' כלל ופרט, כי ההיולי הוא מושלל מהגילוים, ובפרט כמו שהוא בהכחות ההיולים העצמיים שמושללים<sup data-n=\"322\">322</sup> לגמרי מגדרי הגילוים, אך עכ\"פ יובן מזה ענין השלילה, והיינו איך דאוא\"ס שלפני הצמצום אינו בחי' כלל לאורות פרטיים, שהרי גם במדרי' שלאחר הצמצום, וכמו א\"ק וגם למטה מא\"ק, ה\"ה בחי' אורות כללים, וכ\"ש דהאור א\"ס שלפני הצמצום אין שם התחלקות אורות פרטיים.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דגם באצי' יש חומר וצורה, אורות וכלים, ויבאר ענין הרשימו שנשאר אחר שהאור הבל\"ג נכלל בהמאור, והגם שהאור הבל\"ג הוא אור ולא עצמות, ומ\"מ הוא מעין המאור, ודוגמא לדבר החיות כללי שבנפש, ומסביר כי אין המשל דחיות כללי דומה להאור הבל\"ג, וראי' מהפרצופים שאחר הצמצום<sup data-n=\"323\">323</sup>.</span>\n<b>ענינים.</b> א צורה וחומר דאצי', אורות וכלים. ב שרש הכלים מרשימו. ג האור שלפני הצמצום אינו עצמות. ד החיות כללי אינו מושלל מהכחות.",[["319","319","בספר המאמרים ה'שי\"ת שבהערה :1 מ\"מ."],["320","320","ראה עץ חיים שער ו (שער העקודים) פ\"א. מאמרי אדמו\"ר הזקן פרשיות ח\"א ע' סד ואילך. תורת חיים נח סה, ד ואילך. ובכ\"מ."],["321","321","ראה ד\"ה בראשית ברא שנה זו (לקמן ע' צז ואילך)."],["322","322","בספר המאמרים ה'שי\"ת שבהערה :1 מושללים."],["323","323","הקיצור דשנת ה'שי\"ת: או\"כ דאצילות נק' חומר וצורה. הכלים נק' חומר כי שרש התהוותם מהרשימו. יבאר דאוא\"ס שלפה\"צ הוא פשוט ואינו בגדר כלל לפרט."],["e50","*","<b>פרצוף א\"ק שנק':</b> כך קראו הרב המגיד ז\"ל (סהמ\"צ להצ\"צ מצות האמנת אלקות פי\"א [נח, ב])."],["e51","*","<b>וכמו שהכחות:</b> ראה תו\"א ותו\"ח ס\"פ נח [תו\"א י, ג ואילך. תו\"ח סז, ב ואילך]. ד\"ה ויגדלו הנערים תרס\"ה [ספר המאמרים תרס\"ה ע' צה ואילך]. ד\"ה וספרתם לכם, קדש ישראל בהמשך תרס\"ו [ע' ריב ואילך. ע' תקיא ואילך]. ועוד."]]],[2700520259,"כז) <b>אמנם</b> צ\"ל והלא עלה ברצונו ית' להאציל ולברוא העולמות, ומבואר בע\"ח<sup data-n=\"324\">324</sup> שזה הי' לפני הצמצום, וכמאמר הזהר<sup data-n=\"325\">325</sup> בריש הורמניתא<sup data-n=\"326\">326</sup> דמלכא, ומבואר במ\"א<sup data-n=\"327\">327</sup> שזהו בחי' התעוררות הרצון כבי' על בריאת והתהוות העולמות, א\"כ הרי בעליית רצון זה שהוא באוא\"ס שלפני הצמצום כאלו יש בחי' מדריגות אורות פרטיים. אך הענין הוא דהנה ידוע<sup data-n=\"e52\">*</sup> שיש רצון הנק' רצון המוחלט, דהיינו שמוחלט בהחלטה עצמיות מצד העצמיות גופא ולא שנתעורר בזה והוחלט כך כ\"א שהוא מוחלט בעצם<sup data-n=\"328\">328</sup>, ויש רצון שבא בהתעוררות, והיינו שמתעורר באיזה רצון כמו בבנין איזה בית וכה\"ג, דרצון זה הרי יש בו בהעלם פרטי הדבר איך ומה יהי' הדבר ההוא שהתעורר ברצונו אליו, דמאחר שנתעורר בהרצון הרי בהכרח שיש בו בהעלם איזה ציור אשר בו הוא רוצה. והדוגמא מזה למעלה הוא בבחי' עליית הרצון שעלה ברצונו ית' להאציל, שזהו בחי' התעוררות רצון כבי' שנתעורר ברצונו ית' להאציל ולברוא כו', ושיער בעצמו בכח כל מה שיהי' לפועל<sup data-n=\"329\">329</sup>. וביאור הענין הוא דהנה בהתעוררות הרצון גופא הרי יש ג\"כ ב' מדרי', והם רצון נעלם ורצון גלוי, דרצון נעלם הוא שהרצון הוא בהעלם בעצמותו כבי' ואינו עדיין בבחי' מח' ורצון כלל, והיינו שנאמר אשר רצון זה יהי' כלל אל מדרי' האורות פרטיים שאחר הצמצום, ורצון זה נק' רצון פשוט להיותו בבחי' פשיטות ממש, דהגם שזהו בחי' התעוררות כבי' וממילא הרי עלה הכל בהעלם, מ\"מ הרי הכל הוא בבחי' פשיטות ממש שאינו בגדר להקרא בשם אור כללי, ולכן הרי כללות הרצון הזה נק' רצון נעלם שהוא בהעלם בעצמותו, והב' הוא רצון גלוי שהוא בבחי' אור כללי כמו כלל ופרט. ויובן זה עד\"מ באדם שנתעורר בעצמו ברצון באיזה דבר, כמו בנין בית וכה\"ג, והוחלט אצלו הרצון, אבל החלטה זה אין זה לפועל עדיין, ואינו אלא מה שנתעורר בעצם הדבר לרצות בו והתעוררות זו הביאה החלטה, והוא מה שהוחלט אצלו לרצות בזה שנתעורר, אבל לא לעשות הדבר בפועל, א\"כ מובן דהרצון הזה אינו שייך עדיין אל הפועל ובאמת הנה לא זו בלבד שאינו שייך אל הפועל הרי אינו גם רצון כללי אליו, מאחר שאין שום התעוררות עדיין על פועל הדבר, ועם היות",[["324","324","ענף ב שם."],["325","325","ח\"א טו, א."],["326","326","בזהר שלפנינו: הורמנותא."],["327","327","ראה ספר המאמרים תרנ\"ו שבהערה הבאה. תרס\"ה ע' ע' ד ואילך. תש\"ג ע' 14 ואילך. מקומות שצויינו בהערה ד\"ה \"דהנה ידוע\"."],["328","328","וכמ\"ש מזה בד\"ה ועשית ח\"ש רנ\"ו [ספר המאמרים תרנ\"ו ע' שסה ואילך] - ספר המאמרים עת\"ר שבהערה 1."],["329","329","ראה עץ חיים שם ענף א' בתחילתו. מק\"מ לזח\"א טו, א. מאמרי אדמו\"ר הזקן תקס\"ח ח\"א ע' שכד ואילך. שער היחוד לאדמו\"ר האמצעי פ\"י ואילך. ועוד."],["e52","*","<b>דהנה ידוע:</b> ראה שער היחוד פ\"י ואילך [קטז, ב ואילך]. עטרת ראש [שער ר\"ה] פ\"ו ואילך [ו, ב ואילך]. ובכ\"מ."]]],[2700520309,"שנתעורר ברצון על עצם הדבר מ\"מ הרי הוא מרוחק עדיין מן הפועל כמו שהי' מרוחק ממנו קודם שנתעורר בהרצון, והיינו שהוא בנפש בלי התפעלות עדיין, וזהו מה שנק' רצון הנעלם, מה שנשאר בהעלם בעצמו, אבל כאשר נתעורר ברצון לפעול הדבר ההוא בפועל, הרי מתקרב אל הפועל ע\"י הרצון ואז הנה רצון זה הוא רצון גלוי לעצמו ורצון כללי אל הפועל, והנה הרצון הגלוי הזה הגם שסיבתו הוא הרצון הנעלם, דהנה זה מה שנתעורר עתה לפעול הוא מפני שכבר נתעורר ברצון נעלם בעצם הדבר, מ\"מ הנה הרצון הנעלם הוא בבחי' סיבה לבד, והיינו דהתגלות הרצון הגלוי אינו ע\"י גילוי הרצון הנעלם בעצמו, והיינו דהרצון הגלוי אין זה התגלות הרצון הנעלם, להיות דגם לאחר שנתעורר בהרצון הגלוי הרי הרצון הנעלם נשאר בהעלמו וסתימתו, והוא מובדל בערך ממנו<sup data-n=\"330\">330</sup>. והדוגמא מזה למעלה הוא בהב' מדרי' דטהירא עילאה וטהירא תתאה<sup data-n=\"e53\">*</sup>, דטה\"ת הוא בחי' מחשבה הקדומה דא\"ק שאחר הצמצום, שזהו כדוגמת בחי' הרצון הכללי הנ\"ל, ובחי' טה\"ע הוא בחי' עליית הרצון שעלה ברצונו הפשוט באוא\"ס שלפני הצמצום ושיער בעצמו בכח, דעם היות שזהו בחי' התעוררות הרצון כבי', אבל הוא בהעלם בעצמותו כבי' ואינו שייך כלל לפועל העולמות, להיות כי כללות האור הזה אינו בגדר ובערך העולמות כלל, דבכללותו הוא אור הכלול בעצמותו, וכל מה שבאור זה הכל מתאחד בעצמותו ית', ואינו בבחי' שייכות כלל אל פועל העולמות, והנה ענין הרצון בכלל הוא בבחי' הבדלה, היינו שאינו בבחי' התפעלות בהדבר שרוצה להיות נתפס בו, וא\"כ בחי' הרצון שאינו שייך אל הפועל, הגם שהוא הרצון ע\"ז אבל לא השייך לפועל ודאי שהוא בבחי' הבדלה לגמרי. וממילא מובן דבהאור א\"ס שלפני הצמצום הגם שעלה ברצונו הפשוט כו', מ\"מ אין שם כלל בחי' התחלקות אורות פרטיים ומיוחדים, וא\"כ הרי מאור זה הי' נאצל ספירות ומדות עד אין קץ ושיעור, וגם הי' נמצא מאתו מציאות אורות וכחות שאינם במציאות ומהות סדר האצי' דוקא, אלא מציאו' ומהות אחר ברבוא רבבות אופנים שונים, ולא במדה וגבול במציאות האצי' בע\"ס דוקא. והגם דלכאו' הרי אם הי' באופן כזה שאינו במציאות ומהות עולם האצי', הרי אז הי' זה לא כפי מה שעלה ברצונו ית', אך הענין הוא דלהיות שהרצון אינו בבחי' שייך לפועל ובבחי' הבדלה לגמרי, לזאת הנה אין הרצון מכריח שיהי' כפי הרצון דוקא, ומצד בחי' הא\"ס שבו שאינו ניכר שם התחלקות אורות כלל, הנה משו\"ז הי' ההתהוות בבחי' בל\"ג, דהרי כללות הגילוי שלפני הצמצום הוא האוא\"ס הבל\"ג, א\"כ הרי מאור זה הי' ההתהוות בל\"ג, היינו ריבוי ספירות עד אין קץ ושיעור ובאופנים אחרים לגמרי, ולפ\"ז לא הי'",[["330","330","ועמ\"ש בזה באורך בדרוש יו\"ט של ר\"ה רס\"ו בד\"ה אדם כי יהי' [המשך תרס\"ו ע' קצז ואילך] - ספר המאמרים עת\"ר שבהערה 1."],["e53","*","<b>דטהירא עילאה וטהירא תתאה:</b> ראה ג\"כ שער היחוד פט\"ז [קכא, סע\"א ואילך]. אמרי בינה שער הק\"ש פ\"י ואילך [כא, ד ואילך]. תו\"ח פ' נח ד\"ה ויהי כל הארץ פכ\"ג ואילך [סט, א ואילך]. ד\"ה אדם כי יהי' תרס\"ו [המשך תרס\"ו ע' קצט ואילך]. ועוד."]]],[2700520359,"השתלשלות דאבי\"ע, היינו שלא הי' באופן מהות ומציאות שהן עתה, ולא הי' בהם מעו\"מ, שהי' הכל שוה<sup data-n=\"331\">331</sup>, ואור זה הי' ממלא כל החלל בבחי' השפעה וגילוי, ולזאת הוצרך המאציל העליון ב\"ה לצמצם אור זה בבחי' צמצום והסתלקות בעצמותו, והוא מה שהאור נכלל בהמאור, והוא הנק' מקום פנוי, ויומשך אור שבבחי' הארה לבד שיהי' בערך להיות בחי' מקור לעולמות, ומ\"מ נמשך בעולמות גם בחי' אורות מקיפים, שזהו גילוי בחי' אור עצמי שלמעלה מבחי' התלבשות בעולמות.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר כי יש רצון המוחלט ורצון הבא בהתעוררות, שבהכרח יש בהעלמו ציור מה הוא רוצה, ובו, א) רצון נעלם ופשוט, ב) גלוי כמו כולל, והמשל מבנין בית, א) מוחלט, בלי פועל, ב) נעלם, ג) גלוי כללי, ומסביר כי הנעלם הוא רק סיבה להגלוי, והדוגמא למעלה טה\"ע וטה\"ת<sup data-n=\"332\">332</sup>.</span>\n<b>ענינים.</b> ה רצון, א) מוחלט, ב) נעלם, ג) גלוי. ו רצון הנעלם הוא רק סיבה להגלוי. ז רצון אינו נתפס במה שרוצה. ח טהירו עילאה רצון הנעלם. ט טהירו תתאה רצון כללי.\nכח) <b>והנה</b> כוונת המאציל ב\"ה בענין הצמצום א\"א לומר שהכוונה הוא בבחי' סילוק האור ח\"ו, כי איזה תכלית יש בבחי' העדר האור והגילוי, והרי במדרי' שלאחר הצמצום כתי'<sup data-n=\"333\">333</sup> לא לתוהו בראה כי לשבת יצרה, דעולם התוהו שהי' בחי' סילוק האור, אין זה כפי הכוונה האמיתית, כ\"א הכוונה האמיתית היא בבחי' התיקון דלשבת יצרה בבחי' גילוי אור, וא\"כ א\"א לומר דכוונת הצמצום הוא שיהי' סילוק האור ח\"ו, אלא דכוונת הצמצום הוא שהאור הזה יבוא אח\"כ במדה וגבול, והוא ע\"י בחי' הרשימו שנשאר בחלל זה לאחר הצמצום. וענין הרשימו היינו בחי' כח הגבול שבא\"ס, כי הוא ית' כל יכול ויש בו גם כח הגבול, וכמ\"ש העה\"ק ש\"א פ\"ח<sup data-n=\"334\">334</sup> דא\"ס הוא שלימות מבלי חסרון ח\"ו, וא\"ת שיש לו כח בל\"ג ואין לו כח בגבול אתה מחסר שלימותו, אלא כשם שיש לו כח הבבע\"ג, כן יש לו כח הגבול כו', ושם כ' זה לענין הספירות שהן בחי' כח הבל\"ג וכח הגבול, שהכוונה הוא על או\"כ דאצי', ומכ\"ש שהוא כן באוא\"ס עצומ\"ה שיש בו גם כח הגבול, וזהו בחינת הרשימו שזהו ע\"ד בחי' אותיות, וכמא'|69 גליף גליפא בטה\"ע, דפי' גליפא ל' חקיקה<sup data-n=\"335\">335</sup>, והיינו חקיקת האותיות שבאוא\"ס שלפני הצמצום, ונק' בשם חקיקה להורות על העדר",[["331","331","עמ\"ש במב\"ש [ במבוא שערים] ש\"א פ\"ב - ספר המאמרים עת\"ר שבהערה 1."],["332","332","הקיצור דשנת ה'שי\"ת: יבאר דיש רצון המוחלט, או ע\"י התעוררות ובזה ב' מדרי' רצון נעלם והוא פשוט או גלוי והוא כללי, הדוגמא למעלה טה\"ע וטה\"ת. רצון הנעלם אינו שייך לפועל ולכן הי' ההתהוות באו\"א, ולזה הוצרך הצמצום."],["333","333","ישעי' מה, יח (בשינוי)."],["334","334","העבודת הקודש שער א פרק ח."],["335","335","דרך אמת לזח\"א שם. וראה לקו\"ת חוקת נט, ג. מאמרי אדמו\"ר הזקן תקס\"ה ח\"ב ע' תרפט ואילך. ועוד."]]],[2700520406,"המציאות, וכידוע בההפרש<sup data-n=\"e54\">*</sup> שבין אותיו' החקיקה לאותיות הכתיבה, דאותיות הכתב הרי יש דבר נוסף על הקלף, והיינו בחי' מציאות דבר, ולמעלה היינו בחי' כלים דאצי' שהן בבחי' מציאות דבר, וכן בד\"כ הכלים בכל מדריגה שנדבר ה\"ה בבחי' מציאות, ומהאי טעמא נק' א\"ק אדם דבריאה דכללות<sup data-n=\"336\">336</sup>, אמנם אותיות החקיקה אינם בבחי' מציאות דבר, והיינו בחי' האותיות שבאוא\"ס שלפני הצמצום שאינם בבחי' מציאות, וכמו עד\"מ אותיו' שבעצם הנפש, שהנפש מלאה אותיות<sup data-n=\"337\">337</sup>, ואינם בבחי' מציאות כלל. ובאמת הרי באותיו' החקיקה יש ג\"כ ב' מיני חקיקה<sup data-n=\"338\">338</sup>, וכמו החקיקה על האב\"ט שהגם שאין כאן אותיו' בבחי' מציאות, היינו שיהיו כדבר נוסף, מ\"מ הרי יש להאותיות אחיזה באיזה דבר, וא\"כ ה\"ה בבחי' איזה מציאות, ועם היות שהאחיזה שלהם הוא בגופו ומהותו של האב\"ט, והיינו שמציאותם הוא העצם ומהותו של האב\"ט, ולא איזה דבר זולתו, מ\"מ ה\"ה בבחי' איזה מציאות, שהרי האותיות משחירים במקום החקיקה שאין האב\"ט מבהיק כ\"כ במקום ההוא, וגם באפשר למלאות אותן בדיו כו', ויש חקיקה מעבר לעבר כמו האותיות שבלוחות<sup data-n=\"e55\">*</sup> שאין להם אחיזה כלל, והיינו שאינם בבחי' מציאות כלל גם לא באופן הנ\"ל שהעצם הוא מציאותם, ואינם אלא אותיות בלבד, וא\"א כלל למלאות אותן כו'. והמשל דחקיקה על אב\"ט הוא על בחי' הכלים דא\"ק|336, בחי' טה\"ת, דהגם שהן רק בחי' שרש נשמות דגופות|336, מ\"מ יש להם אחיזה שהן עכ\"פ בחי' איזה מציאות, דהרי העדר המציאות דכלים דא\"ק אינו כ\"כ מצ\"ע, כ\"א מצד האור והגילוי<sup data-n=\"339\">339</sup>, והגם שמציאותם הוא רק בחי' האור בעצמו לא כמו דבר נוסף, דגם בחכ' הכלי נק' חיוהי כנודע<sup data-n=\"e56\">*</sup>, ובת\"ת גם הכלי<sup data-n=\"e57\">*</sup> שם הוי' כו', ומכ\"ש בבחי' א\"ק, מ\"מ הנה לאחר כל ההפלאה וההפשטה ה\"ה בבחי' מציאות דבר, וגם אפשר למלאותם, היינו שהם בבחי' מקור עכ\"פ לכלים דאצי', וזהו שהן שרש נשמות דגופות. והחקיקה מעבר לעבר הוא משל על בחי' האותיות דטה\"ע שלפני הצמצום|336, שהן בבחי' העדר המציאות לגמרי, וא\"א למלאותם בדיו, היינו שאינם בגדר מקור כלל, ומ\"מ ה\"ז בחי' אותיות שנק'",[["336","336","ראה לקמן פרק לח (לקמן ע' צז)."],["337","337","לקו\"ת בחוקותי מה, ד. שה\"ש ד, ב. ספר המאמרים תרצ\"ו ע' 110. וש\"נ."],["338","338","מאמרי אדמו\"ר הזקן שם ע' תרצ. המשך תרס\"ו ותער\"ב שבהערה ד\"ה \"וכידוע בההפרש\". וראה גם לקוטי שיחות חלק ח ע' 127 ואילך. ד\"ה וידבר ה' גו' זאת חוקת התורה תשמ\"ה. ועוד."],["339","339","וכמ\"ש מזה בדרוש יו\"ט של ר\"ה הנ\"ל [המשך תרס\"ו ע' רו]. - ספר המאמרים עת\"ר שבהערה 1. וראה גם המשך תער\"ב ח\"א ע' טז ואילך. ד\"ה מה רבו מעשיך תרמ\"ד פרק ה (ספר המאמרים תרמ\"ד (קה\"ת, תשס\"ב) ע' שכ ואילך)."],["e54","*","<b>וכידוע בההפרש:</b> ראה לקו\"ת ר\"פ בחוקותי [מה, א]. ד\"ה פב\"פ, וד\"ה אין עומדין תרס\"ז [המשך תרס\"ו ע' תעג ואילך. ע' תעו ואילך]. ד\"ה נשא רדע\"ת [המשך תער\"ב ח\"א ע' תק]."],["e55","*","<b>האותיות שבלוחות:</b> שהיו מעבר לעבר כמרז\"ל (שבת קד, א) מ\"ם וסמ\"ך שבלוחות בנס היו עומדין."],["e56","*","<b>נק' חיוהי כנודע:</b> ראה ד\"ה כימי צאתך תש\"ח (קונטרס נו) פ\"ט [ספר המאמרים תש\"ח ע' 163]."],["e57","*","<b>ובתפארת גם הכלי:</b> ראה תו\"א ותו\"ח פ' נח רד\"ה הן עם אחד [תו\"א י, ב ואילך. תו\"ח סד, ג]."]]],[2700520453,"כח הגבול שבא\"ס, ולפני הצמצום הי' האוא\"ס הבל\"ג מאיר בגילוי בהאותיות<sup data-n=\"340\">340</sup>, והכח הגבול הי' בהעלם, וע\"י שנתצמצם האור נתגלה כח הגבול, שזהו פי' רשימו, היינו שזהו בחי' רשימו מהאוא\"ס שלפני הצמצום שנשאר אחר הצמצום, שהרי זהו בחי' כח הגבול שבא\"ס, שהוא א\"ס ממש כמו הכח הבל\"ג<sup data-n=\"341\">341</sup>, אלא דזה כחו ית' בבחי' בל\"ג, וזה כחו ית' בבחי' גבול.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דכוונת הצמצום הוא בשביל שהבל\"ג יבוא במדה וגבול, והוא ע\"י הרשימו, שהוא כח הגבול שבא\"ס, ואותיות שלפני הצמצום, ונק' גליפו חקיקה, ויסביר ב' אופני חקיקה, א) אחוזים במהות העצם שאפשר למלאותם, טה\"ת כלים דא\"ק, ב) מעבר לעבר, אותיות, ואי אפשר למלאותם, טה\"ע<sup data-n=\"342\">342</sup>.</span>\n<b>ענינים.</b> י רשימו, א) כח הגבול שבא\"ס, ב) אותיות שלפני הצמצום, ג) טה\"ע, ד) מביא הבל\"ג בהגבלה. יא גליפו חקיקה. יב חקיקה, א) בהעצם, ב) טה\"ת, ג) מעבר לעבר, ד) טה\"ע.\nכט) <b>אמנם</b> לפ\"ז דכח הגבול שבא\"ס הוא בל\"ג כמו כח הבל\"ג, והוא האותיות דאוא\"ס שלפני הצמצום שבהם האיר אוא\"ס הבל\"ג, א\"כ למה נק' רשימו לבד. אך הענין הוא דהנה תנועה הכללית הלזו, מה שהתצמצם והתעלם האור הבל\"ג, ונתגלה כח הגבול, הוא התחלת הנטי' בהשייך אל ההגדרה דגילוים, פי' גילוים כאן הכוונה היינו המדרי' שאחר הצמצום, הנה בגילוים הרי מדרי' הגבול הוא באין ערוך לגבי בלי גבול, דהבל\"ג הוא בחי' גילוי אור שבל\"ג, דענין הגילוי בעצם הוא בבחי' בל\"ג, ולכן הכינוי שלו הוא שם גילוי שמורה על אור המאיר אַ אור ואָס לייכט, הרי בשעה שמאיר אין נרגש הגבלתו וכאלו אינו כי ההגבלה שבהאור הרי אינו מצ\"ע, כי בעת שמאיר הוא כמו בל\"ג, אלא שהגבלתו הוא ע\"י דבר המגביל אותו, וגבול הוא העלם, ולכן הרי הכינוי של הגבול הוא חשך, דפירושו מניעה, וכמ\"ש (בראשית כ\"ב י\"ב) ולא חשכת את בנך ממני, דפירושו ולא מנעת, דזהו\"ע הגבול שהוא מונע ומעכב את ההתפשטות הבלי גבולי ומכריחו שיהי' במדה וגבול, ונותן מדה ושיעור בכל דבר עד כמה יהי' התפשטותו, וכמ\"ש (תלים ק\"ד ט') גבול שמת בל יעברון, ולזאת הנה כח הגבול שבא\"ס עם היות שזהו כח הא\"ס, מ\"מ ה\"ז כח נעלם, ומהאי טעמא נק' בשם רשימו לבד, שהוא בחי' כח נעלם<sup data-n=\"343\">343</sup>, ולכן המשל בכחות הנפש על ענין הרשימו, הוא מכח הזריקה<sup data-n=\"344\">344</sup> שהוא כח נעלם ונבדל מן האדם, וכמו עד\"מ הזורק אבן מלמטלמ\"ע הרי הכח היד הוא הנושא את האבן",[["340","340","ראה לקו\"ת הוספות לויקרא נב, ד ואילך. ועוד."],["341","341","ראה גם ספר המאמרים תרכ\"ט ע' קסג. ובכ\"מ."],["342","342","הקיצור דשנת ה'שי\"ת: כוונת הצמצום בשביל הגילוי בגבול. רשימו הוא ע\"ד אותיות. ויבאר אותיות הכתיבה ואותיות החקיקה על האב\"ט או מעבר לעבר. והנמשל למעלה כלים דאצי', דא\"ק טה\"ת, דטה\"ע."],["343","343","וכמ\"ש בהוספות לקו\"ת בד\"ה להבין מ\"ש באוצ\"ח [נד, א] - ספר המאמרים עת\"ר שבהערה 1."],["344","344","ראה שער היחוד לאדמו\"ר האמצעי פי\"ב ואילך. ד\"ה כבוד מלכותך תרס\"א (ספר המאמרים תרס\"א ס\"ע קסז ואילך). ספר המאמרים תרח\"ץ ע' מא ואילך."]]],[2700520495,"למעלה, מ\"מ הרי כח זה נעשה נבדל מן עצמות כחו לגמרי, דזריקת האבן בא מכח היד, דכח זה הוא אחד מאופני הפעולה דפעולת כח התנועה, דהכח<sup data-n=\"345\">345</sup> התנועה ענינו להעתיק ולהסיע דבר ממקומו ולעשות איזה דבר בפועל מה שלא הי' קודם שעשה, ובגילוי כח זה הרי יש בו כמה אופנים שונים, כמו כתיבה ציור עשיית כלי עבודת משא וזריקת אבנים או צרורות, הנה הגם דהזריקה הוא רק אחד האופנים של גילוי כח התנועה, ומ\"מ ה\"ה חלוק משאר האופנים והפעולות דכח התנועה ואינו דומה כלל, וכמו המצייר או עושה איזה כלי הרי בעת הפעולה הרי הוא מחובר עם כח היד הפועל הציור או הכלי, וא\"כ הרי הכח הפועל הוא בו בגילוי בעת הפעולה עכ\"פ, משא\"כ בזריקה הגם שנמשך בזה ג\"כ כח היד, מ\"מ הרי בעת הפעולה הוא נבדל מן היד, ואדרבא בעת שהאבן בידו היינו בעת שהוא מכין א\"ע לזרוק, דאז הוא התחלת פעולת הזריקה לפי שאז ה\"ה מאסף כחו ומאצילו לנשוא את האבן, דכן אנו רואים במוחש דלפי אופן הכנתו באסיפת כחו לזרוק, הרי באופן כזה יהי' תוקף מרוצתו של האבן ומשך הילוכו בגובה, ומ\"מ הרי אז אינו נזרק, ובעת שנזרק ה\"ה נבדל ממנו, וא\"כ הרי כח ידו שבאבן אינו בא בגילוי ובקירוב אלא אדרבא בהעלם ובנבדל, דפירוש גילוי והעלם כאן שניהם הו\"ע השפעה, היינו השפעה נגלית והשפעה נעלמת, והיינו שההשפעה באה בקירוב ובגילוי או שבאה בריחוק ובהעלם. והנה בענין אור וכח מבו' דכח הוא שנראה ונגלה הכח הפועל, דכן הוא גם בזריקת אבן מלמטלמ\"ע היפך טבעו הרי נראה ונגלה בזה כח הזורק, שהרי בהכרח לומר שיש כאן כח הנושאו למעלה, ומ\"מ ה\"ז נעלם, והיינו שהיא השפעה נעלמת, ולכן ג\"כ אין הכח נרגש בהנפעל, מפני שפועל בו בבחי' כח נעלם, וכמו בסיבוב הגלגלים שיש להם שני סיבובים, סיבוב עצמי וסיבוב הכרחי, דהנה אי' ברמב\"ם (היסוה\"ת פ\"ג ה\"ט) כל הכוכבים והגלגלים כולן בעלי נפש ודיעה והשכל הם, והם חיים ועומדים ומכירין את מי שאמר והי' העולם. וסיבובם העצמי הוא ממערב למזרח, דסיבובם הוא עפ\"י רוחניות נפשם כאדם ההולך בבחירה ורצון, ויש להם סיבוב הכרחי שלא יסבו בלכתם בלי נטי', שזהו סיבובם ממזרח למערב לפי דשכינה במערב<sup data-n=\"e58\">*</sup>, וסיבוב זה אין זה מכח עצמם ולא מצד בחירתם, אלא שמוכרחי' הם בסיבובם מצד כח האלקי המלובש בהם בבחי' מקיף, שזהו בחי' כח נעלם המכריח אותם, והיינו להיות דשרשם הוא מבחי' האופנים, וכנ\"ל<sup data-n=\"346\">346</sup> דהמזלות מקבלים שפעם מן המזלות הרוחנים, והמזלות הרוחנים מקבלים שפע חיותם מן האופנים, והאופנים מחיות הקודש, וגבוה מעל גבוה שומר|205 עד שרשם הראשון כנ\"ל, לזאת הנה הביטול דאופנים ה\"ז מכריח הגלגלים בסיבובם, והיינו לפי שהוא כח נעלם לכן פועל בבחי' ההכרח לבד, וה\"ז כמו כח הזריקה שהוא כח נעלם, ולכן הנה עם היות שהוא אחד",[["345","345","בספר המאמרים ה'שי\"ת שבהערה :1 דכח."],["346","346","פרק יט-כ (לעיל ע' מב ואילך)."],["e58","*","<b>לפי דשכינה במערב:</b> ב\"ב כה, א."]]],[2700520531,"מאופני הכחות שבכח התנועה, ומ\"מ הרי אינו דומה כלל לכל אופני הפעולה דכח התנועה, לפי דזריקה הוא כח נבדל בעצם יותר מהכחות שבשארי הפעולות, דהגם דכולם באי' בדברים נבדלים, מ\"מ הרי ענינם הוא להיות הפעולה בקירוב וחיבור עם כח היד, וכח הזריקה ענינו הוא להיות בריחוק וכח נבדל דוקא. והנמשל בזה הוא בבחי' הרשימו שזהו בבחי' כח נעלם, היינו בחי' כח נבדל מן העצמות ובזה יובן מ\"ש בפדר\"א<sup data-n=\"e59\">*</sup> נטל צרורות וזרקן ומהם נעשה הארץ, דהמשל הוא מזריקה שהוא כח נבדל, כמו\"כ ענין הרשימו שזהו<sup data-n=\"347\">347</sup> בחי' כח הגבול שבא\"ס ה\"ז בחי' כח נבדל כבי' מן העצמות, דהרי בחי' הגילוי דאוא\"ס הוא בבחי' בלי גבול, וענין כח הגבול הוא בבחי' כח נעלם ונבדל דוקא.\n<span data-k=\"ks\"><b>קיצור.</b> יקשה דמאחר שכח הגבול שבא\"ס הוא בל\"ג למה נק' רשימו, ויתרץ שזהו התחלת הנטי' אל ענין ההגדרה, ויבאר דענין תואר ושם גילוי מורה על שהאור מצ\"ע הוא בלי גבול, והתואר ושם גבול מורה על המניעה, ולכן המשל ברשימו הוא מכח הזריקה, ויסביר ענין השפעה גלוי' והשפעה נעלמת, ויטעים מענין זריקת אבן וסיבוב הכרחי<sup data-n=\"348\">348</sup>.</span>\n<b>ענינים.</b> יג רשימו התחלת ההגדרה. יד זריקה, א) כח נעלם, ב) נפרד.\nל) <b>והנה</b> אחר שנתגלה בחי' הגבול שבא\"ס שזהו בחי' הרשימו, ה\"ז מגביל גם את האוא\"ס הבל\"ג, והיינו שהאור שנתצמצם ונתעלם, שזהו בחי' האור הבל\"ג, ה\"ה בא בבחי' גבול ע\"י הרשימו. והכוונה בזה להיות שענין הצמצום הי' שיתגלה בחי' כח הגבול, לזאת כמו שקודם הצמצום כשהי' התגלות בחי' אוא\"ס הבל\"ג הרי הי' התגברות האור הזה על בחי' כח הגבול, שלא הי' ניכר כלל והי' הכל בבחי' א\"ס, וכמ\"ש בע\"ח שהי' אור עליון פשוט ממלא כל המציאות ולא הי' בו מעלה ומטה וראש וסוף, הרי שבמקום החלל הי' רק גילוי בחי' אוא\"ס הבלי גבול, כמו\"כ הוא לאחר הצמצום שהי' רצונו ית' שיהי' התגלות בחי' כח הגבול ה\"ז בחי' התגברות הכח הגבול להגביל בחי' האוא\"ס הבל\"ג, וזהו שנקרא בשם רשימו, שהוא עד\"מ הרושם שעושין האומני' לבנין גדול<sup data-n=\"349\">349</sup>, שקודם שבונים בנין גדול הרי עושים רשימות קצרות המורה על הבנין ואשר עפ\"ז הם בונים את הבנין, וכדאי' במד\"ר בתחלתו בנוהג שבעולם מלך ב\"ו בונה פלטין אינו בונה אותה מדעת עצמו אלא מדעת אומן, והאומן אינו בונה אותה מדעת עצמו אלא דיפתראות ופנקסאות יש לו לדעת היאך הוא עושה חדרים וכו', היינו ענין התהוות הכלים מהרשימו|314, שהרי",[["347","347","בספר המאמרים ה'שי\"ת שם: שהוא."],["348","348","הקיצור דשנת ה'שי\"ת: כח הגבול הוא כח נעלם ולכן נק' רשימו. וימשיל בכח הזריקה שהוא כח נעלם ונבדל."],["349","349","ראה שער היחוד שם. ספר המאמרים עת\"ר ע' לה ואילך."],["e59","*","<b>מ\"ש בפדר\"א:</b> פ\"ג. וצ\"ע. וראה שמ\"ר רפי\"ג."]]],[2700520558,"הכלים הם ג\"כ בחי' העלם, וכידוע דאור וכלי הוא בחי' גילוי והעלם, שהאור הוא בחי' גילוי, והכלי הוא בחי' העלם, ולזאת שרש הכלים הוא מבחי' הרשימו, שזהו ג\"כ בחי' כח נעלם, וכדאי' בע\"ח שעגו\"י סע\"ג<sup data-n=\"350\">350</sup> שע\"י הצמצום נתגלה הויות הכלי כו', והיינו התגלות בחי' הרשימו, ושזהו שרש ומקור הכלים, והטעם הוא לפי שהתהוות הכלי הוא בבחי' ריחוק דוקא, שהרי כל ענין הכלים הוא להיות בחי' מציאות דבר מה, שזה א\"א להיות מבחי' הגילוי דאוא\"ס, דהיינו מההשפעה שבבחי' קירוב, כ\"א בבחי' ריחוק דוקא, ולזאת התהוות הכלי' הוא מבחי' הרשימו דוקא, שזהו בחי' כח ריחוק דוקא, שזהו בחי' כח נעלם ונבדל מן העצמות, דהיינו בבחי' ריחוק, לכן הנה ההתהוות מזה הוא ג\"כ בבחי' ריחוק ונבדל להיות בבחי' מציאות. וזהו שאמר בפדר\"א נטל צרורות וזרקן ומהם נעשה הארץ, דהיינו בחי' התהוות הכלים שמהרשימו. אמנם לפעמים מבו' דהתהוות הכלים הוא מן האור, וכמ\"ש בע\"ח שער העקודים<sup data-n=\"351\">351</sup> בענין הויות הכלי שזה מהתעבות האור כו', הענין הוא דשרש ומקור התהוות הכלים הוא מן הרשימו, בחי' כח הגבול, אמנם ידוע דכל התהוות צ\"ל ע\"י גילוי וקירוב כח הפועל לפעול, והרי הרשימו הוא בחי' כח נעלם, וא\"כ ה\"ז בחי' ריחוק לבד, וא\"א להיות אשר מזה לבד יהי' התהוות הכלים, כ\"א ע\"י האור שהוא בחי' גילוי, וגם זאת שבכדי שתהי' הכלי בערך האור, שתוכל לקבל בתוכו האור והגילוי, שהרי זהו תכלית הכוונה בהתהוות הכלי' שהאור יתלבש בהם ויאיר בהם בגילוי, הנה משו\"ז צ\"ל ג\"כ ההתהוות ע\"י אמצעית<sup data-n=\"352\">352</sup> האור, דאז הנה לפי אופן גילוי האור כן תהי' הכלי, ולכן הנה המשל על ערך הכלים אל האורות הוא מאותיות השכל ושכל, דלפ\"ע השכל הן האותיות, הגם שהאותיות בעצם הן מקדמות השכל ומעצם הנפש<sup data-n=\"353\">353</sup>, ומ\"מ התהוותם בגילוי הוא ע\"י הגילוים דנפש, כמו אור השכל והמדות, והיינו בכדי שיהיו האותיות לפ\"ע האור, אם אור שכל או אור מדות, לפי אופן כזה יהיו האותיות, וכן הוא בכל אור שכל בפרט, כי יש חילוקים באותיות אם הם כלים אל השכל או אל המדות, וכמו אתוון רברבין או בינונים כו', וכן במדות גופא בבחי' חו\"ג שבהם<sup data-n=\"354\">354</sup>. וכמו\"כ הוא בכלים בכדי שיהי' כלים אל האור, ושיהיו לפ\"ע האור, לזאת הנה התהוותם הוא ע\"י האור, אמנם להיות שהאור הוא בבחי' א\"ס, ואינו בערך שיהי' מאתו התהוות הכלים, וגם בכדי שהאור יהי' בערך בחי' התלבשות בכלים, לזאת הוצרך האור הזה להתצמצם בהרשימו, שהיא מגבלת את האור הבל\"ג. וזהו מה שהקו הנמשך מהרשימו הוא בבחי' קו המדה, שמודד מדידת האורות והכלים, והיינו שמודד אופן גילוי האור, ושלפי אופן כזה יהי' התהוות הכלים, דמדידה זו הרי אין זה באור הקו מצ\"ע, שהרי המשכתו של",[["350","350","שער עגולים ויושר סוף ענף ג."],["351","351","פרק ג."],["352","352","כ\"ה גם בספר המאמרים עת\"ר שבהערה 1. ובספר המאמרים ה'שי\"ת שבהערה הנ\"ל: אמצעות."],["353","353","ראה תניא אגה\"ק ס\"ה."],["354","354","כמ\"ש במ\"א בהביאור דונתתי לך מהלכים [ספר המאמרים עת\"ר שבהערה 1]. - ראה אוה\"ת בראשית ח\"ה תתקיח, ב ואילך. המשך תרס\"ו ע' תמז ואילך."]]],[2700520575,"הקו הוא מהאוא\"ס שלפה\"צ, דהיינו מבחי' הגילוי שהוא בחי' הכח הבל\"ג, כ\"א שמדידה זו זהו ע\"י הרשימו, דרשימו מגביל אור התפשטותו של הקו הבלתי מוגבלת, הנה עי\"ז נעשה אור הקו שאחר צמצום הרשימו בבחי' קו המדה. וז\"ש בע\"ח|350 שאחר הצמצום בא אור הקו במדה ובמשקל, שעי\"ז נעשה בערך להיות ע\"י התהוות הכלי, ולהיות בבחי' אור אל הכלי להתלבש בתוכה, שבזה הוא נותן כח בהכלי שהכלי מגבלת את האור בהתלבשותו בתוכו, שהרי גם לאחר הגבלת הרשימו, מ\"מ הרי האור הוא בבחי' בל\"ג לגבי הכלי, והכלי צריכה להגביל את האור, ולעשות בו ציור ותמונה לפ\"ע מהותה, וכמ\"ש הפרד\"ס<sup data-n=\"355\">355</sup> בשער עצמות וכלים<sup data-n=\"356\">356</sup>, משל על זה ממים הניתנים בכלי זכוכית, או אור השמש המאיר ע\"י הזכוכית שנראים כמראה הזכוכית, הנה כח זה הוא ע\"י הקו שנמשך מהגבלת הרשימו, והעיקר הוא לפי דשרש הכלים הוא מן הרשימו, ולזאת הנה כשם שבחי' רשימו מגבלת את האור הבל\"ג, שבא בבחי' גבול ובבחי' קו המדה, הנה כמו\"כ הכלים מגבילים את האורות. ולפ\"ז יובן דבחי' רשימו והאור המתלבש בהרשימו, היינו האור הבל\"ג שלפני הצמצום שבא בבחי' גבול ומדה ע\"י הרשימו, הרי זה ג\"כ כמו כלי ואור, אלא שזהו ענין כלי ואור בשרש הראשון, ומן הרשימו נמשך הקו בבחי' מדה וגבול, ומהתעבות האור שהיא ההגבלה שהרשימו עושה בהקו נעשה הכלי, והיינו דשרש הכלים בעצם הוא מהרשימו, ומ\"מ הוא לפ\"ע האור, והאור בא לפ\"ע הכלי, ומתלבש בה, והכלי מגבלת את האור, דאז דוקא הרי האור פועל עילוי הכלי, ומהאי טעמא נקראים כלים דאצי' חומר לפי דשרש התהוותם הוא מהרשימו שהוא כח נעלם.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר דרשימו מגביל גם את האור הבל\"ג, והמשל מרשימת ציור הבנין קודם הבנותו, רשימו הוא כח נעלם והוא שרש התהוות הכלים, ולכן הכלים מעלימים על האורות להיותם כחות נעלמים, והתהוותם בפועל ע\"י האור, קירוב הפועל אל הנפעל, אותיות המושכל לפי מעלת אורו, הקו להיותו בא מן וע\"י הרשימו לזאת מודד מדידת האורות והכלים.</span>\n<b>ענינים.</b> טו רשימו, א) כרושם על בנין, ב) שרש לכלים.\n<b>וזהו</b> בסכת תשבו שבעת ימים כו', דסוכה הוא המשכה מבחי' אוא\"ס הבל\"ג, דבסוכה עיקרה הסיכוך שהוא מקיף, דשרש ההמשכה הוא מבחי' אוא\"ס הבל\"ג, דהגילוים שבסוכות הוא מהעבודה ותשובה דר\"ה ויוהכ\"פ שמעוררים בבחי' עצמות אוא\"ס ב\"ה, וההמשכה והגילוי מזה הוא בסכת, שזהו בחי' וימינו<sup data-n=\"357\">357</sup> תחבקני<sup data-n=\"e60\">*</sup>,",[["355","355","כ\"ה (פרד\"ס - עם מירכאות כפולות) בכ\"מ. וראה \"הערות ותיקונים\" ו\"מ\"מ, הגהות והערות קצרות\" לתניא ספמ\"ח."],["356","356","פרק ד."],["357","357","שיר השירים ב, ו."],["e60","*","<b>בחי' וימינו תחבקני:</b> ראה לקו\"ת פ' נצבים ד\"ה שוש אשיש פ\"ה [מח, ג]."]]],[2700520588,"וע\"י הד\"מ שבלולב דכולם מורים על היחוד והאחדות<sup data-n=\"e61\">*</sup> ממשיכים זה בפנימי', והכלי לזה הוא השמחה דתורה. וזהו בסכת תשבו שבעת ימי', דהמשכה זו צריכים להמשיכה גם בהמדות דז\"א ומל', שהוא הגילוי בעולם, ובעבודה הכוונה לעשות מדותיו לכלים מקבלי אור, דזהו שבעת ימים תשבו בסכת, דעי\"ז שנתגלה כח הגבול שבא\"ס, הוא שרש ומקור לבריאת והתהוות העולמות, ושיהיו תומ\"צ מלובשי' בדברים גשמים, הרי כח הגבול מגביל גם את האור הבל\"ג, דע\"י התומ\"צ ממשיכים בחי' האוא\"ס שלפני הצמצום, והמשכה זו צריכה לפעול בעולם ובכחות נפשו שזהו\"ע השבעת ימים. וכל האזרח בישראל ישבו בסוכות, שהם יושבים תמיד בסוכה, שהוא בחינת<sup data-n=\"e62\">*</sup> הפנימיות והעצמיות, שעוד למעלה גם מבחי' עליית הרצון הפשוט הנ\"ל. וזהו מלמד דכל ישראל ראוים לישב בסוכה אחת, דע\"י העבודה דשבעת הימים, הנה ממשיכים בהעלם גם בחי' ומדריגה זו, ועיקר הגילוי יהי' לע\"ל, והכלים לזה הוא הסוכה והד\"מ שבלולב, שהם מצוה מן המובחר להיות בסוכה דוקא<sup data-n=\"358\">358</sup>, דעי\"ז זוכים לסוכה אחת, ובעבודה הו\"ע להמשיך בעולם התחתון בחי' גילוי אחדותו ית'<sup data-n=\"359\">359</sup>.\n<b>סיום.</b> מצות מלובשים בגשמיות לעשותם כלים לאלקות, ובהם מתגלה הבל\"ג שהוא הישיבה במקיף במספר ז' מדות. וזהו שהאזרח מאיר בל\"ג ומצד עצם הנשמה כל ישראל יושבים במקיף אחד.\n-------------------- * --------------------",[["358","358","ראה לקוטי שיחות חלק כב ע' 124. וש\"נ."],["359","359","הקיצור דשנת ה'שי\"ת: הרשימו מגביל את האור הבל\"ג. שרש התהוות הכלים הוא מהרשימו כי הם ג\"כ בריחוק. יסביר דכל התהוות צ\"ל ע\"י גילוי וקירוב, גם הכלים צ\"ל לפ\"ע האור, ולכן התהוותם באמצעות האור. האור נעשה קו המדה ע\"י הרשימו, וכן הכלים מגבילים את האור."],["e61","*","<b>על היחוד והאחדות:</b> באריכות בסידור שער הלולב [רסב, ב ואילך]. בהמשך וככה תרל\"ז פפ\"ז [ע' קמב]. ועוד."],["e62","*","<b>שהוא בחינת:</b> ראה לקו\"ת ד\"ה ביום השמע\"צ (השני) פ\"ג [פב, ב]. ד\"ה ה' לי בעוזרי פ\"ב [פח, ג]."]]],[2700520060,"<b>ביום</b> השמיני עצרת תהי' לכם<sup data-n=\"360\">360</sup>, ואי' במד\"ר (שמות פט\"ו פיסקא כ\"ג) הה\"ד (משלי ה'<sup data-n=\"361\">361</sup>) יהיו לך לבדך ואין לזרים אתך, לא נתתי המשפט אלא לכם שנא' (הושע ה'<sup data-n=\"362\">362</sup>) שמעו זאת הכהנים והקשיבו בית ישראל ובית המלך כי לכם",[["360","360","פינחס כט, לה."],["361","361","פסוק יז."],["362","362","פסוק א (ושם: ובית המלך האזינו)."]]],[2700520110,"המשפט, הצדקה שלכם שנא' (דברים כ\"ד<sup data-n=\"363\">363</sup>) ולך תהי' צדקה, הרחמים שלכם שנא' (שם י\"ג<sup data-n=\"364\">364</sup>) ונתן לך רחמים ורחמך והרבך כו', הברכות לכם שנא' (במדבר ו'<sup data-n=\"365\">365</sup>) יברכך ה' וישמרך וכן (ויקרא כ\"ה<sup data-n=\"366\">366</sup>) וצויתי את ברכתי לכם, לא נתתי התורה אלא לכם שנא' (משלי ד'<sup data-n=\"367\">367</sup>) כי לקח טוב נתתי לכם וגו', וכן מחשב שם במד\"ר כמה מצות שנא' בהם לשון לכם, וכמו ולקחתם לכם<sup data-n=\"368\">368</sup>. וצ\"ל והלא כל המצות ניתנו רק לישראל<sup data-n=\"369\">369</sup>, דזהו ההפרש בין המצות שקיימו האבות להמצות שנתנו במתן תורה, דהנה אמרז\"ל (יומא דכ\"ח ע\"ב) אמר רב קיים אברהם אבינו כל התורה כולה שנא'<sup data-n=\"370\">370</sup> עקב אשר שמע אברהם בקולי וגו', אמנם כל קיומן של מצות אלו שקיימו האבות הן ברוחניות, וכמארז\"ל<sup data-n=\"371\">371</sup> (מד\"ר שה\"ש פ\"א פיסקא כ'<sup data-n=\"372\">372</sup>) כל השירים שאמרו לפניך האבות ריחות היו (כלומר כעין ריח בעלמא. מ\"כ) אבל אנו שמן תורק שמך<sup data-n=\"373\">373</sup> כאדם שמריק מכלי לכלי חבירו (שנותן לו השמן בעצמו. מ\"כ), כל המצות שעשו לפניך האבות ריחות היו אבל אנו שמן תורק שמך, רמ\"ח מ\"ע שס\"ה מל\"ת. דהנה בכל מצוה בכלל הנה לבד זאת שבה ועל ידה מתחבר האדם עם אוא\"ס ב\"ה<sup data-n=\"374\">374</sup>, דהאדם כמו שהוא למטה בגוף גשמי ובעניניו הגשמיים ה\"ה רחוק מרוחניות בכלל ובפרט מעניני אלקות, וכמו עד\"מ בגשמיות הנה האיש הפשוט שאינו יודע תורה ואינו בעל חושים בהשכלה וחכמה או איזה ידיעה בידיעת המושכלות ה\"ה אינו תופס מקום כלל לגבי החכם המופלג בחכמה ונמשל כדומם ממש, וביטול זה הרי אין זה מה שהחכם מבטלו אלא שהוא באופן כזה שאינו עולה בשם ביטול כלל, דענין הביטול הוא מה שלעצמו הוא איזה דבר אלא שהוא בטל וטפל, אבל הפשיטות דאיש הפשוט אינו דבר כלל לגבי החכם המופלג שיבטלו, אלא שהוא בטל באמת כאילו אינו כלל, וביטול והעדר המציאות אינו מצד החכם אלא גם מצד האיש הפשוט, שהוא בעצמו יודע העדר מציאותו לגמרי מכל וכל כאלו אינו במציאות, וכאשר החכם המופלג מדבר איזה דיבור עם האיש הפשוט ומצוה לו לעשות איזה דבר, הרי בדיבור זה הוא עושה את האיש הפשוט למציאות דבר, כי מצד עצם ענינו של האיש הפשוט הרי לגבי החכם הוא כגולם דוממי, ובהדיבור הזה שמדבר עמו מוציאו מן ההעדר",[["363","363","פסוק יג."],["364","364","פסוק יח."],["365","365","פסוק כד."],["366","366","פסוק כא."],["367","367","פסוק ב."],["368","368","אמור כג, מ."],["369","369","ראה גם ד\"ה ביום השמע\"צ תשכ\"ט (ספר המאמרים תשכ\"ט ע' מ ואילך)."],["370","370","תולדות כו, ה."],["371","371","ראה ספר המאמרים תרס\"ב ע' רסה ואילך. תרע\"ח ע' קסד ואילך. תש\"ו ע' 94 ואילך. ועוד."],["372","372","כ\"ה במד\"ר דפוס ווארשא, תרכ\"ז. ובדפוס ווילנא - פיסקא ג."],["373","373","שיר השירים א, ג."],["374","374","ראה גם לקמן ע' קעו. ספר המאמרים תרח\"ץ ע' נב. ה'ש\"ת ע' 73 ואילך. אגרות-קודש אדמו\"ר מהוריי\"צ חלק י ע' שסט ואילך. לקוטי שיחות חלק ז ע' 30 ואילך."]]],[2700520160,"והאפיסה אל המציאות, שנעשה איזה מציאות דבר בדיבור זה שהחכם דיבר עמו, וכאשר בדיבורו של החכם יש איזה ציווי לעשות, הנה גם אם הציווי ההוא אינו שייך אל החכם ה\"ה ג\"כ נעשה האיש הפשוט מקורב אל החכם, ובפרט כאשר הציווי ההוא משלים רצונו של החכם ה\"ז עילוי גדול אל האיש הפשוט שנתעלה במדריגה ובמעלה גבוה מן האפס הגמור אל מציאות מעולה להשלים רצונו של חכם מופלג. וככל המשל הזה הנה ביתר שאת יובן בענין המצות, דמצוה הוא צוותא וחיבור<sup data-n=\"375\">375</sup>, דהאדם הנה גם בהיותו למטה בגוף גשמי ובעניניו הגשמיים ה\"ה מתחבר עם עצמות אוא\"ס בעל הרצון דציוים שבמצות<sup data-n=\"376\">376</sup>, הנה לבד זאת הרי כל מצוה ומצוה יש לה סגולה פרטית לאכפייא להנה\"ב ולנתקו מעניני העולם ולבררו, דזהו כן בכל המצות בכל, בפרט<sup data-n=\"377\">377</sup> בענין פרטי כמו שהוא ענינה של מצוה ההיא, והיינו דכל המצות בכלל הנה לבד הצוותא וחיבור שנעשה על ידן כנ\"ל הרי יש הזדככות הכללי שנעשה ע\"י המצות בכלל וכמאמר<sup data-n=\"e63\">*</sup> אמר רב לא נתנו המצות אלא לצרף בהן את הבריות, הנה לבד זאת הרי בכל מצוה ומצוה יש ענין וסגולה פרטית, וכמו במצות תפילין לשעבד המוח והלב<sup data-n=\"378\">378</sup> ושיבוא מעשה הטוב בפועל, וכן הוא בכל מצוה בפרט, וא\"כ מהו היתרון בהמצות שנאמר בהם לשון לכם. ועוד זאת מהו המצוה פרטית שנאמר כאן שאומר ביום השמיני עצרת תהי' לכם, דלכאו' הרי אין כאן שום פועל ועבודה כלל, ובשמע\"צ עושים ש\"ת וענינה שלוקחים הס\"ת ומקיפים שולחן הקריאה ורוקדים עמה בשמחה גדולה זקנים ונערים, דלכאו'<sup data-n=\"379\">379</sup> הרי תורה הו\"ע ידיעה והשגה, והי' ראוי הדבר אשר בשמח\"ת היו לומדים תורה ובעיון גדול דוקא, ומפני מה כל העבודה דשמח\"ת היא בריקודים ביגיעה עצומה עד שיזיע דוקא, וכולם שוים מבלי הבדל והפרש יושבי אהל ובעלי עסקים.\n<b>ולהבין</b> כ\"ז ילהק\"ת משנת\"ל דדוגמת חומר וצורה דנבראי' הוא גם באצי' דאו\"כ הם חומר וצורה, דכלים דאצי' הם בחי' חומר, וטעם הדבר לפי דשרש התהוותם הוא מהרשימו, ונת' דהרשימו הוא כח הגבול שבא\"ס, שלפני הצמצום הי' מכוסה ונעלם בהאור הבל\"ג שהאיר, והם האותיות שהאיר בהם אוא\"ס הבל\"ג, וע\"י",[["375","375","לקו\"ת בחוקותי מה, ג. מקומות שצויינו בהערה 14."],["376","376","בספר המאמרים ה'שי\"ת שבהערה :1 דציום במצות."],["377","377","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שם: בכלל, ובפרט."],["378","378","שו\"ע או\"ח סכ\"ה ס\"ה. שו\"ע אדמו\"ר הזקן שם סי\"א. סידור אדמו\"ר הזקן סדר הנחת תפילין. תניא פמ\"א (נו, ב)."],["379","379","ראה גם רד\"ה ביום השמע\"צ תרפ\"ו (ספר המאמרים תרפ\"ו ס\"ע נה). תרפ\"ט (ספר המאמרים תרפ\"ט ע' 57). תרצ\"ו (ספר המאמרים תרצ\"ו ע' 41). רד\"ה עץ חיים תרצ\"ט (ספר המאמרים תרצ\"ט ע' 68). רד\"ה להבין ענין שמחת תורה תש\"ה (ספר המאמרים תש\"ה ע' 69). תש\"ו (ספר המאמרים תש\"ו ע' 40). תשל\"ח (ספר המאמרים מלוקט ח\"א ע' רנט. בהוצאה החדשה - ע' רי). וראה גם מאמרי אדמו\"ר הזקן הקצרים ריש ע' רד."],["e63","*","<b>וכמאמר:</b> בראשית רבה פמ\"ד [פיסקא א]."]]],[2700520210,"הצמצום נתגלו האותיות ונשאר הרשימו מהאור הבל\"ג, אמנם מאחר דזהו רשימו מהאור הקודם וגם כח הגבול שבא\"ס הוא בבחי' א\"ס בגבול כמו הבל\"ג ממש, א\"כ למה נקרא בשם רשימו, וביאר כי בגילוים, כלומר לאחר הצמצום, היינו בסדר ההשתל', הנה הגבול אינו בערך לבל\"ג, דגבול הוא העלם ובל\"ג גילוי, אשר כן הוא לפני הצמצום שהוא כח נעלם, ולזאת הגם שהוא בבחי' א\"ס לכן<sup data-n=\"380\">380</sup> נקרא רשימו, ולכן המשל על רשימו הוא מכח הזריקה, ויבאר הפרש תנועת הזריקה מתנועת המלאכה והציור, וענין הרשימו שמגביל גם האור הבל\"ג, והוא שרש התהוות הכלים, לפי שהרשימו בכללותה כלומר האותיות הם בענינם כדוגמת כלי ואור בעת שהאיר בהם אוא\"ס הבל\"ג, וביאר כי באותיות החקיקה יש הפרש בין חקיקה ע\"ג אב\"ט שהם האותיות דטה\"ת שהם שרש נשמות דגופות לאותיות הנחקקים מעבר לעבר אותיות דטה\"ע שלפני הצמצום, והם שרש ומקור הראשון דכלים, וכמובן הרי רשימו עצמו בעיקרו הוא האור שנשאר, ולכן הנה גמר התהוות הכלים הוא ע\"י האור, והוא אור הקו שנמשך ע\"י הרשימו, דשרש המשכתו העצמית הוא מלפני הצמצום, אמנם בזה שבא ע\"י הרשימו הרי נעשה קו המדה במדידת האורות והכלים, ולכן הקו נותן כח בהכלי שמקבלת<sup data-n=\"381\">381</sup> את האור לפי צורתה, דעי\"ז הנה האור המתגלה בהכלי מאיר את הכלי, וזהו דרשימו הוא שרש ומקור התהוות הכלים, ולכן הכלים דאצי' נקראי' חומר לפי דשרש התהוותם הוא מבחי' כח נעלם שהוא בחי' רשימו.\nלב) <b>והנה</b><sup data-n=\"382\">382</sup> מכל המבואר מובן דרשימו הוא שם כולל להאותיות דטה\"ע שהם כח הגבול שבא\"ס ב\"ה והאור שנשאר בהם מהאור הבל\"ג שהאיר לפני הצמצום. ובאמת יש עוד ברושם זה יתרון על אור הקודם, דאור הקודם הוא גילוי אוא\"ס הבל\"ג, וכנ\"ל דאין הפרש והבדל בין כח הגבול שבא\"ס לכח הבל\"ג שבא\"ס, דשניהם הם בבחי' א\"ס אלא דזה כחו ית' בבלי גבול וזה כחו ית' בגבול, אמנם רשימו זו היא באה בכוונה מיוחדה בכוונת המכוין ית' ויתעלה, שבזה יתרון אור הרשימו על אור הקודם, ולכן הנה הגם דרשימו כולל ב' הענינים, האותיות ואור הרושם, מ\"מ נקרא בשם רשימו לפי שהעיקר הוא האור<sup data-n=\"383\">383</sup>. ובזה יובן מ\"ש בפרד\"ס|355 שער כ\"ז פכ\"ז כי הרשימה יותר דק מהחקיקה<sup data-n=\"384\">384</sup>, והוא כתב זה בענין האותיות שיש בזה מדריגות חלוקות רשימה חקיקה חציבה ועשי'<sup data-n=\"385\">385</sup>, ויובן בענינינו כי הרשימו שהוא האור הוא נעלה יותר מהחקיקה שהם האותיות כנ\"ל. אמנם לפ\"ז א\"מ מפני מה הרשימו הוא שרש ומקור להתהוות הכלים. אך הענין הוא דהנה נת\"ל<sup data-n=\"386\">386</sup> דרשימו הוא כעין הרושם לבנין גדול, שהרושם אינו מענין הבנין כלל ודבר זר ממנו, מ\"מ",[["380","380","בספר המאמרים ה'שי\"ת שם - ליתא תיבה זו."],["381","381","כ\"ה בכתי\"ק ובהעתקה. בספר המאמרים ה'שי\"ת שבהערה :1 שמגלה."],["382","382","ראה לקמן הוספה א בסוף הספר (ע' תקנג ואילך)."],["383","383","ראה גם ד\"ה חסידים ואנשי מעשה תשכ\"ט (ספר המאמרים תשכ\"ט ע' לה ואילך)."],["384","384","ראה לקו\"ת הוספות לויקרא נד, א. המשך תרס\"ו ע' תקט ואילך."],["385","385","בענין \"רשימה חקיקה חציבה עשי'\" - ראה גם מאמרי אדמו\"ר הזקן ענינים ע' שפח ואילך."],["386","386","פרק ל (לעיל ע' עד)."]]]]});
